window.BASAIR_QUESTIONS=window.BASAIR_QUESTIONS.concat([{"id":"s2-467","number":467,"surah":2,"verses":[122],"verseLabel":"البقرة: 122","question":"ما سرّ التعبير في قوله تعالى: ﴿أَنْعَمْتُ عَلَيْكُمْ﴾ بحرف ﴿على﴾، دون أن يقال: «أنعمت إليكم»؟","answer":"﴿على﴾ تستحضر علو مصدر النعمة وانصبابها عليهم وكثرتها ودوام آثارها؛ فهي ليست عطيةً وصلت ثم انقطعت، بل إحسان نزل من عند الله وأحاط بالمخاطبين. وهذا أدعى إلى الطمأنينة والشكر لمن عرف مصدر النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص221–223، تحت البقرة: 122، في تعدية ﴿أنعم﴾ بحرف الاستعلاء.","url":""}]},{"id":"s2-468","number":468,"surah":2,"verses":[123],"verseLabel":"البقرة: 123","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا تَجْزِي نَفْسٌ عَنْ نَفْسٍ شَيْئًا﴾، دون أن يقال: «لا تجزي روح عن روح»؟","answer":"النفس هي صاحبة الكسب التي تنسب إليها الطاعة والمعصية ويقع عليها الحساب والجزاء، أما الروح فهي سر الحياة ولا تنسب إليها الأعمال بهذا الاعتبار. لذلك يختار القرآن لفظ النفس في مواطن المسؤولية الأخروية؛ فهي التي صنعت الاختيار وتواجه نتيجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص228–230، تحت البقرة: 123، في الفرق بين النفس والروح وسر إيثار النفس في الحساب.","url":""}]},{"id":"s2-469","number":469,"surah":2,"verses":[123],"verseLabel":"البقرة: 123","question":"ما سرّ ترتيب وسائل النجاة المنفية في قوله تعالى: ﴿لَا تَجْزِي نَفْسٌ... وَلَا يُقْبَلُ مِنْهَا عَدْلٌ وَلَا تَنْفَعُهَا شَفَاعَةٌ وَلَا هُمْ يُنْصَرُونَ﴾؟","answer":"نفت الآية وسائل الخلاص المعهودة مرتبة: أن يؤدي غيره الحق عنه، ثم أن يقدم فدية، ثم أن تنفعه شفاعة، ثم أن تنقذه قوة ناصرة؛ فاستوعبت وجوه النجاة المتوهمة وقطعتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص231–233، تحت البقرة: 123، في بلاغة ترتيب المنفيات الأربع.","url":""}]},{"id":"s2-470","number":470,"surah":2,"verses":[123],"verseLabel":"البقرة: 123","question":"ما دلالة قوله تعالى: ﴿وَلَا هُمْ يُنْصَرُونَ﴾ بذكر الضمير، دون أن يقال: «ولا يُنصرون»؟","answer":"تقديم ﴿هم﴾ يزيد نفي النصرة توكيدًا، والبناء للمجهول يغيّب أي ناصر محتمل، وتكرار ﴿لا﴾ يجعل هذا الباب منفيًا مستقلًا بعد الفدية والشفاعة. هكذا تنتهي الآية بقطع آخر وهم يمكن أن يتعلق به المكذب.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص232–233، تحت البقرة: 123، في بلاغة الفاصلة وتقديم المسند إليه والبناء للمجهول.","url":""}]},{"id":"s2-471","number":471,"surah":2,"verses":[124],"verseLabel":"البقرة: 124","question":"ما سرّ التعبير في قوله تعالى: ﴿وإذ ابتلى إبراهيم ربه﴾ باسم الربوبية؟","answer":"الابتلاء هنا تربية وارتقاء من الرب لعبده حتى يبلغ الإمامة، لا امتحان من يجهل النتيجة؛ فاسم الرب يبرز الرعاية داخل التكليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص244، تحت البقرة: 124.","url":""}]},{"id":"s2-472","number":472,"surah":2,"verses":[124],"verseLabel":"البقرة: 124","question":"ما سرّ التعبير في قوله تعالى: ﴿بكلمات﴾ جمع قلة، مع كثرة ما ابتُلي به إبراهيم؟","answer":"جاءت ﴿كلمات﴾ على جمع القلة، دون «كلام»، للإشارة إلى قلة التكاليف ويسرها ولطف الله فيها، وإن كان شأنها عظيمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص246، تحت البقرة: 124.","url":""}]},{"id":"s2-473","number":473,"surah":2,"verses":[124],"verseLabel":"البقرة: 124","question":"ما سرّ التعبير في قوله تعالى: ﴿فأتمهن﴾ بالتمام لا بالكمال؟","answer":"الإتمام يدل على أن إبراهيم مضى في أداء الكلمات ولم ينقطع أو يفتر حتى استوفاها؛ وهذا هو الملائم لسياق الابتلاء والامتثال.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص247، تحت البقرة: 124.","url":""}]},{"id":"s2-474","number":474,"surah":2,"verses":[124],"verseLabel":"البقرة: 124","question":"ما سرّ التعبير في قوله تعالى: ﴿إني جاعلك للناس إمامًا﴾، دون أن يقال: رسولًا؟","answer":"الإمامة أعم أثرًا من مجرد تبليغ الرسالة؛ إذ ينتفع به قومه بالمباشرة، وتقتدي به الأمم بعده، فناسب مقام القدوة العامة قوله: ﴿لِلنَّاسِ إِمَامًا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص249، تحت البقرة: 124.","url":""}]},{"id":"s2-475","number":475,"surah":2,"verses":[124],"verseLabel":"البقرة: 124","question":"ما سرّ إسناد النيل إلى العهد في قوله تعالى: ﴿لَا يَنَالُ عَهْدِي الظَّالِمِينَ﴾؟","answer":"أُسند النيل إلى العهد، فالمعنى: لا يصيب عهدي الظالمين ولا يشملهم. وفي اختيار لفظ ﴿عهدي﴾ تعريض بمن نقضوا عهد الله؛ فالإمامة لا تشمل الظالم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص249–253، تحت البقرة: 124.","url":""}]},{"id":"s2-476","number":476,"surah":2,"verses":[124],"verseLabel":"البقرة: 124","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِذِ ابْتَلَى إِبْرَاهِيمَ رَبُّهُ﴾ فقدم إبراهيم على الفاعل ﴿ربه﴾؟","answer":"قُدّم إبراهيم لأنه المقصود بالعناية في القصة، ولئلا يعود الضمير في ﴿ربه﴾ على متأخر لفظًا قبل ذكر مرجعه. ثم أضيف الرب إليه لإظهار معنى التربية والرعاية في الابتلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص234–241، تحت البقرة: 124، في ترتيب صدر الآية وإضافة الرب إلى إبراهيم.","url":""}]},{"id":"s2-477","number":477,"surah":2,"verses":[124],"verseLabel":"البقرة: 124","question":"ما سرّ التعبير في قوله تعالى: ﴿فَأَتَمَّهُنَّ﴾ بالفاء؟","answer":"الفاء تصور سرعة إبراهيم في الامتثال؛ فما إن جاء التكليف حتى أعقبه الإتمام بلا تراخٍ أو تسويف. فاختصرت حرفٌ واحد مسافةً كاملة بين الأمر والعمل، وصار مدح إبراهيم في المبادرة ظاهرًا قبل أن يذكر جزاؤه بالإمامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص245–246، تحت البقرة: 124، في دلالة الفاء على الفور في الامتثال.","url":""}]},{"id":"s2-478","number":478,"surah":2,"verses":[124],"verseLabel":"البقرة: 124","question":"ما سرّ التعبير في قوله تعالى بعد الابتلاء: ﴿قَالَ إِنِّي جَاعِلُكَ لِلنَّاسِ إِمَامًا﴾، دون أن يقال: «فقال»؟","answer":"الفصل يشعر بأن الإمامة منحة إلهية مستقلة بمحض الاصطفاء، لا نتيجة آلية يملكها الإنسان بمجرد العمل. نعم جاءت بعد نجاح الابتلاء جزاءً وتشريفًا، لكنها تظل فضلًا من الله ورسالة لا تنال بالكسب وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص248–250، تحت البقرة: 124، في الفصل بين الجمل وحذف الفاء قبل ﴿قال﴾.","url":""}]},{"id":"s2-479","number":479,"surah":2,"verses":[124],"verseLabel":"البقرة: 124","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنِّي جَاعِلُكَ﴾ باسم الفاعل، دون أن يقال: «سأجعلك»؟","answer":"اسم الفاعل يصور الجعل مستقبلًا محققًا كأنه قائم حاصل لا يشوبه شك، وهو أوكد من مجرد وعد بالفعل. فالإمامة ليست احتمالًا ينتظر الظروف، بل أمر قضاه الله بعد نجاح إبراهيم في الابتلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص249–251، تحت البقرة: 124، في العدول عن الفعل المستقبل إلى اسم الفاعل ﴿جاعلك﴾.","url":""}]},{"id":"s2-480","number":480,"surah":2,"verses":[124],"verseLabel":"البقرة: 124","question":"ما دلالة تقديم ﴿للناس﴾ في قوله تعالى: ﴿إِنِّي جَاعِلُكَ لِلنَّاسِ إِمَامًا﴾؟","answer":"التقديم يبرز سعة الإمامة واختصاص أثرها بالناس جميعًا، لا بجماعة محلية واحدة. ومن ذريته جاءت النبوات بعده، وصار قدوة تتجاوز زمنه ومكانه؛ فقدم نطاق الرسالة قبل لقبها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص249–251، تحت البقرة: 124، في تقديم الجار والمجرور ﴿للناس﴾.","url":""}]},{"id":"s2-481","number":481,"surah":2,"verses":[124],"verseLabel":"البقرة: 124","question":"لماذا لم يقل إبراهيم مباشرة: «واجعل ذريتي أئمة»، بل قال: ﴿وَمِنْ ذُرِّيَّتِي﴾؟","answer":"عدل إلى عبارة خبرية قصيرة تحمل الطلب بأدب، فلم يأمر ربه ولم يصرح باستحقاق ذريته، بل عرض رجاءه بلطف: واجعل من ذريتي. وفيها حرص الأب على صلاح نسله مع بقاء مقام العبودية والتسليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص251–252، تحت البقرة: 124، في العدول من الطلب المباشر إلى قوله ﴿ومن ذريتي﴾.","url":""}]},{"id":"s2-482","number":482,"surah":2,"verses":[124],"verseLabel":"البقرة: 124","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ ذُرِّيَّتِي﴾، دون أن يقال: «وذريتي»؟","answer":"﴿من﴾ للتبعيض؛ فإبراهيم لم يسأل الإمامة لجميع نسله على اختلاف أحوالهم، وإنما لمن يصلح منهم للاقتداء. فجاء الدعاء موافقًا للحكمة والواقع، ومهّد للجواب الذي يستبعد الظالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص251–253، تحت البقرة: 124، في دلالة ﴿من﴾ على التبعيض وفقه الدعاء.","url":""}]},{"id":"s2-483","number":483,"surah":2,"verses":[124],"verseLabel":"البقرة: 124","question":"ما سرّ مجيء الجواب عن طلب إبراهيم بقوله تعالى: ﴿لَا يَنَالُ عَهْدِي الظَّالِمِينَ﴾، دون جواب مباشر بنعم أو لا؟","answer":"جاء الجواب بذكر المانع لا بمجرد القبول أو الرفض، ليضع قاعدة باقية لكل الأجيال: النسب إلى إبراهيم لا يكفي، والظلم يمنع صاحبه من عهد الإمامة. وفي هذا إيجاز يجيب الدعاء ويهذب الذرية ويحذر كل من يطلب القيادة بلا عدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص252–253، تحت البقرة: 124، في إيثار ذكر الظلم والعدول عن الجواب المباشر.","url":""}]},{"id":"s2-484","number":484,"surah":2,"verses":[125],"verseLabel":"البقرة: 125","question":"ما سرّ التعبير عن البيت بأنه ﴿مَثَابَةً لِلنَّاسِ﴾، دون «مرجعًا»؟","answer":"المثابة تتضمن الرجوع والثواب، وتفيد تكرر عودة الناس إلى البيت مع الشوق إليه؛ فهي أبلغ من لفظ يدل على مطلق الرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص261، تحت البقرة: 125.","url":""}]},{"id":"s2-485","number":485,"surah":2,"verses":[125],"verseLabel":"البقرة: 125","question":"ما سرّ التعبير في قوله تعالى: ﴿للناس﴾ لا: للمسلمين؟","answer":"لأن حرمة البيت وأصله الإبراهيمي وآية الأمن موجهة للبشر، ودعوته سابقة على التقسيمات اللاحقة؛ ثم ينتفع بها المؤمنون أتم انتفاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص262، تحت البقرة: 125.","url":""}]},{"id":"s2-486","number":486,"surah":2,"verses":[125],"verseLabel":"البقرة: 125","question":"ما سرّ التعبير في قوله تعالى: ﴿البيت﴾ مجردًا من الوصف، مع أنه البيت الحرام؟","answer":"أطلق عليه ﴿البيت﴾ لأنه صار علمًا معروفًا للبناء الذي اختاره الله لعبادته، وهو أول بيت وضع للناس وموضع الأمن؛ فلا يحتاج في السياق إلى وصف يميزه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص261، تحت البقرة: 125.","url":""}]},{"id":"s2-487","number":487,"surah":2,"verses":[26],"verseLabel":"البقرة: 125، الحج: 26","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة عند تطهير البيت: ﴿لِلطَّائِفِينَ وَالْعَاكِفِينَ﴾، وقوله تعالى في الحج: ﴿لِلطَّائِفِينَ وَالْقَائِمِينَ﴾؟","answer":"سبق في آية الحج نفسها ذكر ﴿العاكف فيه والباد﴾، فعدل عن إعادة مادة العكوف إلى ﴿القائمين﴾، فجمع تجنب التكرار وإضافة معنى جديد: دوام القيام بالصلاة أو الإقامة بجوار البيت. أما البقرة فلم يسبق فيها لفظ العكوف في هذا السياق، فذكر ﴿العاكفين﴾ تصريحًا بأهل الملازمة والإقامة؛ وهكذا يفسر كل موضع جانبًا من عبادة المقيمين عند البيت.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص501–502، تحت الحج: 26، في المقارنة بالبقرة: 125.","url":""}]},{"id":"s2-488","number":488,"surah":2,"verses":[125],"verseLabel":"البقرة: 125","question":"ما دلالة إعادة ﴿إذ﴾ في قوله تعالى: ﴿وَإِذْ جَعَلْنَا الْبَيْتَ﴾ بعد قوله: ﴿وَإِذِ ابْتَلَى إِبْرَاهِيمَ﴾؟","answer":"لأن كل مشهد جدير بأن يستقل بالتذكر: الأول ابتلاء إبراهيم ورفعه إلى الإمامة، والثاني جعل البيت مثابةً وأمنًا وما ترتب عليه من شعائر. فتكرار ﴿إذ﴾ ينبه إلى انتقال جديد، ويربط تكريم البيت بنجاح بانيه في الابتلاء من غير أن يذيب الحدثين في جملة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص253–255، تحت البقرة: 125، في دلالة إعادة الظرف ﴿إذ﴾.","url":""}]},{"id":"s2-489","number":489,"surah":2,"verses":[125],"verseLabel":"البقرة: 125","question":"ما سرّ التعبير في قوله تعالى: ﴿وَأَمْنًا﴾ بالمصدر، دون أن يقال: «وآمنًا»؟","answer":"الإخبار بالمصدر للمبالغة؛ فكأن البيت نفس الأمن لا مجرد مكان متصف به. وهذا يصور رسوخ الحرمة وامتداد الطمأنينة إلى من دخله وما حوله، ويجعل الأمن وظيفةً أصيلة في بنائه لا صفة عارضة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص259–261، تحت البقرة: 125، في التعبير بالمصدر ﴿أمنًا﴾.","url":""}]},{"id":"s2-490","number":490,"surah":2,"verses":[125],"verseLabel":"البقرة: 125","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ مَقَامِ إِبْرَاهِيمَ مُصَلًّى﴾، دون أن يقال: «من مكان إبراهيم»؟","answer":"المقام يحمل أثر القيام والمكث والعبادة، ويربط الموضع بتاريخ إبراهيم وهو يرفع البيت ويؤدي النسك؛ أما «المكان» فلفظ جغرافي أعم لا يستحضر هذه السيرة. فاختير ما يحوّل الحجر من نقطة إلى شاهد على الطاعة والاقتداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص261–263، تحت البقرة: 125، في إيثار لفظ المقام دون المكان.","url":""}]},{"id":"s2-491","number":491,"surah":2,"verses":[125],"verseLabel":"البقرة: 125","question":"ما سرّ التعبير في قوله تعالى: ﴿وَعَهِدْنَا إِلَى إِبْرَاهِيمَ وَإِسْمَاعِيلَ﴾ بحرف ﴿إلى﴾؟","answer":"لأن العهد هنا وصية مؤكدة أُلقيت إليهما ليقوما بتنفيذها، لا مجرد اتفاق متبادل يقال فيه «عهدنا معهما». فـ﴿إلى﴾ تصور وصول التكليف من الآمر الأعلى إلى القائمين على البيت، وتبرز أمانة العمل وشدة حرصهما على أدائها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص262–264، تحت البقرة: 125، في تعدية فعل العهد بحرف ﴿إلى﴾.","url":""}]},{"id":"s2-492","number":492,"surah":2,"verses":[125],"verseLabel":"البقرة: 125","question":"ما سرّ التعبير في قوله تعالى: ﴿طَهِّرَا بَيْتِيَ﴾ فأضاف البيت إلى نفسه؟","answer":"الإضافة للتشريف والاختصاص، لا لأن الله يحل في مكان؛ فالبيت بيت عبادته وتوحيده. وحين يسمع إبراهيم وإسماعيل ﴿بيتي﴾ يصير التطهير عنايةً بما أضافه الله إليه، كما تصبح الإضافة سببًا لجذب قلوب الناس إلى هذا الموضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص264–265، تحت البقرة: 125، في إضافة البيت إلى ياء المتكلم.","url":""}]},{"id":"s2-493","number":493,"surah":2,"verses":[125],"verseLabel":"البقرة: 125","question":"ما سرّ ترتيب أصناف العابدين في قوله تعالى: ﴿لِلطَّائِفِينَ وَالْعَاكِفِينَ وَالرُّكَّعِ السُّجُودِ﴾؟","answer":"رُتبت الأصناف من الأقل عددًا إلى الأكثر: فالطائفون أقل من العاكفين، والعاكفون أقل من الركع السجود. وهي كذلك مرتبة من العبادة الأخص بالبيت إلى الأعم؛ فالطواف أشد اختصاصًا به.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص265–267، تحت البقرة: 125، في نكتة ترتيب أصناف العابدين.","url":""}]},{"id":"s2-494","number":494,"surah":2,"verses":[125],"verseLabel":"البقرة: 125","question":"ما سرّ التعبير في قوله تعالى: ﴿الطَّائِفِينَ وَالْعَاكِفِينَ﴾ بجمع السلامة، ثم ﴿الرُّكَّعِ السُّجُودِ﴾ بجمع التكسير؟","answer":"جيء بالطائفين والعاكفين جمعي سلامة لقربهما من البيت وخصوص عبادتهما به، وجيء بالركع جمع تكسير الدال على الكثرة، وبالسجود مصدرًا يفيد المبالغة وكثرة السجود كمًّا وكيفًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص265–267، تحت البقرة: 125، في سر اختيار صيغ الجموع.","url":""}]},{"id":"s2-495","number":495,"surah":2,"verses":[126],"verseLabel":"البقرة: 126","question":"ما سرّ تخصيص إبراهيم المؤمنين بطلب الرزق، ثم مجيء الجواب الإلهي بتمتيع الكافر أيضًا؟","answer":"خص إبراهيم المؤمنين في دعائه بالرزق، فجاء الجواب مبينًا أن متاع الدنيا يشمل المؤمن والكافر؛ فالرزق الدنيوي ليس دليلًا وحده على الرضا ولا يختص بأهل الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص267–277، تحت البقرة: 126.","url":""}]},{"id":"s2-496","number":496,"surah":2,"verses":[35],"verseLabel":"البقرة: 126، إبراهيم: 35","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿اجْعَلْ هَذَا بَلَدًا آمِنًا﴾، وقوله في إبراهيم: ﴿اجْعَلْ هَذَا الْبَلَدَ آمِنًا﴾؟","answer":"في البقرة جاء ﴿بلدًا﴾ تنكيرَ نوع؛ أي اجعل هذا المكان واحدًا من البلاد التي يتصف أهلها بالأمن. أما في سورة إبراهيم فقد صار البلد معهودًا حاضرًا معروفًا، ثم بينه بعد ذلك بقوله: ﴿عند بيتك المحرم﴾، فناسب تعريفه بـ﴿البلد﴾ والدعاء بأن يتحول حاله من الخوف إلى الأمن وأن يدوم أمنه. فالمآل واحد، لكن كل تعبير يلحظ حال المكان في الدعاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص91–92، تحت إبراهيم: 35، في المقارنة بالبقرة: 126.","url":""}]},{"id":"s2-497","number":497,"surah":2,"verses":[4],"verseLabel":"البقرة: 126، قريش: 4","question":"ما سرّ اختلاف الترتيب بين تقديم الأمن على الرزق في دعاء إبراهيم، وتقديم الإطعام على الأمن في سورة قريش؟","answer":"في دعاء البقرة قُدّم الأمن لأن الدعاء كان قبل قيام البلد واستقرار أهله، ووجود البلدة الآمنة سابق لانتفاع أهلها بالرزق. وفي سورة قريش جاء الكلام خبرًا عن نعم واقعة، فبدأ بالإطعام الذي يقع على الناس مباشرة، ثم الأمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص275–276، تحت البقرة: 126، في المقارنة بقريش: 4.","url":""}]},{"id":"s2-498","number":498,"surah":2,"verses":[126],"verseLabel":"البقرة: 126","question":"ما مناسبة دعاء إبراهيم باسم الربوبية في قوله: ﴿رَبِّ اجْعَلْ هَذَا بَلَدًا آمِنًا﴾؟","answer":"لأنه يسأل إنشاء بلد ورعايته ورزقه، وهذه من آثار الربوبية التي تتضمن التربية والتدبير والإنماء. وحذف أداة النداء يشعر بالقرب وشدة الضراعة؛ فالطلب يخرج مباشرة من قلب العبد إلى ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص268–271، تحت البقرة: 126، في افتتاح الدعاء بعنوان الربوبية.","url":""}]},{"id":"s2-499","number":499,"surah":2,"verses":[126],"verseLabel":"البقرة: 126","question":"ما دلالة التعريف في ﴿الثمرات﴾، ودخول ﴿من﴾ عليها في قوله تعالى: ﴿وَارْزُقْ أَهْلَهُ مِنَ الثَّمَرَاتِ﴾؟","answer":"التعريف في ﴿الثمرات﴾ للاستغراق العرفي، أي الثمرات المعروفة للناس، و﴿من﴾ للتبعيض والرفق؛ حتى تتوافر لهم أنواع من الثمار من غير أن تتحول مكة إلى موطن زراعة يشغل النفوس بالارتحال إليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص277، تحت البقرة: 126، في دلالة تعريف ﴿الثمرات﴾ ودخول ﴿من﴾ عليها.","url":""}]},{"id":"s2-500","number":500,"surah":2,"verses":[126],"verseLabel":"البقرة: 126","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَنْ كَفَرَ فَأُمَتِّعُهُ قَلِيلًا﴾؛ أليس الكافر غير مستحق للنعمة؟","answer":"بيّن الجواب أن الكافر يُمتع في الدنيا إلى منتهى أجله، ثم يصير إلى عذاب النار. فالرزق الدنيوي عام، ولا يدل حصوله على الرضا عن صاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص274–276، تحت البقرة: 126، في شمول المتاع ووصفه بالقلة.","url":""}]},{"id":"s2-501","number":501,"surah":2,"verses":[126],"verseLabel":"البقرة: 126","question":"ما سرّ التعبير في قوله تعالى: ﴿ثُمَّ أَضْطَرُّهُ إِلَى عَذَابِ النَّارِ﴾، دون أن يقال: «ثم أعذبه»؟","answer":"﴿أضطره﴾ أي ألجئه مرغمًا إلى عذاب النار؛ فليس له عنه مهرب ولا اختيار، وهو أبلغ من مجرد الإخبار بتعذيبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص275–277، تحت البقرة: 126، في دلالة ﴿أضطره إلى﴾ وانتقال المتاع إلى المصير.","url":""}]},{"id":"s2-502","number":502,"surah":2,"verses":[127],"verseLabel":"البقرة: 127","question":"ما سرّ التعبير في قوله تعالى: ﴿يرفع إبراهيم القواعد من البيت﴾ مع أن القواعد هي التي تحمل البناء؟","answer":"رفع القواعد هو البناء فوق الأسس الموجودة حتى يرتفع ما كان منخفضًا منها؛ فالآية تدل على أن قواعد البيت كانت قائمة قبل بناء إبراهيم عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص283، تحت البقرة: 127.","url":""}]},{"id":"s2-503","number":503,"surah":2,"verses":[127],"verseLabel":"البقرة: 127","question":"ما سرّ التعبير في قولهما: ﴿رَبَّنَا تَقَبَّلْ مِنَّا﴾، دون «اقبل منا»؟","answer":"في ﴿تقبل﴾ معنى التكلف في القبول؛ كأن العمل، مع إخلاص صاحبه، لا يستحق القبول بذاته لما فيه من نقص، فيسأل العبد ربه أن يتفضّل بقبوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص285، تحت البقرة: 127.","url":""}]},{"id":"s2-504","number":504,"surah":2,"verses":[127],"verseLabel":"البقرة: 127","question":"ما دلالة حكاية بناء البيت بالمضارع في قوله تعالى: ﴿وَإِذْ يَرْفَعُ إِبْرَاهِيمُ الْقَوَاعِدَ﴾ مع وقوعه في الماضي؟","answer":"المضارع يستحضر المشهد كأنه يقع أمام القارئ: إبراهيم يرفع، وإسماعيل يعينه، والدعاء يصعد مع الحجارة. فبدل خبر تاريخي جامد تصبح هيئة العمل حاضرة مشاهدة، وهذا أليق بمقام الاقتداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص278–280، تحت البقرة: 127، في حكاية الحال الماضية بالمضارع.","url":""}]},{"id":"s2-505","number":505,"surah":2,"verses":[127],"verseLabel":"البقرة: 127","question":"ما سرّ التعبير في قوله تعالى: ﴿يَرْفَعُ إِبْرَاهِيمُ الْقَوَاعِدَ﴾، دون أن يقال: «يبني البيت»؟","answer":"التعبير برفع القواعد يصور إعلاء البناء فوق أسسه الموجودة، ويشير إلى شرف البيت وسبق قواعده؛ وهو أدق من قول عام مثل «يبني البيت».","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص279–282، تحت البقرة: 127، في اختيار مادة الرفع دون غيرها.","url":""}]},{"id":"s2-506","number":506,"surah":2,"verses":[127],"verseLabel":"البقرة: 127","question":"ما سرّ التعبير في قوله تعالى: ﴿الْقَوَاعِدَ مِنَ الْبَيْتِ﴾، دون أن يقال: «قواعد البيت»؟","answer":"عُرّفت ﴿القواعد﴾ ثم بُيّنت بقوله ﴿من البيت﴾ بعد إبهام، فحصل التشويق والتفخيم؛ ولو قيل «قواعد البيت» لزال هذا الأثر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص281–283، تحت البقرة: 127، في تركيب ﴿القواعد من البيت﴾ وأثره في التشويق.","url":""}]},{"id":"s2-507","number":507,"surah":2,"verses":[127],"verseLabel":"البقرة: 127","question":"ما سرّ تقديم إبراهيم على إسماعيل، والفصل بين الاسمين بقوله: ﴿الْقَوَاعِدَ مِنَ الْبَيْتِ﴾؟","answer":"قُدّم إبراهيم لأنه صاحب العمل الأصلي، وكان إسماعيل معينًا له. والفصل بين الاسمين بمتعلقات الفعل يلمح إلى تفاوت نصيبهما في العمل مع اشتراكهما فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص282–284، تحت البقرة: 127، في تقديم إبراهيم والفصل بينه وبين إسماعيل.","url":""}]},{"id":"s2-508","number":508,"surah":2,"verses":[127],"verseLabel":"البقرة: 127","question":"ما دلالة حذف مفعول ﴿تقبل﴾ في قولهما: ﴿رَبَّنَا تَقَبَّلْ مِنَّا﴾؟","answer":"حذف المفعول ليفيد العموم: تقبل منا كل ما صدر من عمل وقول صالح. كما يوجه النظر إلى أصل القبول، فلا يقيده بعمل أو زمان أو مكان مخصوص.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص283–285، تحت البقرة: 127، في حذف مفعول ﴿تقبل﴾.","url":""}]},{"id":"s2-509","number":509,"surah":2,"verses":[127],"verseLabel":"البقرة: 127","question":"ما مناسبة ختم الدعاء بقولهما: ﴿إِنَّكَ أَنْتَ السَّمِيعُ الْعَلِيمُ﴾؟","answer":"الخاتمة تعلل الدعاء: فالله يسمع قولهما ويعلم نيتهما وعملهما. وضمير الفصل وتعريف الخبر يفيدان اختصاصه بكمال السمع والعلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص284–286، تحت البقرة: 127، في فصل الجملة وضمير الفصل واختيار الاسمين.","url":""}]},{"id":"s2-510","number":510,"surah":2,"verses":[128],"verseLabel":"البقرة: 128","question":"ما سرّ دعاء إبراهيم وإسماعيل: ﴿وَاجْعَلْنَا مُسْلِمَيْنِ لَكَ﴾ مع أنهما نبيان مسلمان؟","answer":"الدعاء لزيادة الإسلام والثبات عليه وبلوغ كماله في المستقبل، لا لطلب أصل الإسلام الذي كان حاصلًا لهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص286–301، تحت البقرة: 128.","url":""}]},{"id":"s2-511","number":511,"surah":2,"verses":[128],"verseLabel":"البقرة: 128","question":"لماذا كررا النداء: ﴿رَبَّنَا﴾ بعد قولهما في الآية السابقة: ﴿رَبَّنَا تَقَبَّلْ مِنَّا﴾؟","answer":"لأن كل دعوة حاجة مستقلة تستحق ضراعة جديدة، وتكرار الربوبية يظهر لذة المناجاة وشدة الافتقار. فبعد طلب قبول العمل انتقلا إلى طلب الثبات لهما ولذريتهما وتعليم العبادة وقبول التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص287–289، تحت البقرة: 128، في تكرار النداء بالربوبية.","url":""}]},{"id":"s2-512","number":512,"surah":2,"verses":[128],"verseLabel":"البقرة: 128","question":"ما سرّ قول إبراهيم وإسماعيل: ﴿وَمِنْ ذُرِّيَّتِنَا أُمَّةً مُسْلِمَةً لَكَ﴾ دون «واجعل ذريتنا مسلمة»؟","answer":"﴿من﴾ تبعيضية؛ فلم يسألا ما لا تجري به الحكمة من صلاح كل فرد في الذرية، بل سألا أن يبقى فيها دائمًا جمع يحمل التوحيد. وهذا أدب واقعي سبق أن علّمه جواب ﴿لا ينال عهدي الظالمين﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص289–291، تحت البقرة: 128، في دلالة ﴿من﴾ في ﴿ومن ذريتنا﴾.","url":""}]},{"id":"s2-513","number":513,"surah":2,"verses":[128],"verseLabel":"البقرة: 128","question":"ما سرّ قول إبراهيم وإسماعيل: ﴿وَأَرِنَا مَنَاسِكَنَا﴾ دون «وعلّمنا مناسكنا»؟","answer":"الرؤية تحتمل الإبصار المباشر والعلم اليقيني، فتجمع أن يريهما الله مواقع النسك وكيفيته وأن يفقههما معناه. أما التعليم وحده فقد لا يستحضر المشاهدة العملية التي تحتاجها أعمال الحج وبناء الشعائر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص291–292، تحت البقرة: 128، في دلالة فعل الرؤية واختياره.","url":""}]},{"id":"s2-514","number":514,"surah":2,"verses":[128],"verseLabel":"البقرة: 128","question":"ما مناسبة ختم الدعاء بقوله: ﴿إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ﴾، وتقديم ﴿التواب﴾ على ﴿الرحيم﴾؟","answer":"قُدّم ﴿التواب﴾ لمجاورته طلبهما ﴿وتب علينا﴾، ثم ذُكر ﴿الرحيم﴾ لأنه أعم، ولأن قبول التوبة أثر من آثار رحمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص292–293، تحت البقرة: 128، في اختيار صفتي الفاصلة وترتيبهما.","url":""}]},{"id":"s2-515","number":515,"surah":2,"verses":[2],"verseLabel":"البقرة: 129، آل عمران: 164، الجمعة: 2","question":"ما سرّ اختلاف ترتيب التعليم والتزكية بين دعاء إبراهيم في البقرة: 129، وآيتي الاستجابة في آل عمران والجمعة؟","answer":"في دعاء إبراهيم كان المخاطبون لم يوجدوا بعد، فبدأ بالتلاوة والتعليم لرفع الخطأ المتوقع ثم التزكية. وفي آيتي الامتنان جاء الخطاب لأقوام موجودين في ضلال، فقدم تطهيرهم من الضلال ثم تعليمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص299–301، تحت البقرة: 129، في توجيه المتشابه مع آل عمران: 164 والجمعة: 2.","url":""}]},{"id":"s2-516","number":516,"surah":2,"verses":[129],"verseLabel":"البقرة: 129","question":"ما سرّ التعبير بـ﴿فيهم﴾ في قوله: ﴿وَابْعَثْ فِيهِمْ رَسُولًا﴾، دون «إليهم»؟","answer":"﴿فيهم﴾ تتضمن أن الرسول يكون من جماعتهم، ولا تقتضي أن رسالته محصورة فيهم؛ بخلاف عبارة قد توهم مجرد الاتجاه إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص298، تحت البقرة: 129.","url":""}]},{"id":"s2-517","number":517,"surah":2,"verses":[129],"verseLabel":"البقرة: 129","question":"ما دلالة ﴿منهم﴾ في قوله: ﴿وَابْعَثْ فِيهِمْ رَسُولًا مِنْهُمْ﴾؟","answer":"كون الرسول ﴿منهم﴾ يجعله معروف النسب واللسان والأحوال، فيكون أقرب إلى الألفة وقبول الدعوة وأبعد عن الريبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص294–297، تحت البقرة: 129، في معنى ﴿فيهم﴾ و﴿منهم﴾ ومناسبة الدعاء.","url":""}]},{"id":"s2-518","number":518,"surah":2,"verses":[129],"verseLabel":"البقرة: 129","question":"ما سرّ تقديم تلاوة الآيات على تعليم الكتاب والحكمة في دعاء إبراهيم؟","answer":"قُدمت تلاوة الآيات لأنها برهان الرسالة وأصل تلقي الوحي، ومنها يبدأ تعليم الكتاب والحكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص297–300، تحت البقرة: 129، في ترتيب وظائف الرسول.","url":""}]},{"id":"s2-519","number":519,"surah":2,"verses":[129],"verseLabel":"البقرة: 129","question":"ما سرّ تقديم ﴿العزيز﴾ على ﴿الحكيم﴾ في ختام الدعاء؟","answer":"قُدّم ﴿العزيز﴾ لأنه من صفات الذات، و﴿الحكيم﴾ متعلق بإحكام الأفعال؛ فالعزة أصل، وعنها يصدر الحكم المحكم: عزّ فحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص300–302، تحت البقرة: 129، في مناسبة اسمي ﴿العزيز الحكيم﴾ وترتيبهما.","url":""}]},{"id":"s2-520","number":520,"surah":2,"verses":[130],"verseLabel":"البقرة: 130","question":"ما سرّ التعبير في قوله تعالى: ﴿إلا من سفه نفسه﴾ لا: إلا سفيه؟","answer":"أصل التركيب أن نفسه سفهت، فنُقل الإسناد إلى صاحبها وقيل ﴿سفه نفسه﴾؛ وفي هذا الإسناد المجازي تصوير للسفه كأنه تمكن منه حتى أفسد نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص310–318، تحت البقرة: 130.","url":""}]},{"id":"s2-521","number":521,"surah":2,"verses":[130],"verseLabel":"البقرة: 130","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَنْ يَرْغَبُ عَنْ مِلَّةِ إِبْرَاهِيمَ﴾ في صورة سؤال، دون أن يقال: «لا يرغب عنها عاقل»؟","answer":"الاستفهام إنكاري يجعل السامع يبحث فلا يجد صاحب عقل يختار الإعراض عن ملة إبراهيم بعد ظهور شرفها. وهو أوقع من الخبر؛ لأنه يحول الحكم إلى نتيجة يصل إليها القارئ بنفسه: لا يفعل ذلك إلا من أفسد تقديره لنفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص303–306، تحت البقرة: 130، في بناء الاستفهام والاتصال بما قبله.","url":""}]},{"id":"s2-522","number":522,"surah":2,"verses":[130],"verseLabel":"البقرة: 130","question":"ما دلالة لفظ ﴿اصطفيناه﴾ في قوله تعالى: ﴿وَلَقَدِ اصْطَفَيْنَاهُ فِي الدُّنْيَا﴾؟","answer":"الاصطفاء تناول صفو الشيء وخلاصته؛ والمعنى أن الله اختار إبراهيم من بين الخلق للنبوة والحكمة في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص304–305، تحت البقرة: 130، في معنى الاصطفاء.","url":""}]},{"id":"s2-523","number":523,"surah":2,"verses":[130],"verseLabel":"البقرة: 130","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِنَّهُ فِي الْآخِرَةِ لَمِنَ الصَّالِحِينَ﴾، دون أن يقال: «وإنه في الآخرة صالح»؟","answer":"التعبير بـ﴿لَمِنَ الصَّالِحِينَ﴾ أدخل إبراهيم في جماعة الصالحين وثبت له الوصف توكيدًا. وتعدد المؤكدات يناسب الرد على من عرف اصطفاءه ثم رغب عن ملته.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص307–308، تحت البقرة: 130، في دلالة ﴿لمن الصالحين﴾.","url":""}]},{"id":"s2-524","number":524,"surah":2,"verses":[131],"verseLabel":"البقرة: 131","question":"ما دلالة حذف المفعول في الأمر والجواب: ﴿أَسْلِمْ قَالَ أَسْلَمْتُ﴾؟","answer":"حذف مفعول ﴿أسلم﴾ و﴿أسلمت﴾ للإيجاز ولإطلاق معنى الإسلام من غير تقييد، والتقدير: أسلم نفسك لي. وجاء الجواب دالًا على المبادرة إلى الامتثال.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص309–311، تحت البقرة: 131، في حذف مفعول ﴿أسلم﴾ والإيجاز.","url":""}]},{"id":"s2-525","number":525,"surah":2,"verses":[131],"verseLabel":"البقرة: 131","question":"ما سرّ اختيار إبراهيم وصف ﴿رَبِّ الْعَالَمِينَ﴾ في جوابه: ﴿أَسْلَمْتُ لِرَبِّ الْعَالَمِينَ﴾؟","answer":"وصف ﴿رب العالمين﴾ يناسب قوله ﴿إذ قال له ربه﴾، ويعلن أن إسلام إبراهيم ليس لرب خاص بقوم، بل لرب جميع العالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص310–311، تحت البقرة: 131، في إيثار ﴿رب العالمين﴾ والمقابلة اللفظية.","url":""}]},{"id":"s2-526","number":526,"surah":2,"verses":[132],"verseLabel":"البقرة: 132","question":"ما سرّ التعبير في قوله تعالى: ﴿وَوَصَّى بِهَا إِبْرَاهِيمُ بَنِيهِ﴾، وإلى ماذا يعود ضمير ﴿بها﴾؟","answer":"يحتمل أن يعود ضمير ﴿بها﴾ إلى كلمة ﴿أسلمت لرب العالمين﴾، أي كلمة التوحيد والإسلام، ويحتمل عوده إلى ملة إبراهيم المفهومة من السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص312–315، تحت البقرة: 132، في استئناف الوصية ومرجع الضمير.","url":""}]},{"id":"s2-527","number":527,"surah":2,"verses":[132],"verseLabel":"البقرة: 132","question":"ما سرّ إفراد يعقوب بالذكر في قوله تعالى: ﴿وَوَصَّى بِهَا إِبْرَاهِيمُ بَنِيهِ وَيَعْقُوبُ﴾؟","answer":"أُفرد يعقوب بالذكر لأنه وصّى بنيه الوصية نفسها، ولإقامة الحجة على بني إسرائيل خاصة؛ فهو الجامع لنسبهم الذي ينتسبون إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص313–316، تحت البقرة: 132، في عطف يعقوب واتصال الوصية بالذرية.","url":""}]},{"id":"s2-528","number":528,"surah":2,"verses":[132],"verseLabel":"البقرة: 132","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّ اللَّهَ اصْطَفَى لَكُمُ الدِّينَ﴾، دون أن يقال: «اصطفاكم للدين»؟","answer":"﴿اصطفى لكم الدين﴾ تفيد أن الله اختار لهم الدين الصفو الكامل وادخره لهم تفضّلًا، فالعناية هنا بالدين المختار لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص315–317، تحت البقرة: 132، في معنى الاصطفاء وبناء الوصية.","url":""}]},{"id":"s2-529","number":529,"surah":2,"verses":[132],"verseLabel":"البقرة: 132","question":"كيف يُفهم النهي في قوله تعالى: ﴿فَلَا تَمُوتُنَّ إِلَّا وَأَنْتُمْ مُسْلِمُونَ﴾ مع أن الإنسان لا يملك وقت موته؟","answer":"ليس النهي عن وقوع الموت نفسه، بل عن مفارقة الإسلام في أي وقت؛ أي داوموا على الإسلام حتى إذا جاءكم الموت وجدكم عليه. والجملة الاسمية ﴿وأنتم مسلمون﴾ تثبت هذه الحال.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص317–319، تحت البقرة: 132، في معنى النهي والاستثناء والجملة الاسمية الدالة على الثبوت.","url":""}]},{"id":"s2-530","number":530,"surah":2,"verses":[133],"verseLabel":"البقرة: 133","question":"ما دلالة الاستفهام بـ﴿ما﴾ دون ﴿من﴾ في قول يعقوب: ﴿مَا تَعْبُدُونَ مِنْ بَعْدِي﴾؟","answer":"﴿ما﴾ أعم من ﴿من﴾؛ فهي تسأل عن المعبود وحقيقته وصفته، أما ﴿من﴾ فتختص غالبًا بالعاقل. فالمقام امتحان لحقيقة ما يعبدون لا لمجرد تعيين أشخاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص325–326، تحت البقرة: 133.","url":""}]},{"id":"s2-531","number":531,"surah":2,"verses":[133],"verseLabel":"البقرة: 133","question":"ما دلالة دخول ﴿من﴾ على ﴿بعدي﴾ في قوله تعالى: ﴿مَا تَعْبُدُونَ مِنْ بَعْدِي﴾؟","answer":"تفيد ﴿من﴾ ابتداء الزمن من أول وقت بعد موته؛ فتؤكد استمرار العبادة بلا مهلة يقع فيها تغيير أو انقطاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص326، تحت البقرة: 133.","url":""}]},{"id":"s2-532","number":532,"surah":2,"verses":[133],"verseLabel":"البقرة: 133","question":"ما سرّ التعبير في قوله تعالى: ﴿أَمْ كُنْتُمْ شُهَدَاءَ﴾، ولم يسألهم مباشرة: «ماذا أوصى يعقوب أبناءه؟»؟","answer":"﴿أم﴾ منقطعة بمعنى «بل أكنتم شهداء؟»، والاستفهام للإنكار والتوبيخ؛ ينفي حضورهم وصية يعقوب ويبطل دعواهم أن الأنبياء كانوا يهودًا أو نصارى.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص320–322، تحت البقرة: 133، في الاستفهام الإنكاري والاحتجاج على أهل الكتاب.","url":""}]},{"id":"s2-533","number":533,"surah":2,"verses":[133],"verseLabel":"البقرة: 133","question":"ما سرّ التعبير في قوله تعالى: ﴿إِذْ حَضَرَ يَعْقُوبَ الْمَوْتُ﴾، مع أن الموت لا يحضر قبل وقوعه؟","answer":"صُوّر الموت كأنه شخص حاضر ليقرب المشهد ويستحضر شدته، ويجوز أن يراد حضور مقدماته وأسبابه التي دلت على قربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص320–323، تحت البقرة: 133، في تصوير حضور الموت ومناسبة الوصية.","url":""}]},{"id":"s2-534","number":534,"surah":2,"verses":[133],"verseLabel":"البقرة: 133","question":"ما دلالة قولهم: ﴿نَعْبُدُ إِلَهَكَ وَإِلَهَ آبَائِكَ﴾، دون الاكتفاء بقولهم: «نعبد الله»؟","answer":"ربطوا توحيدهم بتربية أبيهم وسلسلة النبوة قبله، فأعلنوا أن معبودهم ليس اختيارًا جديدًا بعد موته بل إله البيت النبوي كله. وإضافة الإله إلى يعقوب وآبائه تشعر باتصال العهد من جيل إلى جيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص323–326، تحت البقرة: 133، في التعريف بالإضافة وتوقير سلسلة الآباء.","url":""}]},{"id":"s2-535","number":535,"surah":2,"verses":[133],"verseLabel":"البقرة: 133","question":"كيف عُدَّ إسماعيل من ﴿آبَائِكَ﴾ ليعقوب وهو عمه؟","answer":"سمّي إسماعيل أبًا ليعقوب لأن العم بمنزلة الأب في القرابة والرعاية، وقُدّم على إسحاق لأنه أكبر منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص324–326، تحت البقرة: 133، في إطلاق الأب على العم وذكر إسماعيل.","url":""}]},{"id":"s2-536","number":536,"surah":2,"verses":[133],"verseLabel":"البقرة: 133","question":"ما سرّ إعادة لفظ ﴿إله﴾ ثم وصفه بالوحدة في قولهم: ﴿إِلَهَكَ وَإِلَهَ آبَائِكَ... إِلَهًا وَاحِدًا﴾؟","answer":"أُعيد لفظ ﴿إله﴾ ليبنى عليه الوصف ﴿واحدًا﴾ بعد تعدد المضاف إليهم؛ فيتأكد أن إله إبراهيم وإسماعيل وإسحاق إله واحد لا آلهة متعددة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص325–326، تحت البقرة: 133، في وصف الإله بالوحدة والتوكيد.","url":""}]},{"id":"s2-537","number":537,"surah":2,"verses":[133],"verseLabel":"البقرة: 133","question":"ما دلالة الجملة الاسمية وتقديم ﴿له﴾ في قولهم: ﴿وَنَحْنُ لَهُ مُسْلِمُونَ﴾؟","answer":"الجملة الاسمية تدل على الثبات والاستمرار، وتقديم ﴿له﴾ يفيد القصر؛ أي نحن مسلمون له وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص326–327، تحت البقرة: 133، في الجملة الاسمية وتقديم المتعلق للقصر.","url":""}]},{"id":"s2-538","number":538,"surah":2,"verses":[134],"verseLabel":"البقرة: 134","question":"ما سرّ تكرار قوله تعالى: ﴿تِلْكَ أُمَّةٌ قَدْ خَلَتْ لَهَا مَا كَسَبَتْ...﴾ في الآيتين 134 و141؟","answer":"كرر النص بعد عرض دعوى اليهود والنصارى ليقطع التعلق بالأنساب من الجهتين: فعمل الآباء لهم، وعمل المخاطبين لهم، ولا يغني أحد عن أحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص332–345، تحت البقرة: 134 و141.","url":""}]},{"id":"s2-539","number":539,"surah":2,"verses":[134],"verseLabel":"البقرة: 134","question":"ما سرّ التعبير في قوله تعالى: ﴿تِلْكَ أُمَّةٌ قَدْ خَلَتْ﴾ باسم الإشارة للبعيد؟","answer":"البعد يلحظ انقضاء زمنهم وعلو منزلة الصالحين منهم معًا، ويوقظ المخاطب من الاتكال على تاريخ لم يعشه. مهما عظم السابقون فقد عبروا إلى حسابهم، وبقي على الحاضرين أن يصنعوا عملهم هم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص328–330، تحت البقرة: 134، في دلالة اسم الإشارة والبعد.","url":""}]},{"id":"s2-540","number":540,"surah":2,"verses":[134],"verseLabel":"البقرة: 134","question":"ما دلالة تقديم ﴿لها﴾ و﴿لكم﴾ في قوله تعالى: ﴿لَهَا مَا كَسَبَتْ وَلَكُمْ مَا كَسَبْتُمْ﴾؟","answer":"التقديم يقصر كسب كل جماعة عليها: حسنات الآباء لا تعبر آليًا إلى الأبناء، وذنوبهم لا تحمل على غير فاعلها. وفي المقابلة قطع لأطماع من جعل النسب رصيدًا يغنيه عن الإيمان والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص329–331، تحت البقرة: 134، في تقديم المسند وقصر الكسب على صاحبه.","url":""}]},{"id":"s2-541","number":541,"surah":2,"verses":[134],"verseLabel":"البقرة: 134","question":"ما فائدة قوله تعالى: ﴿وَلَا تُسْأَلُونَ عَمَّا كَانُوا يَعْمَلُونَ﴾ بعد قوله: ﴿لَهَا مَا كَسَبَتْ وَلَكُمْ مَا كَسَبْتُمْ﴾؟","answer":"أكدت الجملة استقلال المسؤولية من جهة الحساب بعد أن قررته من جهة الملك: لا تملكون كسبهم ولا تسألون عن عملهم. والزيادة تغلق الوهمين معًا؛ لا ينفعكم فضلهم بلا اقتداء، ولا يصح أن تتخذوا أخطاءهم عذرًا لتقصيركم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص330–332، تحت البقرة: 134، في فائدة نفي السؤال والتوكيد.","url":""}]},{"id":"s2-542","number":542,"surah":2,"verses":[135],"verseLabel":"البقرة: 135","question":"ما سرّ جمع قول الفريقين في قوله تعالى: ﴿وَقَالُوا كُونُوا هُودًا أَوْ نَصَارَى تَهْتَدُوا﴾؟","answer":"القول موزع على الفريقين: اليهود قالوا كونوا هودًا، والنصارى قالوا كونوا نصارى. و﴿أو﴾ فصلت الدعوتين، وفي العبارة احتباك؛ حُذف ﴿تهتدوا﴾ من الأولى و﴿كونوا﴾ من الثانية لدلالة المذكور عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص343–344، تحت البقرة: 135، في الاحتباك واستعمال ﴿أو﴾.","url":""}]},{"id":"s2-543","number":543,"surah":2,"verses":[135],"verseLabel":"البقرة: 135","question":"ما سرّ مجيء الرد بقوله تعالى: ﴿بَلْ مِلَّةَ إِبْرَاهِيمَ﴾ من غير ذكر فعل؟","answer":"﴿بل﴾ للإضراب الإبطالي عن الدعوتين، والتقدير: بل نتبع، أو اتبعوا، ملة إبراهيم. وحذف الفعل لدلالة السياق عليه وإبراز الملة التي هي موضع الرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص344–345، تحت البقرة: 135، في الإضراب والحذف في ﴿بل ملة إبراهيم﴾.","url":""}]},{"id":"s2-544","number":544,"surah":2,"verses":[135],"verseLabel":"البقرة: 135","question":"ما دلالة وصف إبراهيم بأنه ﴿حَنِيفًا﴾؟","answer":"الحنيف هو المائل عن الأديان الباطلة والشرك إلى الدين المستقيم والتوحيد الخالص؛ فالوصف ينفي عن إبراهيم ما نسبه إليه الفريقان.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص342 و345–346، تحت البقرة: 135، في معنى ﴿حنيفًا﴾ ومناسبته للسياق.","url":""}]},{"id":"s2-545","number":545,"surah":2,"verses":[135],"verseLabel":"البقرة: 135","question":"ما فائدة قوله تعالى: ﴿وَمَا كَانَ مِنَ الْمُشْرِكِينَ﴾ بعد وصف إبراهيم بأنه ﴿حَنِيفًا﴾؟","answer":"وصف ﴿حنيفًا﴾ يثبت ميل إبراهيم إلى التوحيد، ثم جاء ﴿وما كان من المشركين﴾ احتراسًا يقطع كل احتمال لإدخاله في شيء من الشرك، ويرد دعوى من نسبه إلى ملل حدثت بعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص339–341، تحت البقرة: 135، في الاحتراس بنفي الشرك.","url":""}]},{"id":"s2-546","number":546,"surah":2,"verses":[136],"verseLabel":"البقرة: 136","question":"ما سرّ التعبير في قوله تعالى في البقرة ﴿قولوا آمنا﴾، وفي آل عمران ﴿قل آمنا﴾؟","answer":"البقرة رد جماعي على دعوة اليهود والنصارى فخوطب المؤمنون جميعًا، وآل عمران مقام إعلان الرسول لميثاق الوحي فبدأ الأمر به.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص351–353، تحت البقرة: 136، في المقارنة بآل عمران: 84.","url":""}]},{"id":"s2-547","number":547,"surah":2,"verses":[136],"verseLabel":"البقرة: 136","question":"ما سرّ التعبير هنا في قوله تعالى ﴿وما أنزل إلينا﴾، وفي آل عمران ﴿وما أنزل علينا﴾؟","answer":"عبّر في البقرة بـ﴿إلينا﴾ لأن الخطاب للأمة، والمنزل وصل إليها وانتهى إليها. وعبّر في آل عمران بـ﴿علينا﴾ لأن الأمر للنبي ﷺ، والإنزال عليه مباشرة، ثم تتلقاه الأمة عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص351–353، تحت البقرة: 136، في المقارنة بآل عمران: 84.","url":""}]},{"id":"s2-548","number":548,"surah":2,"verses":[84],"verseLabel":"البقرة: 136، آل عمران: 84","question":"ما سرّ تكرار ﴿وَمَا أُوتِيَ﴾ قبل ﴿النَّبِيُّونَ﴾ في البقرة، وحذفها في نظيرها من آل عمران؟","answer":"البقرة خطاب للمؤمنين، ومقامها تسجيل إيمانهم المفصل بجميع ما أوتي الأنبياء من غير تفريق، فناسب توكيد فعل الإيتاء مرة أخرى. أما آل عمران فالخطاب فيه صادر من النبي ﷺ، وهو منزه أصلًا عن التفريق بين الرسل؛ فلم يحتج المقام إلى التوكيد نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص407، تحت آل عمران: 84، في المقارنة بالبقرة: 136.","url":""}]},{"id":"s2-549","number":549,"surah":2,"verses":[136],"verseLabel":"البقرة: 136","question":"ما سرّ تقديم الإيمان بما أنزل إلى المسلمين على ذكر ما أنزل إلى الأنبياء السابقين؟","answer":"قُدّم ما أنزل إلى المسلمين لأنه الكتاب الذي خوطبوا به ويلزمهم اتباعه، ومن طريقه عرفوا صدق ما أنزل إلى الأنبياء السابقين؛ ثم عطف عليه سائر الوحي بيانًا لوحدته.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص347–351، تحت البقرة: 136، في تقديم القرآن على سائر الكتب.","url":""}]},{"id":"s2-550","number":550,"surah":2,"verses":[136],"verseLabel":"البقرة: 136","question":"ما سرّ اختلاف التعبير بين ﴿مَا أُنْزِلَ إِلَيْنَا﴾ و﴿مَا أُوتِيَ مُوسَى وَعِيسَى﴾؟","answer":"الإنزال يلائم القرآن المنزل المتلو بوصفه كتاب الأمة القائم، أما الإيتاء فأوسع؛ يشمل ما أعطي موسى وعيسى من الكتب والمعجزات والحكم، لا النص وحده. فاختير لكل موضع الفعل الذي يستوعب نوع العطاء المقصود.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص348–351، تحت البقرة: 136، في الفرق بين الإنزال والإيتاء.","url":""}]},{"id":"s2-551","number":551,"surah":2,"verses":[136],"verseLabel":"البقرة: 136","question":"ما سرّ ترتيب إبراهيم وإسماعيل وإسحاق ويعقوب والأسباط قبل موسى وعيسى؟","answer":"رتبهم بحسب الأصل والنسب والتاريخ: إبراهيم أبو الملة، ثم ابناه إسماعيل وإسحاق، ثم يعقوب وذريته، ثم الرسالات الكبرى في بني إسرائيل. وهذا التدرج يبين أن الوحي سلسلة واحدة لا ملكية حصرية لفريق متأخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص346–350، تحت البقرة: 136، في ترتيب الأنبياء والتدلي من الأصل إلى الفروع.","url":""}]},{"id":"s2-552","number":552,"surah":2,"verses":[136],"verseLabel":"البقرة: 136","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْهُمْ﴾، مع أن للأنبياء درجات مختلفة؟","answer":"المنفي هو التفريق في أصل الإيمان والقبول، لا تفاوت الفضل والخصائص؛ فلا يؤمن المسلم ببعض ويكفر ببعض كما فعلت جماعات من أهل الكتاب. كلمة ﴿أحد﴾ في سياق النفي تستغرق كل فرد، فتغلق أي استثناء من التصديق.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص350–352، تحت البقرة: 136، في عموم ﴿أحد﴾ ومعنى نفي التفريق.","url":""}]},{"id":"s2-553","number":553,"surah":2,"verses":[136],"verseLabel":"البقرة: 136","question":"ما مناسبة ختم آية الإيمان بالكتب والرسل بقوله: ﴿وَنَحْنُ لَهُ مُسْلِمُونَ﴾؟","answer":"لأن التصديق لا يكتمل بلا انقياد؛ فبعد بيان ما تؤمن به الأمة قرر حالها العملي تجاه مصدر الوحي. وتقديم ﴿له﴾ يقصر الإسلام على الله، والجملة الاسمية تثبت هذا الخضوع صفةً دائمة لا موقفًا مؤقتًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص351–352، تحت البقرة: 136، في مناسبة الفاصلة وتقديم المتعلق.","url":""}]},{"id":"s2-554","number":554,"surah":2,"verses":[137],"verseLabel":"البقرة: 137","question":"ما سرّ التعبير في قوله تعالى: ﴿فسيكفيكهم الله﴾ بالسين لا بسوف؟","answer":"السين أقرب زمنًا وأوجز، فحملت وعدًا سريعًا مطمئنًا بكفاية عداوتهم، وناسبت مقام المواجهة المباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص357، تحت البقرة: 137.","url":""}]},{"id":"s2-555","number":555,"surah":2,"verses":[137],"verseLabel":"البقرة: 137","question":"ما وجه التعبير في قوله تعالى: ﴿فَإِنْ آمَنُوا بِمِثْلِ مَا آمَنْتُمْ بِهِ﴾؛ وهل للإيمان الحق «مثل» آخر؟","answer":"المثلية ليست بين إيمانين مختلفين متساويين، بل في مضمون ما آمن به المسلمون وطريقته الجامعة: الإيمان بالله والوحي والرسل جميعًا. أي إن صدقوا بالذي صدقتم به تصديقًا مماثلًا بلا انتقاء فقد اهتدوا؛ فالعبارة تقيم إيمان المؤمنين نموذجًا عمليًا يعرض عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص353–356، تحت البقرة: 137، في توجيه ﴿بمثل ما آمنتم به﴾.","url":""}]},{"id":"s2-556","number":556,"surah":2,"verses":[137],"verseLabel":"البقرة: 137","question":"ما سرّ التعبير في قوله تعالى: ﴿فَقَدِ اهْتَدَوْا﴾ بالماضي بعد شرط مستقبل؟","answer":"لأن حصول الهداية عند تحقق هذا الإيمان محقق لا يتخلف، فصُوّر الجزاء كأنه قد وقع واستقر. و﴿قد﴾ تزيد معنى التحقيق: ما إن يؤمنوا بذلك الإيمان الجامع حتى يدخلوا في الهداية دخولًا ثابتًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص355–357، تحت البقرة: 137، في بناء جواب الشرط وتحقيق الهداية.","url":""}]},{"id":"s2-557","number":557,"surah":2,"verses":[137],"verseLabel":"البقرة: 137","question":"ما سرّ التعبير في قوله تعالى: ﴿فَإِنَّمَا هُمْ فِي شِقَاقٍ﴾، دون أن يقال: «فإنهم ضالون»؟","answer":"الشقاق يصورهم في شق مقابل لشق الحق، قد اختاروا المفاصلة والعداوة لا مجرد الخطأ في الطريق. والقصر بـ﴿إنما﴾ يحصر حقيقة موقفهم بعد وضوح الإيمان: ليس وراء التولي حجة خفية، وإنما عناد وانشقاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص356–358، تحت البقرة: 137، في القصر بـ﴿إنما﴾ وتصوير الشقاق.","url":""}]},{"id":"s2-558","number":558,"surah":2,"verses":[137],"verseLabel":"البقرة: 137","question":"ما سرّ التعبير بالكفاية في قوله تعالى: ﴿فَسَيَكْفِيكَهُمُ اللَّهُ﴾، دون التصريح بالنصر عليهم؟","answer":"الكفاية أعم من النصر؛ فهي ضمان أن يكفي الله نبيه شرهم وكيدهم، وتتضمن إظهاره عليهم، فلا يبلغه منهم ما يريدون.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص357–359، تحت البقرة: 137، في الوعد بالكفاية وبناء اللفظ.","url":""}]},{"id":"s2-559","number":559,"surah":2,"verses":[137],"verseLabel":"البقرة: 137","question":"ما مناسبة ختم الوعد بقوله تعالى: ﴿وَهُوَ السَّمِيعُ الْعَلِيمُ﴾؟","answer":"يسمع أقوالهم ومجادلاتهم ويعلم كيدهم الخفي وحال الرسول، فلا يفوته ما يحتاج إلى كفاية. والتعريف وضمير الفصل يفيدان كمال الصفتين واختصاصه بالسمع والعلم المحيطين اللذين يقوم عليهما الوعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص358–359، تحت البقرة: 137، في مناسبة الفاصلة والقصر في الاسمين.","url":""}]},{"id":"s2-560","number":560,"surah":2,"verses":[138],"verseLabel":"البقرة: 138","question":"ما سرّ التعبير عن الدين بقوله تعالى: ﴿صِبْغَةَ اللَّهِ﴾؟","answer":"الصبغة في أصلها ما يظهر أثره في المصبوغ. واستعيرت لدين الله؛ لأن الإيمان يداخل صاحبه ويظهر أثره عليه، وفي اللفظ مقابلة لصبغة أهل الكتاب وطقوسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص359، تحت البقرة: 138.","url":""}]},{"id":"s2-561","number":561,"surah":2,"verses":[138],"verseLabel":"البقرة: 138","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَنْ أَحْسَنُ مِنَ اللَّهِ صِبْغَةً﴾ بصيغة المفاضلة، وهل توجد صبغة حسنة تقاربها؟","answer":"الاستفهام ينفي أن توجد صبغة تدانيها أصلًا؛ فصيغة التفضيل خرجت إلى تقرير الحسن المطلق والتهكم بمن ظن في بدائل البشر حسنًا. ما يصنعه الله في الفطرة والوحي لا يساويه طقس ولا هوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص361–364، تحت البقرة: 138، في الاستفهام واستعمال أفعل التفضيل.","url":""}]},{"id":"s2-562","number":562,"surah":2,"verses":[138],"verseLabel":"البقرة: 138","question":"ما مناسبة قوله: ﴿وَنَحْنُ لَهُ عَابِدُونَ﴾ بعد قوله قبل آيتين: ﴿وَنَحْنُ لَهُ مُسْلِمُونَ﴾؟","answer":"الإسلام يقرر الانقياد العام لله، والعبادة تظهر ثمرة هذا الانقياد في العمل والتقرب؛ فانتقل السياق من الهوية الإيمانية إلى أثر الصبغة في السلوك. وتقديم ﴿له﴾ في الموضعين يقصر الخضوع والعبادة عليه وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص363–364، تحت البقرة: 138، في دلالة الفاصلة والقصر.","url":""}]},{"id":"s2-563","number":563,"surah":2,"verses":[139],"verseLabel":"البقرة: 139","question":"ما دلالة قوله تعالى: ﴿أَتُحَاجُّونَنَا فِي اللَّهِ﴾؟","answer":"الاستفهام للإنكار والتوبيخ: أتخاصموننا في شأن الله ودينه واختصاصكم بفضله، مع أنه ربنا وربكم؟ فالمحاجة باطلة لأن الربوبية مشتركة، والتفاضل بالإخلاص والعمل لا بالدعوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص365–368، تحت البقرة: 139، في الاستفهام والإيجاز بالحذف.","url":""}]},{"id":"s2-564","number":564,"surah":2,"verses":[139],"verseLabel":"البقرة: 139","question":"ما سرّ التعبير في قوله تعالى: ﴿وَهُوَ رَبُّنَا وَرَبُّكُمْ﴾؟","answer":"يهدم الجملة أصل احتكار القرب: الرب الذي ربّى بني إسرائيل هو نفسه رب العرب والعالمين، فلا تمنحهم نسبًا خاصًا يملكون به الوحي. وبدأ بـ﴿ربنا﴾ لأن المؤمن يعلن صلته بالله أولًا ثم يدعو خصمه إلى الاعتراف بالرب المشترك.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص367–370، تحت البقرة: 139، في الاحتجاج بوحدة الربوبية.","url":""}]},{"id":"s2-565","number":565,"surah":2,"verses":[139],"verseLabel":"البقرة: 139","question":"ما دلالة تقديم ﴿لنا﴾ و﴿لكم﴾ في قوله تعالى: ﴿وَلَنَا أَعْمَالُنَا وَلَكُمْ أَعْمَالُكُمْ﴾؟","answer":"التقديم يقصر عمل كل فريق عليه ويفصل المسؤولية: لا يغني انتساب أحد إلى نبي عن عمله، ولا يحمل المؤمن تبعة تحريف غيره. وفي المقابلة هدوء حاسم؛ بدل النزاع في الأنساب يعاد كل إنسان إلى رصيده الحقيقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص369–371، تحت البقرة: 139، في التقديم للقصر وعطف الجملتين.","url":""}]},{"id":"s2-566","number":566,"surah":2,"verses":[139],"verseLabel":"البقرة: 139","question":"ما سرّ التعبير في قوله تعالى: ﴿وَنَحْنُ لَهُ مُخْلِصُونَ﴾، دون أن يقال: «ونحن مؤمنون به»؟","answer":"لأن محل المفاضلة ليس مجرد ادعاء الإيمان الذي يقوله الفريقان، بل صفاء العبادة من الشرك والتحريف والرياء. والإخلاص يواجه احتكارهم مباشرة: القرب من الله لا بالنسب، وإنما بتجريد القصد والعمل له.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص370–372، تحت البقرة: 139، في ختم المحاجة بالإخلاص وتقديم ﴿له﴾.","url":""}]},{"id":"s2-567","number":567,"surah":2,"verses":[140],"verseLabel":"البقرة: 140","question":"كيف يزعمون أن إبراهيم وإسماعيل وإسحاق ويعقوب كانوا يهودًا أو نصارى، وقد عاشوا قبل ظهور اليهودية والنصرانية؟","answer":"صاغ القرآن الدعوى في سؤال يكشف تناقضها الزمني بذاته؛ فهؤلاء الآباء سبقوا التوراة والإنجيل والانقسامات اللاحقة. لذلك كان انتسابهم إلى الإسلام الحنيف أصدق، أما جرّهم إلى أسماء حدثت بعدهم فإسقاط للتاريخ على الهوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص372–377، تحت البقرة: 140، في إبطال دعوى يهودية الأنبياء أو نصرانيتهم.","url":""}]},{"id":"s2-568","number":568,"surah":2,"verses":[140],"verseLabel":"البقرة: 140","question":"ما سرّ التعبير في قوله تعالى: ﴿أَأَنْتُمْ أَعْلَمُ أَمِ اللَّهُ﴾، دون أن يقال: «والله أعلم منكم»؟","answer":"الاستفهام يجبرهم على مواجهة أحد خيارين لا ثالث لهما: علمهم المحدود أم علم الله الذي أوحى بحقيقة الأنبياء. وهو أبلغ من الخبر؛ لأن الخصم نفسه لا يستطيع أن يختار أنه أعلم من الله، فتسقط دعواه بإقراره.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص376–378، تحت البقرة: 140، في الاستفهام والتقريع بالمفاضلة.","url":""}]},{"id":"s2-569","number":569,"surah":2,"verses":[140],"verseLabel":"البقرة: 140","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَنْ أَظْلَمُ مِمَّنْ كَتَمَ شَهَادَةً عِنْدَهُ مِنَ اللَّهِ﴾؟","answer":"جمع التركيب عناصر الجريمة: علم مودع عندهم، وشهادة مصدرها الله، ثم كتمان متعمد لتحقيق مصلحة. لذلك بلغ الظلم غايته؛ لأنه لا يضل صاحبه وحده بل يحجب عن الناس دليلاً يعلم صدقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص378–381، تحت البقرة: 140، في أسلوب ﴿ومن أظلم﴾ وقيود الشهادة والكتمان.","url":""}]},{"id":"s2-570","number":570,"surah":2,"verses":[140],"verseLabel":"البقرة: 140","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وَمَا اللَّهُ بِغَافِلٍ عَمَّا تَعْمَلُونَ﴾ دون التصريح بالعقوبة؟","answer":"نفي الغفلة وعيد أوسع؛ فهو يحيط بالكتمان وبالدوافع والآثار وسائر الأعمال، ويترك نوع الجزاء لهول ما يستحقون. والباء تقوي النفي: لا يغيب عنه شيء حتى لو أخفوه عن الناس أو داخل الكتب.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص381–384، تحت البقرة: 140، في مناسبة الفاصلة ونفي الغفلة.","url":""}]},{"id":"s2-571","number":571,"surah":2,"verses":[142],"verseLabel":"البقرة: 142","question":"ما دلالة الاستفهام بـ﴿ما﴾ في قولهم: ﴿مَا وَلَّاهُمْ عَنْ قِبْلَتِهِمُ﴾، دون ﴿من﴾؟","answer":"﴿ما﴾ هنا للسؤال عن سبب التحويل: أي أيُّ شيء ولّاهم وصرفهم عن قبلتهم؟ أما ﴿من﴾ فتسأل عن الفاعل، والفاعل معلوم؛ فموضع اعتراضهم هو علة التحويل.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص395–396، تحت البقرة: 142.","url":""}]},{"id":"s2-572","number":572,"surah":2,"verses":[142],"verseLabel":"البقرة: 142","question":"ما سرّ التعبير في قوله تعالى: ﴿سَيَقُولُ السُّفَهَاءُ﴾ قبل أن يقولوا اعتراضهم فعلًا؟","answer":"أخبر بالاعتراض مستقبلًا ليهيئ النبي والمؤمنين له، فلا يفاجئهم ولا يزعزعهم، وليكون وقوعه كما أخبر آية على صدق الوحي. كما يدل المضارع على أن مقالتهم ليست لحظة عابرة بل عادة يجددونها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص386–390، تحت البقرة: 142، في التعبير بالمستقبل ﴿سيقول﴾.","url":""}]},{"id":"s2-573","number":573,"surah":2,"verses":[142],"verseLabel":"البقرة: 142","question":"ما سرّ وصف المعترضين بأنهم ﴿السُّفَهَاءُ مِنَ النَّاسِ﴾ قبل الرد على اعتراضهم؟","answer":"السفه خفة العقل واضطراب الرأي، وقد كشف اعتراضهم هذا الوصف؛ إذ اعترضوا على حكم المالك الذي له المشرق والمغرب. وقيد ﴿من الناس﴾ يبين أنهم طائفة من الناس لا جميعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص388–392، تحت البقرة: 142، في اختيار لفظ السفهاء وقيد ﴿من الناس﴾.","url":""}]},{"id":"s2-574","number":574,"surah":2,"verses":[142],"verseLabel":"البقرة: 142","question":"ما سرّ حكاية اعتراضهم بضمير الغائب: ﴿مَا وَلَّاهُمْ عَنْ قِبْلَتِهِمُ﴾؟","answer":"صوّرهم يتناجون عن المؤمنين من وراء ظهورهم لا يطلبون جوابًا صادقًا منهم؛ فالغيبة تلائم السخرية والإرجاف. وهي تكشف أنهم يتخذون التحول مادة حديث، لا مسألة علم يسألون أصحابها مباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص392–394، تحت البقرة: 142، في التعبير بضمير الغيبة.","url":""}]},{"id":"s2-575","number":575,"surah":2,"verses":[142],"verseLabel":"البقرة: 142","question":"ما دلالة إضافة القبلة إلى المسلمين في قوله: ﴿عَنْ قِبْلَتِهِمُ الَّتِي كَانُوا عَلَيْهَا﴾ مع انتقالهم عنها؟","answer":"لأنها كانت قبلتهم المشروعة زمنًا طويلًا بأمر الله، فلا يخرجها التحويل اللاحق من كونها قبلتهم في مرحلتها. والإضافة تقرر أن الطاعة للآمر لا للحجر؛ كانت لهم حين أمروا بها، ثم صارت الكعبة قبلتهم حين جاء الأمر الجديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص394–396، تحت البقرة: 142، في إضافة القبلة إليهم ودلالة ﴿كانوا عليها﴾.","url":""}]},{"id":"s2-576","number":576,"surah":2,"verses":[142],"verseLabel":"البقرة: 142","question":"ما مناسبة الجواب بقوله تعالى: ﴿قُلْ لِلَّهِ الْمَشْرِقُ وَالْمَغْرِبُ﴾ دون ذكر سبب التحويل تفصيلًا؟","answer":"أعادهم إلى الأصل الذي يبطل الاعتراض كله: الجهات ملك لله، وهو الذي يحدد وجهة العبادة في الوقت الذي يشاء. فإذا ثبت سلطان المالك لم يعد تبديل الجهة تناقضًا، بل انتقالًا بين أمرين صحيحين من مشرع واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص395–399، تحت البقرة: 142، في تعليم الجواب وتقديم ﴿لله﴾.","url":""}]},{"id":"s2-577","number":577,"surah":2,"verses":[142],"verseLabel":"البقرة: 142","question":"ما سرّ التعبير في قوله تعالى: ﴿يَهْدِي مَنْ يَشَاءُ﴾ بعد ذكر ملك المشرق والمغرب؟","answer":"ليبين أن اختيار القبلة جزء من الهداية لا مجرد تحديد جغرافي؛ فالذي يملك الجهات يختار لعباده الطريق والوجهة التي تقربهم إليه. و﴿من﴾ تعم كل من يشاء الله هدايته من غير احتكار لقوم أو جهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص399–401، تحت البقرة: 142، في التعبير بالموصول ومناسبة الهداية للملك.","url":""}]},{"id":"s2-578","number":578,"surah":2,"verses":[142],"verseLabel":"البقرة: 142","question":"ما دلالة وصف الصراط بأنه ﴿مُسْتَقِيمٍ﴾ في سياق تحويل القبلة؟","answer":"الصراط الطريق الواضح، و﴿مستقيم﴾ يدل على اعتداله وعدم انحرافه. وفي سياق القبلة يقرر أن الهداية ليست إلى جهة مجردة، بل إلى طريق الطاعة الموصل إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص400–402، تحت البقرة: 142، في الفرق بين المستقيم والقيّم.","url":""}]},{"id":"s2-579","number":579,"surah":2,"verses":[143],"verseLabel":"البقرة: 143","question":"ما سرّ التعبير في قوله تعالى: ﴿وما كان الله ليضيع إيمانكم﴾ بنفي الكون، لا: لن يضيع؟","answer":"صيغة ﴿ما كان الله ليضيع﴾ تنفي وقوع الإضاعة نفيًا مؤكدًا، وتفيد أن ذلك لا يليق بحكمته ورحمته؛ فهي أبلغ من نفي وقوعه في المستقبل وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص421، تحت البقرة: 143.","url":""}]},{"id":"s2-580","number":580,"surah":2,"verses":[78],"verseLabel":"البقرة: 143، الحج: 78","question":"ما سرّ التعبير في قوله تعالى في البقرة: ﴿لِتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ وَيَكُونَ الرَّسُولُ عَلَيْكُمْ شَهِيدًا﴾ فقدم شهادة الأمة، بينما قال في الحج: ﴿لِيَكُونَ الرَّسُولُ شَهِيدًا عَلَيْكُمْ وَتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ﴾ فقدم شهادة الرسول؟","answer":"صدرُ آية البقرة ثناءٌ على الأمة الوسط وتنويهٌ بمكانتها، فكانت شهادتها هي الأهم في ذلك المقام فقُدِّمت. أما آية الحج ففي مقام التنويه بالدين الذي جاء به الرسول وتكليف الأمة باتباعه، فكان الرسول أسبق حضورًا في السياق، فقُدِّمت شهادته. فالترتيب في الموضعين يتبع مركز العناية، لا مجرد ترتيب ثابت للعبارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص387، تحت الحج: 78، في المقارنة بالبقرة: 143.","url":""}]},{"id":"s2-581","number":581,"surah":2,"verses":[143],"verseLabel":"البقرة: 143","question":"إلى ماذا يشير قوله تعالى: ﴿وَكَذَلِكَ جَعَلْنَاكُمْ أُمَّةً وَسَطًا﴾؟","answer":"تشير ﴿كذلك﴾ إلى الهداية السابقة إلى الصراط المستقيم والقبلة؛ فكما خصهم بتلك الهداية جعلهم أمة وسطًا. والإشارة تفيد تعظيم هذا الجعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص403–409، تحت البقرة: 143، في دلالة اسم الإشارة ومناسبة الجعل.","url":""}]},{"id":"s2-582","number":582,"surah":2,"verses":[143],"verseLabel":"البقرة: 143","question":"لماذا وصف الأمة بأنها ﴿وَسَطًا﴾، ولم يقل: «خيارًا» أو «عادلة»؟","answer":"الوسط يجمع الخيرية والعدل والتوازن والبعد عن طرفي الإفراط والتفريط، كما أن وسط الشيء موضع الحماية والظهور. فكلمة واحدة تجعل خيرية الأمة منهجًا متوازنًا يؤهلها للحكم والشهادة، لا امتيازًا عرقيًا مجردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص405–411، تحت البقرة: 143، في اختيار ﴿وسطًا﴾ واتساع دلالتها.","url":""}]},{"id":"s2-583","number":583,"surah":2,"verses":[143],"verseLabel":"البقرة: 143","question":"ما سرّ التعبير في قوله تعالى: ﴿لِتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ وَيَكُونَ الرَّسُولُ عَلَيْكُمْ شَهِيدًا﴾ بهذا الترتيب؟","answer":"قُدمت شهادة الأمة لأن السياق في تكريمها بالوسطية والشهادة على الناس، ثم ذكرت شهادة الرسول عليها لتكون شهادتها قائمة على تلقيها عنه ومضبوطة بشهادته.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص409–413، تحت البقرة: 143، في ترتيب الشهادتين ومناسبة الوسطية.","url":""}]},{"id":"s2-584","number":584,"surah":2,"verses":[143],"verseLabel":"البقرة: 143","question":"ما سرّ التعبير في قوله تعالى عن بيت المقدس: ﴿الْقِبْلَةَ الَّتِي كُنْتَ عَلَيْهَا﴾، ولم يسمه؟","answer":"لأن العبرة ليست باسم الجهة بل بوظيفتها الاختبارية، ولأنها معلومة للنبي والمخاطبين فلا حاجة إلى التصريح. والموصول يركز على حال الاتباع السابق: كانت قبلة بأمر الله، ثم صار التحول عنها بأمره أيضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص413–416، تحت البقرة: 143، في التعبير بالموصول وحذف اسم الجهة.","url":""}]},{"id":"s2-585","number":585,"surah":2,"verses":[143],"verseLabel":"البقرة: 143","question":"ما المراد بقوله تعالى: ﴿إِلَّا لِنَعْلَمَ مَنْ يَتَّبِعُ الرَّسُولَ﴾ مع إحاطة علم الله بالأشياء قبل وقوعها؟","answer":"ليس المراد حدوث علم لم يكن؛ فعلم الله سابق محيط، وإنما المراد ظهور المعلوم في الواقع وتميز المتبع من المنقلب، حتى يتعلق الجزاء بالفعل الواقع المشاهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص414–418، تحت البقرة: 143، في توجيه ﴿لنعلم﴾ وعلم الابتلاء.","url":""}]},{"id":"s2-586","number":586,"surah":2,"verses":[143],"verseLabel":"البقرة: 143","question":"ما سرّ التعبير في قوله تعالى: ﴿مَنْ يَتَّبِعُ الرَّسُولَ﴾، دون أن يقال: «من يطيع الله»؟","answer":"لأن موضع الامتحان أمر وصلهم بواسطة الرسول وقد خالف ما ألفوه؛ فظهر صدق الإيمان في اتباعه عند التحويل. ووصفه بالرسالة يقرر أن اتباعه ليس طاعة بشر من ذاته، بل طاعة المرسل الذي بلّغه الأمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص416–419، تحت البقرة: 143، في اختيار وصف الرسول واتصال الاتباع بالاختبار.","url":""}]},{"id":"s2-587","number":587,"surah":2,"verses":[143],"verseLabel":"البقرة: 143","question":"ما سرّ التعبير في قوله تعالى عن المرتد: ﴿يَنْقَلِبُ عَلَى عَقِبَيْهِ﴾، دون أن يقال: «يرتد»؟","answer":"الصورة تجعله شخصًا استدار فجأة على مؤخر قدميه فعاد من حيث جاء، بعد أن كان وجهه إلى الهدى؛ وفيها خطر السقوط والانتكاس. فهي لا تخبر عن الرجوع فقط، بل تجعل القارئ يراه حركةً مهينة إلى الخلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص418–420، تحت البقرة: 143، في الكناية والصورة في ﴿ينقلب على عقبيه﴾.","url":""}]},{"id":"s2-588","number":588,"surah":2,"verses":[143],"verseLabel":"البقرة: 143","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِنْ كَانَتْ لَكَبِيرَةً﴾، وما الشيء الذي كان كبيرًا؟","answer":"يعود الضمير إلى القبلة أو التولية والتحويل؛ أي كانت شاقة ثقيلة على النفوس التي ألفت جهةً أو تعلقت بعادة وقومية. ووصفت بالكبر لتكشف حقيقة الامتحان: الطاعة تظهر حين يثقل الأمر، لا حين يوافق المألوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص420–422، تحت البقرة: 143، في معنى الكبيرة ومرجع الضمير.","url":""}]},{"id":"s2-589","number":589,"surah":2,"verses":[143],"verseLabel":"البقرة: 143","question":"ما سرّ الاستثناء في قوله تعالى: ﴿وَإِنْ كَانَتْ لَكَبِيرَةً إِلَّا عَلَى الَّذِينَ هَدَى اللَّهُ﴾؟","answer":"لأن الهداية تحول ثقل التكليف إلى سهولة التسليم؛ فمن عرف أن الجهات كلها لله لم يتعلق بواحدة من تلقاء نفسه. ونسب الهداية إلى الله ليبين أن الثبات في الاختبار نعمة تستحق الشكر، لا قوة ذاتية يتفاخر بها الناجح.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص421–423، تحت البقرة: 143، في الاستثناء وإسناد الهداية إلى الله.","url":""}]},{"id":"s2-590","number":590,"surah":2,"verses":[143],"verseLabel":"البقرة: 143","question":"ما سرّ التعبير في قوله تعالى عن صلواتهم السابقة إلى بيت المقدس: ﴿وَمَا كَانَ اللَّهُ لِيُضِيعَ إِيمَانَكُمْ﴾، فسمّى الصلاة إيمانًا؟","answer":"لأن الصلاة أبرز عمل يصدر عن الإيمان ويصدقه، فأطلق اسم الأصل على ثمرته تشريفًا لها وإثباتًا أن العمل داخل في حقيقة الإيمان. كما طمأنهم أن الطاعة الصحيحة في زمن الأمر لا تبطل حين يتغير الحكم؛ فالله يثيب الامتثال في المرحلتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص423–426، تحت البقرة: 143، في إطلاق الإيمان على الصلاة ونفي إضاعتها.","url":""}]},{"id":"s2-591","number":591,"surah":2,"verses":[143],"verseLabel":"البقرة: 143","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿إِنَّ اللَّهَ بِالنَّاسِ لَرَءُوفٌ رَحِيمٌ﴾؟","answer":"جاءت الخاتمة بعد ذكر مشقة التحويل والخوف على الصلوات السابقة؛ فالرأفة تدفع عنهم ضياع العمل والمشقة، والرحمة توصل إليهم الثواب والخير. والتوكيد يطمئنهم إلى حفظ أعمالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص425–427، تحت البقرة: 143، في مناسبة الفاصلة وترتيب الرؤوف والرحيم.","url":""}]},{"id":"s2-592","number":592,"surah":2,"verses":[144],"verseLabel":"البقرة: 144","question":"ما سرّ التعبير في قوله تعالى: ﴿قد نرى تقلب وجهك في السماء﴾ ولم يذكر أن النبي طلب تغيير القبلة؟","answer":"في الآية إظهار لأدب النبي ﷺ؛ إذ كان يقلب وجهه مترقبًا الوحي من غير تصريح بطلب، فعلم الله رغبته وأجابه، وفي ذلك بيان عنايته به.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص432–434، تحت البقرة: 144.","url":""}]},{"id":"s2-593","number":593,"surah":2,"verses":[144],"verseLabel":"البقرة: 144","question":"ما سرّ التعبير في قوله تعالى: ﴿في السماء﴾ لا: إلى السماء؟","answer":"تفيد ﴿في﴾ أن وجهه كان يتردد في نواحي السماء مرة بعد مرة ترقبًا للوحي، أما ﴿إلى﴾ فقد تدل على مجرد جهة النظر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص434، تحت البقرة: 144.","url":""}]},{"id":"s2-594","number":594,"surah":2,"verses":[144],"verseLabel":"البقرة: 144","question":"ما سرّ التعبير في قوله تعالى: ﴿شطر المسجد الحرام﴾ لا: شطر الكعبة؟","answer":"المسجد الحرام يشتمل على الكعبة، وهو جهة ظاهرة يمكن أن يتوجه إليها البعيد؛ فناسب الحكم العام للناس في الآفاق، مع كون الكعبة عين القبلة للقريب.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص438، تحت البقرة: 144.","url":""}]},{"id":"s2-595","number":595,"surah":2,"verses":[144],"verseLabel":"البقرة: 144","question":"ما سرّ التعبير في قوله تعالى: ﴿تَقَلُّبَ وَجْهِكَ﴾، دون أن يقال: «رفع وجهك»؟","answer":"التقلب يدل على التكرار: يرفع وجهه مرة بعد مرة مترقبًا نزول الوحي، فيصور طول الانتظار وشدة الشوق مع الصبر. أما الرفع فقد يكون حركة واحدة لا تكشف دوام التطلع.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص430–433، تحت البقرة: 144، في اختيار صيغة التقلب.","url":""}]},{"id":"s2-596","number":596,"surah":2,"verses":[144],"verseLabel":"البقرة: 144","question":"ما سرّ التعبير في قوله تعالى: ﴿فَلَنُوَلِّيَنَّكَ قِبْلَةً﴾ بالنون واللام المؤكدتين؟","answer":"اللام والنون تؤكدان الوعد تأكيدًا قويًا؛ لأنه جاء بعد طول ترقب، ولأن التحويل سيواجه اعتراضًا. والفاء تصل الاستجابة بتقلب وجهه، فتدل على سرعة الإجابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص433–436، تحت البقرة: 144، في الفاء والقسم المقدر وتوكيد الفعل.","url":""}]},{"id":"s2-597","number":597,"surah":2,"verses":[144],"verseLabel":"البقرة: 144","question":"ما سرّ التعبير في قوله تعالى: ﴿قِبْلَةً تَرْضَاهَا﴾، دون أن يقال: «تحبها»؟","answer":"الرضا أخص من مجرد الميل والمحبة؛ فهو قبول وطمأنينة إلى ما يوافق الحق والحكمة. فالتعبير ينزه رغبة النبي ﷺ عن العصبية، ويبين موافقة القبلة لما يرضاه شرعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص433–437، تحت البقرة: 144، في اختيار الرضا دون الحب.","url":""}]},{"id":"s2-598","number":598,"surah":2,"verses":[144],"verseLabel":"البقرة: 144","question":"ما سرّ تقديم الوعد: ﴿فَلَنُوَلِّيَنَّكَ قِبْلَةً تَرْضَاهَا﴾ على الأمر: ﴿فَوَلِّ وَجْهَكَ﴾؟","answer":"قُدم الوعد تأنيسًا للنبي ﷺ وبشارة له بما كان يترقبه، ثم جاء الأمر تنفيذًا لذلك الوعد؛ فظهر أن التحويل اختيار إلهي لا اجتهادًا شخصيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص436–438، تحت البقرة: 144، في نكتة تقديم الوعد على الأمر.","url":""}]},{"id":"s2-599","number":599,"surah":2,"verses":[144],"verseLabel":"البقرة: 144","question":"ما سرّ الانتقال من خطاب النبي ﷺ مفردًا إلى خطاب الأمة: ﴿وَحَيْثُ مَا كُنْتُمْ فَوَلُّوا وُجُوهَكُمْ شَطْرَهُ﴾؟","answer":"بدأ بالنبي ﷺ لأنه متلقي الوحي وإمام الأمة، ثم عمم الخطاب ليدل على أن الحكم شامل لجميع المؤمنين في كل مكان، لا خاص بصلاة النبي أو بموضع معين.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص441–443، تحت البقرة: 144، في الاستئناف وتعميم حكم القبلة.","url":""}]},{"id":"s2-600","number":600,"surah":2,"verses":[144],"verseLabel":"البقرة: 144","question":"ما دلالة قوله تعالى عن أهل الكتاب: ﴿يَعْلَمُونَ أَنَّهُ الْحَقُّ مِنْ رَبِّهِمْ﴾؟","answer":"التعريف في ﴿الحق﴾ يقرر ثبوت الحكم، وقوله ﴿من ربهم﴾ يبين أن مصدره الله الذي يقرون بكتابه؛ فاعتراضهم مع العلم كتمان وعناد لا اشتباه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص442–444، تحت البقرة: 144، في القصر والتقييد بـ﴿من ربهم﴾.","url":""}]},{"id":"s2-601","number":601,"surah":2,"verses":[144],"verseLabel":"البقرة: 144","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وَمَا اللَّهُ بِغَافِلٍ عَمَّا يَعْمَلُونَ﴾؟","answer":"لأن علمهم بالحق قد يصحبه كتمان وتشويش عملي، فجاء الوعيد متعلقًا بالأعمال كلها لا بالمعلومة وحدها. والباء تقوي نفي الغفلة: لن يضيع إخلاص المؤمنين في التوجه، ولن يخفى تحريف المعترضين.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص443–444، تحت البقرة: 144، في نفي الغفلة ومناسبة الفاصلة.","url":""}]},{"id":"s2-602","number":602,"surah":2,"verses":[144,149,150],"verseLabel":"البقرة: 144 و149 و150","question":"ما سرّ تكرار أمر استقبال المسجد الحرام ثلاث مرات في الآيات 144 و149 و150؟","answer":"تكرر الأمر لأن لكل موضع وظيفة: الأول استجابة لتطلع النبي ﷺ وإعلان التحويل، والثاني تثبيت الحكم في الخروج والسفر، والثالث تعميمه على النبي والأمة وبيان حكمته في قطع الحجة وإتمام النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص497–502، تحت البقرة: 150، في أسرار تكرار أمر القبلة.","url":""}]},{"id":"s2-603","number":603,"surah":2,"verses":[145],"verseLabel":"البقرة: 145","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَئِنْ أَتَيْتَ الَّذِينَ أُوتُوا الْكِتَابَ بِكُلِّ آيَةٍ مَا تَبِعُوا قِبْلَتَكَ﴾؟","answer":"أسلوب الشرط مع ﴿كل آية﴾ للمبالغة في بيان رسوخ عنادهم: فمهما جاءتهم الأدلة لم يتبعوا القبلة؛ لأن المانع ليس خفاء الحجة بل اتباع الهوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص445–449، تحت البقرة: 145، في عموم ﴿كل آية﴾ وإضافة القبلة.","url":""}]},{"id":"s2-604","number":604,"surah":2,"verses":[145],"verseLabel":"البقرة: 145","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا تَبِعُوا قِبْلَتَكَ﴾ بالإفراد مع أن أهل الكتاب جماعات؟","answer":"لأن الكعبة قبلة واحدة يجتمع المسلمون عليها، فالمفرد يبرز وحدتها في مقابل اضطراب قبَل المعترضين. كما أن الفعل يصور المطلوب اتباع حكم واحد واضح لا الدخول في تفاصيل مذهب كامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص447–450، تحت البقرة: 145، في تخصيص القبلة وإفرادها.","url":""}]},{"id":"s2-605","number":605,"surah":2,"verses":[145],"verseLabel":"البقرة: 145","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا أَنْتَ بِتَابِعٍ قِبْلَتَهُمْ﴾ اسمًا، دون أن يقال: «ولا تتبع قبلتهم»؟","answer":"اسم الفاعل المنفي مع الباء في ﴿وما أنت بتابع﴾ يفيد ثبات نفي الاتباع واستمراره؛ فلا رجوع إلى قبلتهم ولا مداهنة فيها بعد ورود الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص450–453، تحت البقرة: 145، في دلالة النفي باسم الفاعل والباء.","url":""}]},{"id":"s2-606","number":606,"surah":2,"verses":[145],"verseLabel":"البقرة: 145","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا بَعْضُهُمْ بِتَابِعٍ قِبْلَةَ بَعْضٍ﴾؟","answer":"يكشف تناقضهم: يطالبون المسلمين باتباعهم، وهم أنفسهم لا يجتمعون على قبلة واحدة ولا يتبع اليهود قبلة النصارى أو العكس. فإذا كانت مخالفة القبلة دليل بطلان عندهم، لزم أن يبطل بعضهم بعضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص451–454، تحت البقرة: 145، في المقابلة وبيان اختلاف أهل الكتاب.","url":""}]},{"id":"s2-607","number":607,"surah":2,"verses":[145],"verseLabel":"البقرة: 145","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَئِنِ اتَّبَعْتَ أَهْوَاءَهُمْ﴾ بالجمع؟","answer":"لأن مطالبهم متفرقة متناقضة؛ لكل فريق غرض وقبلة وما يريده من النبي، فلا يجمعها حق واحد بل أهواء متعددة. وجاء الشرط المفروض مع استحالته ليقرر للأمة أن العلم لا يسمح بمجاملة الباطل مهما اشتد الضغط.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص454–457، تحت البقرة: 145، في الجمع في ﴿أهواءهم﴾ والقسم المقدر.","url":""}]},{"id":"s2-608","number":608,"surah":2,"verses":[145],"verseLabel":"البقرة: 145","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّكَ إِذًا لَمِنَ الظَّالِمِينَ﴾، دون أن يقال: «فإنك ظالم»؟","answer":"اجتمعت ﴿إن﴾ ولام الجواب و﴿لمن الظالمين﴾ لتأكيد خطورة اتباع الهوى بعد العلم. ولفظ ﴿لمن الظالمين﴾ يدخله ـ على سبيل الفرض ـ في زمرة الظالمين، وفي الخطاب تحذير للأمة بطريق الأولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص455–457، تحت البقرة: 145، في جواب القسم والتعبير بـ﴿لمن الظالمين﴾.","url":""}]},{"id":"s2-609","number":609,"surah":2,"verses":[146],"verseLabel":"البقرة: 146","question":"ما سرّ التعبير في قوله تعالى: ﴿يَعْرِفُونَهُ كَمَا يَعْرِفُونَ أَبْنَاءَهُمْ﴾، دون أن يقال: «يعلمون صدقه علمًا يقينيًا»؟","answer":"حوّل العلم المجرد إلى مشهد مألوف لا يخطئه الأب: معرفة ابنه بين الناس. فالتشبيه يؤكد شدة وضوح صفات النبي أو أمر القبلة في كتبهم، ويجعل الكتمان بعد هذه المعرفة أشد قبحًا من خطأ في الاستدلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص458–463، تحت البقرة: 146، في تشبيه المعرفة بمعرفة الأبناء.","url":""}]},{"id":"s2-610","number":610,"surah":2,"verses":[146],"verseLabel":"البقرة: 146","question":"ما سرّ تخصيص الأبناء في قوله تعالى: ﴿يَعْرِفُونَهُ كَمَا يَعْرِفُونَ أَبْنَاءَهُمْ﴾؟","answer":"الأبناء الذكور كانوا أشهر ملازمةً للآباء وظهورًا في مجتمعهم وأدق اتصالًا بالنسب الذي يحفظونه، فكانت معرفتهم بهم مضربًا في اليقين. واختيار الصورة التي لا يجادلون فيها يجعل الحجة من واقعهم هم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص462–464، تحت البقرة: 146، في تخصيص الأبناء بالذكر في التشبيه.","url":""}]},{"id":"s2-611","number":611,"surah":2,"verses":[146],"verseLabel":"البقرة: 146","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِنَّ فَرِيقًا مِنْهُمْ لَيَكْتُمُونَ الْحَقَّ﴾، ولم ينسب الكتمان إلى أهل الكتاب جميعًا؟","answer":"قيد الكتمان بـ﴿فريقًا منهم﴾ إنصافًا؛ فلم ينسبه إلى أهل الكتاب جميعًا، بل إلى الذين عرفوا الحق ثم تعمدوا ستره.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص464–466، تحت البقرة: 146، في تقييد الكاتمين وإطلاق الحكم.","url":""}]},{"id":"s2-612","number":612,"surah":2,"verses":[146],"verseLabel":"البقرة: 146","question":"ما سرّ التعبير في قوله تعالى: ﴿يَكْتُمُونَ الْحَقَّ﴾، دون أن يقال: «يكتمونه» مع قرب ذكره؟","answer":"أظهر لفظ ﴿الحق﴾ مكان الضمير لتشنيع فعلهم وتأكيد حقيقة ما كتموه؛ فهم لم يكتموا خبرًا محتملًا، بل كتموا الحق مع علمهم به.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص465–467، تحت البقرة: 146، في إظهار الاسم موضع الإضمار.","url":""}]},{"id":"s2-613","number":613,"surah":2,"verses":[60],"verseLabel":"البقرة: 147، آل عمران: 60","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿فَلَا تَكُونَنَّ مِنَ الْمُمْتَرِينَ﴾ بنون التوكيد الثقيلة، وقوله تعالى في آل عمران: ﴿فَلَا تَكُنْ مِنَ الْمُمْتَرِينَ﴾ من غيرها؟","answer":"زيدت نون التوكيد الثقيلة في البقرة لمناسبة شدة التوكيد في سياق القبلة، وخصوصًا قوله قبلها: ﴿فَلَنُوَلِّيَنَّكَ﴾. أما موضع آل عمران فجاء النهي فيه على أصله من غير هذا النسق التوكيدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص477–478، تحت البقرة: 147، في المقارنة بآل عمران: 60.","url":""}]},{"id":"s2-614","number":614,"surah":2,"verses":[147],"verseLabel":"البقرة: 147","question":"ما سرّ استقلال جملة ﴿الْحَقُّ مِنْ رَبِّكَ﴾، دون أن يقال: «وهو الحق من ربك»؟","answer":"فصلت الجملة لتأتي تقريرًا مستقلًا حاسمًا، وبدأت بـ﴿الحق﴾ للعناية به: الحق ثابت من ربك، لا يتوقف على اعتراف أهل الكتاب الذين يكتمونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص471–474، تحت البقرة: 147، في الفصل وبناء جملة ﴿الحق من ربك﴾.","url":""}]},{"id":"s2-615","number":615,"surah":2,"verses":[147],"verseLabel":"البقرة: 147","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ رَبِّكَ﴾، دون أن يقال: «من الله»؟","answer":"اختير وصف الربوبية وأضافه إلى ضمير النبي ﷺ؛ لما فيه من معنى التربية والرعاية والتثبيت: هذا الحق صادر من ربك الذي تولى أمرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص472–475، تحت البقرة: 147، في إضافة الرب إلى ضمير النبي.","url":""}]},{"id":"s2-616","number":616,"surah":2,"verses":[147],"verseLabel":"البقرة: 147","question":"ما سرّ توجيه النهي إلى النبي ﷺ في قوله: ﴿فَلَا تَكُونَنَّ مِنَ الْمُمْتَرِينَ﴾ مع ثبوت يقينه؟","answer":"الخطاب لتثبيت النبي ﷺ وتعريض بغيره، لا لإثبات شك عنده. فإذا وجه النهي المؤكد إليه مع كمال يقينه كان من وراءه أولى بقطع المراء.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص474–479، تحت البقرة: 147، في تكرار التركيب وسياق النهي.","url":""}]},{"id":"s2-617","number":617,"surah":2,"verses":[148],"verseLabel":"البقرة: 148","question":"ما سرّ التعبير في قوله تعالى: ﴿ولكل وجهة هو موليها﴾ فأبهم صاحب التولية؟","answer":"يحتمل الضمير أن يعود إلى الله؛ أي هو مولي كل أمة وجهتها، ويحتمل أن يعود إلى كل؛ أي كل فريق متوجه إليها. واحتمال اللفظ للمعنيين يصرف عن الخصومة في الجهات إلى امتثال الأمر واستباق الخيرات.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص487–496، تحت البقرة: 148.","url":""}]},{"id":"s2-618","number":618,"surah":2,"verses":[148],"verseLabel":"البقرة: 148","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلِكُلٍّ وِجْهَةٌ هُوَ مُوَلِّيهَا﴾، ولم يوحّد الناس على وجهة واحدة في كل الشرائع؟","answer":"لكل أمة وجهة شرعها الله لها في وقتها، واختلاف بعض الجهات لا يعني اختلاف المعبود. لذلك عقب الأمر بتحويل القبلة بالدعوة إلى المعيار الجامع: استباق الخيرات.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص480–484، تحت البقرة: 148، في معنى الوجهة واتصالها بما قبلها.","url":""}]},{"id":"s2-619","number":619,"surah":2,"verses":[148],"verseLabel":"البقرة: 148","question":"ما سرّ التعبير في قوله تعالى: ﴿فَاسْتَبِقُوا الْخَيْرَاتِ﴾ بعد الحديث عن القبلة، دون أن يقال: «فاستقبلوا جهتكم»؟","answer":"بعد بيان أن لكل أمة وجهة، نقلهم من الجدل في الجهات إلى الغاية العملية: المبادرة إلى وجوه الخير. فالقبلة طاعة ضمن الخيرات، وليست الجدل حولها هو المقصد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص483–486، تحت البقرة: 148، في دلالة لفظ الخيرات والانتقال من الوجهة إلى العمل.","url":""}]},{"id":"s2-620","number":620,"surah":2,"verses":[148],"verseLabel":"البقرة: 148","question":"ما سرّ التعبير في قوله تعالى: ﴿الْخَيْرَاتِ﴾ بالجمع؟","answer":"جاءت ﴿الخيرات﴾ جمعًا لتعم كل عمل صالح حسن في الشرع، مع دخول امتثال القبلة فيها دخولًا أوليًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص484–486، تحت البقرة: 148، في عموم الجمع ودلالته السياقية.","url":""}]},{"id":"s2-621","number":621,"surah":2,"verses":[148],"verseLabel":"البقرة: 148","question":"ما سرّ التعبير في قوله تعالى: ﴿أَيْنَ مَا تَكُونُوا يَأْتِ بِكُمُ اللَّهُ جَمِيعًا﴾ بعد اختلاف الوجهات؟","answer":"بعد تفرق الناس في الجهات والأمكنة، ذكّرهم بوحدة المصير: أينما يكونوا يجمعهم الله للحساب. فاختلاف المكان لا يمنع الاجتماع ولا يغير مسؤولية العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص486–488، تحت البقرة: 148، في الشرط وعموم المكان واتصال البعث بالوجهات.","url":""}]},{"id":"s2-622","number":622,"surah":2,"verses":[148],"verseLabel":"البقرة: 148","question":"ما سرّ التعبير في قوله تعالى: ﴿يَأْتِ بِكُمُ اللَّهُ﴾، دون أن يقال: «يبعثكم الله»؟","answer":"الإتيان بالشيء يتضمن إحضاره؛ فصور جمع الخلق المتفرقين من أنحاء الأرض وإحضارهم إلى موقف واحد، وهو أنسب بالسياق من مجرد ذكر البعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص487–489، تحت البقرة: 148، في المجاز في ﴿يأت بكم الله﴾.","url":""}]},{"id":"s2-623","number":623,"surah":2,"verses":[148],"verseLabel":"البقرة: 148","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ﴾؟","answer":"لما كان جمع الخلق من كل مكان قد يستبعد، ختم بكمال القدرة ردًا على الاستبعاد، وتأكيدًا أن الله قادر على جمعهم ومجازاتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص488–489، تحت البقرة: 148، في مناسبة فاصلة القدرة.","url":""}]},{"id":"s2-624","number":624,"surah":2,"verses":[149],"verseLabel":"البقرة: 149","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿وَإِنَّهُ لَلْحَقُّ مِنْ رَبِّكَ﴾ بزيادة اللام، بعدما قال في الآية 144: ﴿أَنَّهُ الْحَقُّ مِنْ رَبِّهِمْ﴾؟","answer":"زيدت لام التوكيد في ﴿للحق﴾ لأن المقام مقام تثبيت النبي ﷺ بعد تكرار الأمر، وأضيف الرب إلى ضميره: ﴿من ربك﴾. أما الآية 144 فالمقصود تقرير علم أهل الكتاب بالحق من ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص493–496، تحت البقرة: 149، في المؤكدات وإضافة الرب إلى النبي.","url":""}]},{"id":"s2-625","number":625,"surah":2,"verses":[149],"verseLabel":"البقرة: 149","question":"ما مناسبة تكرار قوله تعالى: ﴿وَمَا اللَّهُ بِغَافِلٍ عَمَّا تَعْمَلُونَ﴾؟","answer":"الفاصلة تراقب الفريقين في مقام العمل: لا يغفل الله عن امتثال المؤمنين للأمر في سفرهم وحضرهم، ولا عن أعمال المعترضين وكتمانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص495–496، تحت البقرة: 149، في دلالة الفاصلة وتناسبها.","url":""}]},{"id":"s2-626","number":626,"surah":2,"verses":[3,44],"verseLabel":"البقرة: 150، المائدة: 3 و44","question":"ما سرّ اختلاف التعبير بين إثبات الياء في ﴿وَاخْشَوْنِي﴾ بالبقرة وحذفها في ﴿وَاخْشَوْنِ﴾ بالمائدة؟","answer":"أثبتت الياء في البقرة لأن تحويل القبلة كان موضع جدال شديد، فناسب زيادة المبنى زيادة التوكيد في خشية الله دون الناس. وحذفت في المائدة بعد ظهور الإسلام ويأس الكافرين، فناسب التخفيف.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص212–213، تحت المائدة: 44، في المقارنة بالبقرة: 150 والمائدة: 3.","url":""}]},{"id":"s2-627","number":627,"surah":2,"verses":[3],"verseLabel":"البقرة: 150، المائدة: 3","question":"ما سرّ اختلاف التعبير بين ﴿وَلِأُتِمَّ نِعْمَتِي عَلَيْكُمْ﴾ في البقرة و﴿وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي﴾ في المائدة؟","answer":"جاء المضارع في البقرة لأن تمام النعمة كان مستقبلًا ينتظر اكتماله بفتح مكة وانتشار الإسلام، وجاء الماضي في المائدة ـ وهي من أواخر ما نزل ـ لإعلان تحقق تمام النعمة واستقرارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص557–558، تحت المائدة: 3، في المقارنة بالبقرة: 150.","url":""}]},{"id":"s2-628","number":628,"surah":2,"verses":[3],"verseLabel":"البقرة: 150، المائدة: 3","question":"ما سرّ تقديم ﴿نِعْمَتِي﴾ في البقرة، وتقديم ﴿عَلَيْكُمْ﴾ في المائدة؟","answer":"قدمت البقرة ﴿نعمتي﴾ لأن المقام بشارة بنعمة ينتظر تمامها فكانت موضع العناية، وقدمت المائدة ﴿عليكم﴾ لأن المقام تقرير إحاطة النعمة بالمؤمنين بعد تحققها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص558، تحت المائدة: 3، في المقارنة بالبقرة: 150.","url":""}]},{"id":"s2-629","number":629,"surah":2,"verses":[150],"verseLabel":"البقرة: 150","question":"ما وجه الاستثناء في قوله تعالى: ﴿لِئَلَّا يَكُونَ لِلنَّاسِ عَلَيْكُمْ حُجَّةٌ إِلَّا الَّذِينَ ظَلَمُوا مِنْهُمْ﴾؛ وهل للظالمين حجة صحيحة؟","answer":"الاستثناء يجوز أن يكون متصلًا على تسمية شبهتهم حجة بحسب دعواهم، لا لأنها حجة صحيحة، ويجوز أن يكون منقطعًا: لا حجة لأحد، لكن الذين ظلموا يستمرون في الخصومة والعناد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص500–503، تحت البقرة: 150، في توجيه الاستثناء ومعنى الحجة.","url":""}]},{"id":"s2-630","number":630,"surah":2,"verses":[150],"verseLabel":"البقرة: 150","question":"ما سرّ التعبير في قوله تعالى: ﴿فَلَا تَخْشَوْهُمْ وَاخْشَوْنِي﴾، فجمع بين النهي والأمر؟","answer":"جمعت الآية بين النهي والأمر لنقل الخشية من الخلق إلى الخالق: أفرغت القلب من خوف المعترضين، ثم وجهته إلى خشية الله الذي بيده الحكم والنفع والضر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص502–504، تحت البقرة: 150، في مقابلة النهي بالأمر وتقديمهما.","url":""}]},{"id":"s2-631","number":631,"surah":2,"verses":[150],"verseLabel":"البقرة: 150","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلِأُتِمَّ نِعْمَتِي عَلَيْكُمْ وَلَعَلَّكُمْ تَهْتَدُونَ﴾؛ ما علاقة القبلة بإتمام النعمة؟","answer":"استقلال الأمة بقبلة إبراهيم أكمل بناء هويتها وعبادتها بعد الكتاب والرسول، وأزال تبعيتها الرمزية لغيرها؛ فكان التحويل نعمة تشريعية جامعة. و﴿لعلكم تهتدون﴾ تذكر أن القبلة ليست شرفًا بلا تكليف، بل علامة طريق يقود استمرارُ امتثاله إلى الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص504–506، تحت البقرة: 150، في تعليل الحكم بإتمام النعمة والهداية.","url":""}]},{"id":"s2-632","number":632,"surah":2,"verses":[151],"verseLabel":"البقرة: 151","question":"ما سرّ التعبير في قوله تعالى: ﴿فيكم رسولًا منكم﴾، دون أن يقال: إليكم رسولًا؟","answer":"﴿فيكم﴾ تدل على وجود الرسول بينهم وإقامته ومخالطته لهم، وهي أبلغ في الامتنان من مجرد الإرسال إليهم؛ لأنهم يشاهدون سيرته ويتلقون عنه ويقتدون به.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص512، تحت البقرة: 151.","url":""}]},{"id":"s2-633","number":633,"surah":2,"verses":[151],"verseLabel":"البقرة: 151","question":"ما مناسبة تشبيه إتمام نعمة القبلة بإرسال الرسول في قوله تعالى: ﴿كَمَا أَرْسَلْنَا فِيكُمْ رَسُولًا مِنْكُمْ﴾؟","answer":"شبه إتمام نعمة القبلة بنعمة إرسال الرسول؛ لأن كليهما من تمام الهداية وتكوين الأمة: الرسول يبين لها الوحي، والقبلة تجمع عبادتها وتتميز بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص507–510، تحت البقرة: 151، في التشبيه بين نعمتي القبلة والرسالة.","url":""}]},{"id":"s2-634","number":634,"surah":2,"verses":[151],"verseLabel":"البقرة: 151","question":"ما سرّ التعبير في قوله تعالى: ﴿رَسُولًا مِنْكُمْ﴾؟","answer":"كونه منهم يجعلهم يعرفون نسبه ولسانه وصدقه، ويفهم هو طبائعهم وأحوالهم، فتقوم الحجة بلا حاجز غربة. وفيها امتنان خاص: لم يرسل إليهم من يجهلون طريقته، بل واحدًا عاش بينهم وعرفوه قبل الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص507–511، تحت البقرة: 151، في فائدة ﴿فيكم﴾ و﴿منكم﴾.","url":""}]},{"id":"s2-635","number":635,"surah":2,"verses":[151],"verseLabel":"البقرة: 151","question":"ما سرّ ترتيب وظائف الرسول في قوله تعالى: ﴿يَتْلُو عَلَيْكُمْ آيَاتِنَا وَيُزَكِّيكُمْ وَيُعَلِّمُكُمُ الْكِتَابَ وَالْحِكْمَةَ﴾؟","answer":"بدأ بالتلاوة لأنها طريق وصول الوحي، ثم بالتزكية لتطهير النفوس، ثم بتعليم الكتاب والحكمة بعد تهيئتها للعلم والعمل. فالترتيب يراعي انتقال أثر الرسالة من السماع إلى التطهير ثم التعليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص511–515، تحت البقرة: 151، في ترتيب التلاوة والتزكية والتعليم.","url":""}]},{"id":"s2-636","number":636,"surah":2,"verses":[151],"verseLabel":"البقرة: 151","question":"ما فائدة قوله تعالى: ﴿وَيُعَلِّمُكُمْ مَا لَمْ تَكُونُوا تَعْلَمُونَ﴾ بعد تعليم الكتاب والحكمة؟","answer":"عطف العام على الخاص؛ فبعد تعليم الكتاب والحكمة ذكر ما لم يكونوا يعلمون ليشمل ما أفادهم الرسول من سائر المعارف والشرائع التي لم تكن معلومة لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص514–517، تحت البقرة: 151، في عطف التعليم العام على الخاص.","url":""}]},{"id":"s2-637","number":637,"surah":2,"verses":[152],"verseLabel":"البقرة: 152","question":"ما سرّ التعبير في قوله تعالى: ﴿فاذكروني أذكركم﴾ فجعل ذكر الله للعبد جوابًا لذكر العبد؟","answer":"جاء الوعد على المقابلة: من ذكر الله بالطاعة والثناء ذكره الله بالرحمة والثواب والعناية. وذكر الله لعبده أعظم من ذكر العبد لربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص518–524، تحت البقرة: 152.","url":""}]},{"id":"s2-638","number":638,"surah":2,"verses":[152],"verseLabel":"البقرة: 152","question":"ما سرّ تقديم الذكر على الشكر في قوله تعالى: ﴿فَاذْكُرُونِي... وَاشْكُرُوا لِي﴾؟","answer":"قدم الذكر لأنه أصل الشكر؛ فلا يشكر العبد حتى يستحضر المنعم ونعمته، ثم يظهر أثر ذلك الاعتراف في شكره.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص520–523، تحت البقرة: 152، في ترتيب الذكر والشكر.","url":""}]},{"id":"s2-639","number":639,"surah":2,"verses":[152],"verseLabel":"البقرة: 152","question":"ما سرّ التعبير في قوله تعالى: ﴿وَاشْكُرُوا لِي﴾ باللام، دون أن يقال: «واشكروني»؟","answer":"اللام تفيد اختصاص الشكر بالله وإخلاصه له؛ فكل نعمة تنتهي إليه وإن جرت على أيدي الأسباب.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص521–523، تحت البقرة: 152، في تعدية الشكر باللام.","url":""}]},{"id":"s2-640","number":640,"surah":2,"verses":[152],"verseLabel":"البقرة: 152","question":"ما سرّ مقابلة الشكر بقوله تعالى: ﴿وَلَا تَكْفُرُونِ﴾؟","answer":"الكفر في أصله الستر، وهو ضد الشكر الذي يظهر النعمة ويعترف بالمنعم. فالمقابلة تحذر من كفر النعمة ومن صرفها في غير طاعة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص522–524، تحت البقرة: 152، في المقابلة بين الشكر والكفر.","url":""}]},{"id":"s2-641","number":641,"surah":2,"verses":[153],"verseLabel":"البقرة: 153","question":"ما سرّ التعبير في قوله تعالى: ﴿استعينوا بالصبر والصلاة﴾، دون أن يقال: اصبروا وصلوا؟","answer":"جعل الصبر والصلاة وسيلتين يطلب بهما عون الله على سائر التكاليف والمحن، لا فعلين منفصلين ينتهيان عند أدائهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص529، تحت البقرة: 153.","url":""}]},{"id":"s2-642","number":642,"surah":2,"verses":[153],"verseLabel":"البقرة: 153","question":"ما سرّ اختلاف ختام هذه الآية: ﴿إِنَّ اللَّهَ مَعَ الصَّابِرِينَ﴾ عن ختام نظيرتها السابقة في البقرة: 45؟","answer":"في الآية السابقة كان المقام بيان ثقل الصلاة واستثناء الخاشعين، فناسب ذكر الخشوع. وهنا السياق تمهيد للابتلاء والجهاد، فناسب وعد الصابرين بمعية الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص531، تحت البقرة: 153.","url":""}]},{"id":"s2-643","number":643,"surah":2,"verses":[153],"verseLabel":"البقرة: 153","question":"ما سرّ تجديد النداء بقوله تعالى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا﴾ بعد قوله: ﴿فاذكروني﴾؟","answer":"لأن السياق ينتقل من شكر النعمة إلى الاستعداد للابتلاء، فاحتاج الأمر الجديد إلى تنبيه مستقل يستثير صفة الإيمان التي تدفع إلى الامتثال. وكأن النداء يقول: مقتضى إيمانكم أن تلجؤوا إلى الصبر والصلاة عند الشدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص525–528، تحت البقرة: 153، في دلالة أسلوب النداء ومناسبة الانتقال.","url":""}]},{"id":"s2-644","number":644,"surah":2,"verses":[153],"verseLabel":"البقرة: 153","question":"ما سرّ تقديم الصبر على الصلاة؟","answer":"قدم الصبر لأنه أعم؛ فهو لازم للصلاة ولسائر التكاليف والمصائب، وبه يثبت العبد حتى يحسن الاستعانة بالصلاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص528–530، تحت البقرة: 153، في ترتيب وسيلتي الاستعانة.","url":""}]},{"id":"s2-645","number":645,"surah":2,"verses":[153],"verseLabel":"البقرة: 153","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿إِنَّ اللَّهَ مَعَ الصَّابِرِينَ﴾ دون «المصلين»؟","answer":"خص الصابرين لأن الصبر هو الجامع لما يأتي من البلاء والجهاد، ولأنهم أحوج إلى المعية الخاصة بالنصر والتأييد. والمداومة على الصلاة داخلة في الصبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص530–531، تحت البقرة: 153، في مناسبة الفاصلة وتخصيص الصابرين بالمعية.","url":""}]},{"id":"s2-646","number":646,"surah":2,"verses":[154],"verseLabel":"البقرة: 154","question":"ما وجه النهي عن تسمية من يقتل في سبيل الله أمواتًا مع وقوع الموت الحسي؟","answer":"النهي عن وصفهم بالأموات متعلق بحقيقتهم البرزخية، لا بنفي مفارقة أرواحهم للأجساد؛ فهم أحياء عند ربهم حياة لا تدرك بالحس المعتاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص532–541، تحت البقرة: 154.","url":""}]},{"id":"s2-647","number":647,"surah":2,"verses":[154],"verseLabel":"البقرة: 154","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا تَقُولُوا لِمَنْ يُقْتَلُ فِي سَبِيلِ اللَّهِ أَمْوَاتٌ﴾، دون أن يقال مباشرة: «الشهداء أحياء»؟","answer":"بدأ بمنع العبارة التي تصنع تصورًا خاطئًا؛ لأن اللسان يربي القلب، وتسميتهم أمواتًا تورث الحزن المثبط. ثم أثبت الحقيقة المقابلة بـ﴿بل أحياء﴾، فجمع إزالة الوهم وبناء اليقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص532–535، تحت البقرة: 154، في النهي عن القول ثم الإضراب إلى الحياة.","url":""}]},{"id":"s2-648","number":648,"surah":2,"verses":[154],"verseLabel":"البقرة: 154","question":"ما دلالة تقييد القتل بقوله تعالى: ﴿فِي سَبِيلِ اللَّهِ﴾؟","answer":"لأن شرف الشهادة متعلق بالمقصد لا بمجرد صورة القتل؛ فليس كل مقتول شهيدًا، وإنما من خرج مخلصًا لإعلاء الحق. والقيد يربي الأمة على أن قيمة الأعمال بنياتها وغاياتها لا بضخامتها الظاهرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص533–535، تحت البقرة: 154، في فائدة قيد ﴿في سبيل الله﴾.","url":""}]},{"id":"s2-649","number":649,"surah":2,"verses":[154],"verseLabel":"البقرة: 154","question":"ما سرّ التعبير في قوله تعالى: ﴿بَلْ أَحْيَاءٌ﴾ من غير أن يقول: «بل هم أحياء»؟","answer":"حذف المبتدأ يسرع المفاجأة ويجعل الحياة هي الخبر البارز الذي يرد فورًا على كلمة ﴿أموات﴾؛ كأن العبارة تصحح الاسم في اللحظة نفسها: أموات؟ بل أحياء. والإيجاز يزيد قوة المقابلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص534–536، تحت البقرة: 154، في الحذف والإضراب بـ﴿بل﴾.","url":""}]},{"id":"s2-650","number":650,"surah":2,"verses":[154],"verseLabel":"البقرة: 154","question":"ما دلالة قوله تعالى بعد إثبات حياتهم: ﴿وَلَكِنْ لَا تَشْعُرُونَ﴾؟","answer":"حياتهم البرزخية ثابتة، لكن أدوات الحس لا تدرك كيفيتها. لذلك نفى الشعور لا العلم؛ لأن العلم بها حاصل بخبر الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص535–537، تحت البقرة: 154، في الاستدراك ونفي الشعور.","url":""}]},{"id":"s2-651","number":651,"surah":2,"verses":[155],"verseLabel":"البقرة: 155","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَنَبْلُوَنَّكُمْ﴾ مؤكدًا، والله يعلم أحوالهم قبل الابتلاء؟","answer":"أكد الابتلاء لتهيئة المؤمنين له وتحقيق وقوعه. وليس المراد اكتساب علم جديد، بل إظهار ما سبق به علم الله في أفعال واقعة يترتب عليها الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص538–541، تحت البقرة: 155، في المضارع ونون العظمة والتوكيد.","url":""}]},{"id":"s2-652","number":652,"surah":2,"verses":[155],"verseLabel":"البقرة: 155","question":"ما سرّ التعبير في قوله تعالى: ﴿بِشَيْءٍ مِنَ الْخَوْفِ وَالْجُوعِ﴾، دون أن يقال: «بالخوف والجوع»؟","answer":"دل لفظ ﴿شيء﴾ ودخول ﴿من﴾ على أن البلاء بعض محدود، لا استئصالًا شاملًا؛ وفي ذلك تسلية للمؤمنين قبل تعداد أنواعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص540–542، تحت البقرة: 155، في إفراد ﴿شيء﴾ وذكره مع ﴿من﴾.","url":""}]},{"id":"s2-653","number":653,"surah":2,"verses":[155],"verseLabel":"البقرة: 155","question":"ما سرّ ترتيب أنواع الابتلاء: الخوف، ثم الجوع، ثم نقص الأموال والأنفس والثمرات؟","answer":"انتقل من الخوف الذي يمس الأمن، إلى الجوع، ثم إلى نقص الأموال والأنفس والثمرات، فاستوعب أنواعًا تتعلق بأحوال النفس والمعاش وما يملكه الإنسان ويرجوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص542–544، تحت البقرة: 155، في سر ترتيب أنواع البلاء.","url":""}]},{"id":"s2-654","number":654,"surah":2,"verses":[155],"verseLabel":"البقرة: 155","question":"ما سرّ التعبير في قوله تعالى: ﴿وَبَشِّرِ الصَّابِرِينَ﴾ ولم يذكر بماذا يبشرهم؟","answer":"حذف المبشَّر به ليعظم ويتنوع: نصر ومغفرة وصلوات ورحمة وهداية وجنة، ثم تكشف الآية التالية بعضه. لو ذُكر جزاء واحد لضاق الرجاء، أما الحذف فيفتح كل خير يليق بصبرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص544–545، تحت البقرة: 155، في حذف المبشر به.","url":""}]},{"id":"s2-655","number":655,"surah":2,"verses":[156],"verseLabel":"البقرة: 156","question":"ما سرّ التعبير عما يصيب الإنسان بلفظ ﴿مصيبة﴾؟","answer":"المصيبة من الإصابة، وهي ما يقع بالإنسان ويصيبه فعلًا. أما الابتلاء فيلحظ كون ذلك اختبارًا؛ فكل مصيبة في السياق ابتلاء، لكن اللفظ هنا يصور وقوعها بالمصاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص549، تحت البقرة: 156.","url":""}]},{"id":"s2-656","number":656,"surah":2,"verses":[156],"verseLabel":"البقرة: 156","question":"ما دلالة قول الصابرين عند المصيبة: ﴿إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ﴾؟","answer":"قولهم ﴿إنا لله﴾ إقرار بأنهم وما يملكون ملك لله، وقولهم ﴿وإنا إليه راجعون﴾ تذكير بأن المصير إليه؛ فيخف وقع الفقد حين يرد الملك والمآل إلى صاحبهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص549–558، تحت البقرة: 156.","url":""}]},{"id":"s2-657","number":657,"surah":2,"verses":[156],"verseLabel":"البقرة: 156","question":"ما سرّ التعبير في قوله تعالى: ﴿الَّذِينَ إِذَا أَصَابَتْهُمْ مُصِيبَةٌ﴾ بـ﴿إذا﴾ لا بـ«إن»؟","answer":"﴿إذا﴾ تستعمل للمتحقق المتوقع، والمصائب سنة لا يسلم منها إنسان؛ فربى المؤمن على الاستعداد لها لا توهم ندرتها. أما ﴿إن﴾ فقد توحي بأن الوقوع مشكوك فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص546–548، تحت البقرة: 156، في اختيار ﴿إذا﴾ دون ﴿إن﴾.","url":""}]},{"id":"s2-658","number":658,"surah":2,"verses":[156],"verseLabel":"البقرة: 156","question":"ما دلالة تنكير ﴿مصيبة﴾ في قوله تعالى: ﴿إِذَا أَصَابَتْهُمْ مُصِيبَةٌ﴾؟","answer":"ليعم كل ما يصيب الإنسان، صغيرًا أو كبيرًا، فلا تختص الاسترجاع بموت أو كارثة معينة. ويشعر التنكير أيضًا بأن الصابرين يستقبلون أي فرد من أفراد البلاء بالميزان نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص547–549، تحت البقرة: 156، في تنكير لفظ المصيبة.","url":""}]},{"id":"s2-659","number":659,"surah":2,"verses":[157],"verseLabel":"البقرة: 157","question":"ما سرّ التعبير في قوله تعالى: ﴿عَلَيْهِمْ صَلَوَاتٌ مِنْ رَبِّهِمْ وَرَحْمَةٌ﴾، فجمع الصلوات وأفرد الرحمة؟","answer":"جُمعت الصلوات لتعددها وتكررها من الله على الصابرين، وأفردت الرحمة لأنها جنس جامع يشتمل على وجوه الخير كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص550–553، تحت البقرة: 157، في تنكير ﴿صلوات﴾ وجمعها وإفراد الرحمة.","url":""}]},{"id":"s2-660","number":660,"surah":2,"verses":[157],"verseLabel":"البقرة: 157","question":"ما دلالة تكرار اسم الإشارة في قوله تعالى: ﴿وَأُولَئِكَ هُمُ الْمُهْتَدُونَ﴾ بعد ﴿أُولَئِكَ عَلَيْهِمْ صَلَوَاتٌ﴾؟","answer":"ليجعل لكل جزاء استقلاله: لهم عطاء الرب، وهم فوق ذلك أصحاب الهداية الراسخة التي أوصلتهم إلى الصبر. والتكرار يرفع منزلتهم، وضمير الفصل والتعريف يقصران الهداية الكاملة في هذا المقام عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص553–556، تحت البقرة: 157، في ترتيب الجزاء وضمير الفصل.","url":""}]},{"id":"s2-661","number":661,"surah":2,"verses":[158],"verseLabel":"البقرة: 158","question":"ما دلالة وصف الصفا والمروة بأنهما ﴿مِنْ شَعَائِرِ اللَّهِ﴾؟","answer":"لأن المسلمين تحرجوا من السعي لما ارتبط بهما في الجاهلية من أصنام، فجاء الوحي يفصل الشعيرة الإبراهيمية عن تشويه المشركين. كما يرتبطان بابتلاء هاجر وسعيها، فصارا شاهدين على الثقة بالله وتحول الشدة إلى زمزم وعمران.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص557–562، تحت البقرة: 158، في تخصيص الصفا والمروة بالذكر ومناسبتهما.","url":""}]},{"id":"s2-662","number":662,"surah":2,"verses":[158],"verseLabel":"البقرة: 158","question":"ما سرّ التعبير في قوله تعالى: ﴿فَلَا جُنَاحَ عَلَيْهِ أَنْ يَطَّوَّفَ بِهِمَا﴾، مع أن السعي عبادة وليس مجرد أمر مباح؟","answer":"نفي الجناح جاء لإزالة الحرج الذي وجدوه بسبب ما علق بالصفا والمروة في الجاهلية، لا لبيان أن السعي مجرد مباح؛ فالمقام رفع توهم المنع.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص562–566، تحت البقرة: 158، في الفرق بين نفي الجنس والسياق التشريعي.","url":""}]},{"id":"s2-663","number":663,"surah":2,"verses":[158],"verseLabel":"البقرة: 158","question":"ما سرّ التعبير في قوله تعالى: ﴿أَنْ يَطَّوَّفَ بِهِمَا﴾ بصيغة التفعّل، دون أن يقال: «أن يطوف»؟","answer":"صيغة ﴿يطوّف﴾ تدل على التكلف والتكرر في الذهاب والعودة بين الصفا والمروة، فناسبت عمل السعي المتكرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص564–567، تحت البقرة: 158، في اختيار صيغة ﴿يطوف﴾ المشددة.","url":""}]},{"id":"s2-664","number":664,"surah":2,"verses":[158],"verseLabel":"البقرة: 158","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَنْ تَطَوَّعَ خَيْرًا﴾ ولم يحدد نوع الخير؟","answer":"أطلق الخير ليشمل الزيادة في الطاعة وكل عمل يختاره العبد فوق الواجب، ولا يحصره في السعي وحده. فالقاعدة تتسع: ما يبذله العبد طوعًا لا يضيع عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص566–568، تحت البقرة: 158، في إطلاق الخير ودلالة التطوع.","url":""}]},{"id":"s2-665","number":665,"surah":2,"verses":[158],"verseLabel":"البقرة: 158","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿فَإِنَّ اللَّهَ شَاكِرٌ عَلِيمٌ﴾، وما معنى شكر الله لعبده؟","answer":"شكر الله لعبده قبوله عمله وإثابته عليه ومضاعفة جزائه. وقدم ﴿شاكر﴾ لاتصاله بالتطوع، ثم ﴿عليم﴾ لأنه يعلم العمل والنية.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص568–569، تحت البقرة: 158، في اختيار الاسمين وترتيبهما.","url":""}]},{"id":"s2-666","number":666,"surah":2,"verses":[159],"verseLabel":"البقرة: 159","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّ الَّذِينَ يَكْتُمُونَ مَا أَنْزَلْنَا﴾ بنون العظمة؟","answer":"لبيان شرف المنزل وعظم الجريمة في الوقت نفسه: الذي يكتمونه ليس رأيًا بشريًا، بل وحي أنزله الله العظيم. فكلما عظم مصدر البيان اشتد قبح من حبسه عن الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص570–573، تحت البقرة: 159، في تعظيم المنزل وتقبيح الكاتم بصيغة ﴿أنزلنا﴾.","url":""}]},{"id":"s2-667","number":667,"surah":2,"verses":[159],"verseLabel":"البقرة: 159","question":"ما سرّ الجمع بين ﴿الْبَيِّنَاتِ وَالْهُدَى﴾؟","answer":"البينات هي الأدلة الواضحة، والهدى ما يرشد إلى الطريق والعمل؛ فالجمع يشمل كتمان الدليل وكتمان ما يهدي الناس في الاعتقاد والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص572–575، تحت البقرة: 159، في الجمع بين البينات والهدى.","url":""}]},{"id":"s2-668","number":668,"surah":2,"verses":[159],"verseLabel":"البقرة: 159","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ بَعْدِ مَا بَيَّنَّاهُ لِلنَّاسِ فِي الْكِتَابِ﴾؟","answer":"لأن الكتمان بعد البيان أغلظ؛ لم تكن المعلومة غامضة ولا ملكًا خاصًا للعالم، بل جعلها الله للناس وأودعها كتابًا محفوظًا. فالقيود تنزع كل عذر: عرفوها، وكانت عامة، ومثبتة في مصدر يمكن الرجوع إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص573–576، تحت البقرة: 159، في قيود ما بعد البيان وللناس وفي الكتاب.","url":""}]},{"id":"s2-669","number":669,"surah":2,"verses":[159],"verseLabel":"البقرة: 159","question":"ما سرّ التعبير في قوله تعالى: ﴿أُولَئِكَ يَلْعَنُهُمُ اللَّهُ وَيَلْعَنُهُمُ اللَّاعِنُونَ﴾ وكرر اللعن؟","answer":"كرر فعل اللعن لأن لعنة الله ولعنة اللاعنين حكمان مستقلان: يطردهم الله من رحمته، ويدعو عليهم اللاعنون بسبب ما نشره كتمانهم من ضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص575–579، تحت البقرة: 159، في اسم الإشارة وتكرير اللعن.","url":""}]},{"id":"s2-670","number":670,"surah":2,"verses":[5],"verseLabel":"البقرة: 160، النور: 5","question":"ما سرّ زيادة ﴿وَبَيَّنُوا﴾ في توبة كاتمي الهدى بالبقرة، وعدم ذكرها في النور: 5؟","answer":"زيد ﴿وبينوا﴾ لأن ذنبهم كتمان البينات والهدى، فلا تتم توبتهم حتى يظهروا ما كتموه. أما آية النور ففي ذنب القذف، فليس فيها علم مكتوم يحتاج إلى بيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص426–427، تحت النور: 5، في المقارنة بالبقرة: 160.","url":""}]},{"id":"s2-671","number":671,"surah":2,"verses":[89],"verseLabel":"البقرة: 160، آل عمران: 89","question":"ما سرّ اختلاف خاتمة توبة كاتمي الهدى: ﴿وَأَنَا التَّوَّابُ الرَّحِيمُ﴾، عن خاتمة آل عمران: ﴿فَإِنَّ اللَّهَ غَفُورٌ رَحِيمٌ﴾؟","answer":"ناسب ﴿التواب﴾ في البقرة التصريح بالتوبة بعد كتمان الهدى، فهو أخص بقبول الرجوع. وفي آل عمران جاء ﴿غفور﴾ في سياق الكفر بعد الإيمان؛ فناسب الاسم الدال على ستر الذنب ومغفرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص433، تحت آل عمران: 89، في المقارنة بالبقرة: 160.","url":""}]},{"id":"s2-672","number":672,"surah":2,"verses":[89],"verseLabel":"البقرة: 160، آل عمران: 89","question":"ما سرّ زيادة ﴿مِنْ بَعْدِ ذَلِكَ﴾ في آل عمران: 89، وعدم ذكرها في نظيرتها من البقرة؟","answer":"ذكرت آل عمران ﴿من بعد ذلك﴾ لأن السياق وصف انتقالًا زمنيًا خطيرًا: الكفر بعد الإيمان ثم ازدياد الكفر. أما البقرة فالكلام عن كتمان البينات، فلم يحتج إلى القيد نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص432–433، تحت آل عمران: 89، في المقارنة بالبقرة: 160.","url":""}]},{"id":"s2-673","number":673,"surah":2,"verses":[160],"verseLabel":"البقرة: 160","question":"ما سرّ الجمع بين التوبة والإصلاح والبيان في قوله تعالى: ﴿تَابُوا وَأَصْلَحُوا وَبَيَّنُوا﴾؟","answer":"التوبة رجوع في الباطن، والإصلاح يزيل آثار الفساد، والبيان يظهر الحق الذي كُتم؛ فلا تكفي توبة سرية ممن أضل غيره بكتم العلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص580–582، تحت البقرة: 160، في ترتيب التوبة والإصلاح والبيان.","url":""}]},{"id":"s2-674","number":674,"surah":2,"verses":[160],"verseLabel":"البقرة: 160","question":"ما سرّ التعبير في قوله تعالى: ﴿فَأُولَئِكَ أَتُوبُ عَلَيْهِمْ﴾ مع أن التائب هو العبد؟","answer":"توبة العبد رجوعه إلى الله، وتوبة الله عليه رجوعه بالقبول والمغفرة والرضا؛ فالفعلان متقابلان لا متماثلان. والفاء تربط القبول بتحقق شروط الإصلاح والبيان، فلا تبقى التوبة دعوى بلا أثر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص581–584، تحت البقرة: 160، في معنى توبة الله واقتران الخبر بالفاء.","url":""}]},{"id":"s2-675","number":675,"surah":2,"verses":[160],"verseLabel":"البقرة: 160","question":"ما سرّ الالتفات إلى ضمير المتكلم في قوله تعالى: ﴿وَأَنَا التَّوَّابُ الرَّحِيمُ﴾؟","answer":"الالتفات إلى ﴿أنا﴾ يقرب وعد القبول بعد وعيد اللعن، ويؤكد أن الله نفسه يتولى التوبة على من رجع. و﴿التواب﴾ صيغة مبالغة تدل على كثرة قبول التائبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص582–584، تحت البقرة: 160، في الالتفات واختيار الاسمين.","url":""}]},{"id":"s2-676","number":676,"surah":2,"verses":[161],"verseLabel":"البقرة: 161","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّ الَّذِينَ كَفَرُوا وَمَاتُوا وَهُمْ كُفَّارٌ﴾؛ أليس موتهم بعد الكفر مفهومًا؟","answer":"قد يكفر الإنسان ثم يتوب قبل الموت، فلا يستحق الحكم المذكور؛ لذلك قيد العاقبة بالموت على الكفر. والجملة الحالية ﴿وهم كفار﴾ تثبت أن الصفة لازمتهم حتى أُغلق باب العمل، لا أنها مرحلة عابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص585–588، تحت البقرة: 161، في قيد الموت والجملة الحالية.","url":""}]},{"id":"s2-677","number":677,"surah":2,"verses":[161],"verseLabel":"البقرة: 161","question":"ما سرّ التعبير في قوله تعالى: ﴿عَلَيْهِمْ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ﴾ بهذا الترتيب؟","answer":"بدأت اللعنة من صاحب الحكم والرحمة، ثم من الملائكة أهل الطاعة، ثم من البشر الذين أفسد الكفر عالمهم؛ فتدرج من الأعلى إلى الخلق. و﴿أجمعين﴾ تستغرق الناس، حتى إن الكافر يلعن يوم القيامة طريق الكفر وأهله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص587–589، تحت البقرة: 161، في ترتيب مصادر اللعنة وعموم الناس.","url":""}]},{"id":"s2-678","number":678,"surah":2,"verses":[162],"verseLabel":"البقرة: 162","question":"ما سرّ التعبير في قوله تعالى: ﴿خَالِدِينَ فِيهَا﴾، وإلى ماذا يعود الضمير مع أن المذكور «اللعنة»؟","answer":"يجوز عود الضمير إلى اللعنة؛ أي خالدين في أثرها وعذابها، ويجوز عوده إلى النار المفهومة من السياق. وفي الأول تصوير اللعنة كأنها محيط يلازمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص590–592، تحت البقرة: 162، في الحال ومرجع الضمير.","url":""}]},{"id":"s2-679","number":679,"surah":2,"verses":[162],"verseLabel":"البقرة: 162","question":"ما سرّ الجمع بين قوله تعالى: ﴿لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنْظَرُونَ﴾؟","answer":"نفت الآية أمرين يتمناهما المعذب: تخفيف شدة العذاب، أو تأخيره وإمهاله. فتقرر دوام العذاب من غير تخفيف ولا مهلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص592–594، تحت البقرة: 162، في الجمع بين نفي التخفيف والإنظار.","url":""}]},{"id":"s2-680","number":680,"surah":2,"verses":[163],"verseLabel":"البقرة: 163","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِلَهُكُمْ إِلَهٌ وَاحِدٌ﴾ فكرر لفظ ﴿إله﴾؟","answer":"أعيد لفظ ﴿إله﴾ ليوصف بـ﴿واحد﴾؛ فالأول مضاف إلى المخاطبين، والثاني خبر يمهد لإثبات الوحدة، فيرسخ أن معبودهم الحق واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص595–598، تحت البقرة: 163، في توسط لفظ الإله بين المبتدأ والخبر.","url":""}]},{"id":"s2-681","number":681,"surah":2,"verses":[163],"verseLabel":"البقرة: 163","question":"ما فائدة قوله تعالى: ﴿لَا إِلَهَ إِلَّا هُوَ﴾ بعد قوله: ﴿إِلَهٌ وَاحِدٌ﴾؟","answer":"الجملة الأولى تثبت أن إلههم واحد، ثم جاء النفي والاستثناء لقصر الألوهية عليه ونفيها عن كل ما سواه؛ فاجتمع الإثبات الصريح والنفي العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص597–599، تحت البقرة: 163، في توكيد التوحيد بالنفي والاستثناء.","url":""}]},{"id":"s2-682","number":682,"surah":2,"verses":[163],"verseLabel":"البقرة: 163","question":"ما مناسبة ختم آية التوحيد باسمَي ﴿الرَّحْمَنُ الرَّحِيمُ﴾؟","answer":"ختم باسمي الرحمة لبيان أن الإله الواحد المتفرد بالعبادة واسع الرحمة بخلقه، ولترغيبهم في توحيده بعد ذكر الوعيد واللعن.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص598–599، تحت البقرة: 163، في مناسبة اسمي الرحمن الرحيم وترتيبهما.","url":""}]},{"id":"s2-683","number":683,"surah":2,"verses":[164],"verseLabel":"البقرة: 164","question":"ما سرّ جمع هذه الآيات الكونية المتنوعة في آية واحدة؟","answer":"جمعت الآية دلائل من الخلق والحركة والرزق والحياة؛ لتبين أن انتظام هذه الظواهر المختلفة وتعاونها تحت تدبير واحد دليل على وحدانية المدبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص615–654، تحت البقرة: 164.","url":""}]},{"id":"s2-684","number":684,"surah":2,"verses":[63],"verseLabel":"البقرة: 164، العنكبوت: 63","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿فَأَحْيَا بِهِ الْأَرْضَ بَعْدَ مَوْتِهَا﴾، وقوله تعالى في العنكبوت: ﴿فَأَحْيَا بِهِ الْأَرْضَ مِنْ بَعْدِ مَوْتِهَا﴾ بزيادة ﴿مِنْ﴾؟","answer":"زيدت ﴿من﴾ في العنكبوت لتأكيد ابتداء الإحياء بعد تحقق الموت في مقام إلزام المشركين بما أقروا به من إنزال الله الماء. أما البقرة فتسوق دلائل كثيرة متتابعة، فاستغنت عن هذا التوكيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص646، تحت العنكبوت: 63، في المقارنة بالبقرة: 164 والنحل: 65 والجاثية: 5 والروم: 24.","url":""}]},{"id":"s2-685","number":685,"surah":2,"verses":[164],"verseLabel":"البقرة: 164","question":"ما سرّ تقديم خلق السماوات والأرض على بقية الآيات؟","answer":"لأنهما الإطار الأعظم الذي تقع فيه جميع الظواهر اللاحقة؛ الليل والنهار والفلك والمطر والدواب والرياح والسحاب كلها أحوال داخلة بينهما. فبدأ بالأصل المحيط ثم فصل آياته المتحركة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص601–605، تحت البقرة: 164، في ترتيب دلائل القدرة.","url":""}]},{"id":"s2-686","number":686,"surah":2,"verses":[164],"verseLabel":"البقرة: 164","question":"ما سرّ التعبير في قوله تعالى: ﴿وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ﴾، دون أن يقال: «وتعاقبهما»؟","answer":"الاختلاف يجمع التعاقب وتفاوت الطول والقصر والحر والبرد والضياء والظلمة، واختلاف ما يصلح فيهما من أعمال؛ فهو أوسع من مجرد مجيء أحدهما بعد الآخر. وكل هذا التنوع يجري بنظام لا يضطرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص603–606، تحت البقرة: 164، في اتساع معنى اختلاف الليل والنهار.","url":""}]},{"id":"s2-687","number":687,"surah":2,"verses":[164],"verseLabel":"البقرة: 164","question":"ما دلالة تقييد الفلك بقوله تعالى: ﴿بِمَا يَنْفَعُ النَّاسَ﴾؟","answer":"ليست العبرة بجريان سفينة خالية فقط، بل بتسخير البحر لحمل الأقوات والتجارة والمسافرين وما تقوم به الحضارة. فالقيد ينقل الدليل من مشهد قدرة مجرد إلى نعمة تمس حياة الإنسان وتستوجب الشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص605–607، تحت البقرة: 164، في قيد نفع الناس.","url":""}]},{"id":"s2-688","number":688,"surah":2,"verses":[164],"verseLabel":"البقرة: 164","question":"ما سرّ التعبير في قوله تعالى: ﴿فَأَحْيَا بِهِ الْأَرْضَ بَعْدَ مَوْتِهَا﴾، مع أن الأرض لا تموت كالحيوان؟","answer":"شبّه جفافها وخلوها من النبات بالموت، واخضرارها وإنباتها بالحياة؛ فتحول المطر أمام العين إلى نموذج مصغر للبعث. والصورة تجعل العقيدة الأخروية مشاهدة كل موسم لا خبرًا بعيدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص606–609، تحت البقرة: 164، في استعارة الموت والحياة للأرض.","url":""}]},{"id":"s2-689","number":689,"surah":2,"verses":[164],"verseLabel":"البقرة: 164","question":"ما سرّ التعبير في قوله تعالى: ﴿وَبَثَّ فِيهَا مِنْ كُلِّ دَابَّةٍ﴾، دون أن يقال: «وخلق الدواب»؟","answer":"البث يصور نشر الأحياء وتفريقها في أنحاء الأرض بأجناس وأشكال وبيئات لا تحصى، لا مجرد إيجادها. و﴿من كل﴾ تلفت إلى التنوع الذي يملأ الكوكب مع وحدة القوانين التي تحفظه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص608–610، تحت البقرة: 164، في اختيار فعل البث وعموم الدواب.","url":""}]},{"id":"s2-690","number":690,"surah":2,"verses":[164],"verseLabel":"البقرة: 164","question":"ما سرّ التعبير في قوله تعالى: ﴿وَتَصْرِيفِ الرِّيَاحِ﴾، دون أن يقال: «وهبوب الرياح»؟","answer":"التصريف يشمل تغيير اتجاهها وقوتها وحرارتها ومنافعها، وسوقها مرة بالبشرى ومرة بالتلقيح أو تحريك السحاب؛ فهي لا تهب على نمط واحد. هذا التدبير المتنوع هو موضع الدلالة، لا وجود الهواء المتحرك فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص609–612، تحت البقرة: 164، في معنى تصريف الرياح.","url":""}]},{"id":"s2-691","number":691,"surah":2,"verses":[164],"verseLabel":"البقرة: 164","question":"ما دلالة وصف السحاب بأنه ﴿الْمُسَخَّرِ بَيْنَ السَّمَاءِ وَالْأَرْضِ﴾؟","answer":"يبدو السحاب كتلة ثقيلة معلقة، ومع ذلك يساق ويحمل الماء ويقف حيث يشاء الله ثم يفرغه؛ فلفظ التسخير يكشف القوة المدبرة وراء المشهد المألوف. وتحديد مكانه بين السماء والأرض يزيد الدهشة من بقائه ومسيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص611–613، تحت البقرة: 164، في وصف السحاب بالتسخير.","url":""}]},{"id":"s2-692","number":692,"surah":2,"verses":[164],"verseLabel":"البقرة: 164","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿لَآيَاتٍ لِقَوْمٍ يَعْقِلُونَ﴾ مع أن هذه الظواهر يراها الجميع؟","answer":"هذه المشاهد يراها الجميع، لكن المنتفع بها هو من يعقل فيربط آثارها بأسبابها وينتقل من النظام المشهود إلى وحدانية المدبر؛ لذلك خص الآيات بقوم يعقلون.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص612–614، تحت البقرة: 164، في الجمع في ﴿آيات﴾ وتخصيص المنتفعين بالعقل.","url":""}]},{"id":"s2-693","number":693,"surah":2,"verses":[165],"verseLabel":"البقرة: 165","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمِنَ النَّاسِ مَنْ يَتَّخِذُ مِنْ دُونِ اللَّهِ أَنْدَادًا﴾ بعد كل آيات التوحيد السابقة؟","answer":"بعد عرض دلائل الوحدانية جاء اتخاذ الأنداد مفارقة ظاهرة: يشاهدون آثار التدبير الواحد ثم يجعل بعضهم لله نظراء. و﴿من الناس﴾ للتبعيض فلا يعمم الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص615–619، تحت البقرة: 165، في اتصال الشرك بدلائل الوحدة والتعبير بـ﴿من الناس﴾.","url":""}]},{"id":"s2-694","number":694,"surah":2,"verses":[165],"verseLabel":"البقرة: 165","question":"لماذا سمّى المعبودات ﴿أَنْدَادًا﴾؟","answer":"الند هو النظير المقابل الذي يُجعل في رتبة صاحبه؛ فالكلمة تفضح حقيقة الشرك: لم يكتفوا بحب أشياء، بل أعطوها نصيبًا من حق الله في التعظيم والطاعة. وهي تسمية لفعلهم لا إقرار بوجود مماثل حقيقي لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص616–620، تحت البقرة: 165، في معنى الأنداد.","url":""}]},{"id":"s2-695","number":695,"surah":2,"verses":[165],"verseLabel":"البقرة: 165","question":"ما سرّ التعبير في قوله تعالى: ﴿يُحِبُّونَهُمْ كَحُبِّ اللَّهِ﴾، دون أن يقال: «يعبدونهم مع الله»؟","answer":"لأن الحب هو المحرك الباطن للعبادة والطاعة؛ فكشف القرآن أصل الانحراف في القلب قبل مظاهره. وقد يقسم المشرك حبه وولاءه بين الله وندّه، فيظهر الخلل حتى لو ادعى أن عبادته مجرد وساطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص619–622، تحت البقرة: 165، في جمع فعل الحب وعلاقته باتخاذ الأنداد.","url":""}]},{"id":"s2-696","number":696,"surah":2,"verses":[165],"verseLabel":"البقرة: 165","question":"ما سرّ التعبير في قوله تعالى: ﴿وَالَّذِينَ آمَنُوا أَشَدُّ حُبًّا لِلَّهِ﴾، دون أن يقال: «يحبون الله أكثر»؟","answer":"المؤمنون أشد حبًا لله لإخلاص حبهم له وثباته، أما المشركون فيوزعون حبهم بين الله وأندادهم؛ فحب المؤمن أوحد وأرسخ.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص622–624، تحت البقرة: 165، في إيثار ﴿أشد حبًا﴾.","url":""}]},{"id":"s2-697","number":697,"surah":2,"verses":[165],"verseLabel":"البقرة: 165","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَوْ يَرَى الَّذِينَ ظَلَمُوا إِذْ يَرَوْنَ الْعَذَابَ﴾ وأظهر ﴿الذين ظلموا﴾ بدل «ولو يروا»؟","answer":"الإظهار يثبت علة ما يرونه: ظلمهم هو الذي ساقهم إلى المشهد، ويعيد وصفهم عند جواب التمني حتى لا يضيع سبب العقوبة في الضمائر. كما يجعل السامع يقف على الاسم المذموم قبل هول العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص624–626، تحت البقرة: 165، في إظهار الاسم موضع الإضمار.","url":""}]},{"id":"s2-698","number":698,"surah":2,"verses":[165],"verseLabel":"البقرة: 165","question":"ما سرّ الجمع بين قوله تعالى: ﴿أَنَّ الْقُوَّةَ لِلَّهِ جَمِيعًا وَأَنَّ اللَّهَ شَدِيدُ الْعَذَابِ﴾؟","answer":"الجملة الأولى تنفي القوة عن الأنداد وتثبتها كلها لله، والثانية تبين أثر هذه القوة في عقاب المشركين؛ فجمع بين زوال النصير وشدة العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص626–628، تحت البقرة: 165، في وصل الجملتين وتهويل الخطاب.","url":""}]},{"id":"s2-699","number":699,"surah":2,"verses":[166],"verseLabel":"البقرة: 166","question":"ما سرّ التعبير في قوله تعالى: ﴿إِذْ تَبَرَّأَ الَّذِينَ اتُّبِعُوا مِنَ الَّذِينَ اتَّبَعُوا﴾، ولم يسمِّ الرؤساء والأتباع؟","answer":"الموصولان يعمان كل علاقة باطلة: أصنامًا وشياطين ورؤساء ضلال، وكل من سلّم عقله لهم. وبناء الأول للمجهول يركز على كونهم متبوعين اتخذهم الناس قادة، لا على أسمائهم التي تختلف عبر العصور.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص629–632، تحت البقرة: 166، في التعبير بالموصول والبناء للمجهول.","url":""}]},{"id":"s2-700","number":700,"surah":2,"verses":[166],"verseLabel":"البقرة: 166","question":"ما سرّ التعبير في قوله تعالى: ﴿وَتَقَطَّعَتْ بِهِمُ الْأَسْبَابُ﴾، وما الأسباب التي تتقطع؟","answer":"الأسباب كل الروابط التي ظنوها منجية: نسب وولاء ووعود ووسائط وحجج؛ صوّرها القرآن حبالًا تصل بعضهم ببعض ثم تتقطع عند الحاجة. فالمشهد يجعل خيانة الباطل محسوسة: لا يبقى إلا العمل الفردي.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص631–635، تحت البقرة: 166، في الصورة البيانية في تقطع الأسباب.","url":""}]},{"id":"s2-701","number":701,"surah":2,"verses":[167],"verseLabel":"البقرة: 167","question":"ما دلالة تمني الأتباع: ﴿لَوْ أَنَّ لَنَا كَرَّةً فَنَتَبَرَّأَ مِنْهُمْ كَمَا تَبَرَّءُوا مِنَّا﴾؟","answer":"تمنوا الرجوع ليقابلوا تبرؤ المتبوعين بتبرؤ مماثل؛ فيكشف التمني انقلاب الولاء الباطل إلى عداوة وحسرة حين تظهر الحقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص636–639، تحت البقرة: 167، في تمني الكرة والمقابلة في البراءة.","url":""}]},{"id":"s2-702","number":702,"surah":2,"verses":[167],"verseLabel":"البقرة: 167","question":"ما سرّ التعبير في قوله تعالى: ﴿كَذَلِكَ يُرِيهِمُ اللَّهُ أَعْمَالَهُمْ حَسَرَاتٍ عَلَيْهِمْ﴾؛ كيف تصير الأعمال حسرات؟","answer":"تظهر لهم أعمالهم في نتائجها وآثارها، فتصير أسباب ندم متكرر عليهم. وجمع ﴿حسرات﴾ لتعدد الأعمال والفرص التي ضيعوها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص639–642، تحت البقرة: 167، في الإشارة وتصوير الأعمال حسرات.","url":""}]},{"id":"s2-703","number":703,"surah":2,"verses":[167],"verseLabel":"البقرة: 167","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وَمَا هُمْ بِخَارِجِينَ مِنَ النَّارِ﴾؟","answer":"بعد تمني الرجوع قطع كل توهم للخلاص؛ فالجملة الاسمية والباء في ﴿بخارجين﴾ تؤكدان ثبات نفي خروجهم من النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص641–642، تحت البقرة: 167، في نفي الخروج بالصيغة الاسمية والباء.","url":""}]},{"id":"s2-704","number":704,"surah":2,"verses":[168],"verseLabel":"البقرة: 168","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تتبعوا خطوات الشيطان﴾ لا: لا تتبعوا الشيطان؟","answer":"صور الإغواء خطوات صغيرة متتابعة؛ فالشيطان لا ينقل غالبًا إلى النهاية دفعة واحدة، بل يستدرج بتنازل يعقبه آخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص654–657، تحت البقرة: 168.","url":""}]},{"id":"s2-705","number":705,"surah":2,"verses":[168],"verseLabel":"البقرة: 168","question":"ما سرّ خطاب الناس جميعًا بقوله تعالى: ﴿يَا أَيُّهَا النَّاسُ كُلُوا مِمَّا فِي الْأَرْضِ﴾، دون تخصيص المؤمنين؟","answer":"أصل الانتفاع بالرزق وإباحة الطيب نعمة عامة، والتحذير من الشيطان يحتاجه البشر كلهم؛ كما أن الآية تدعو المشركين إلى ترك تحريمات اخترعوها. ثم تأتي الخطابات الخاصة بالمؤمنين حين يذكر الشكر والتكليف التفصيلي.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص643–646، تحت البقرة: 168، في عموم النداء ومناسبة الأمر.","url":""}]},{"id":"s2-706","number":706,"surah":2,"verses":[168],"verseLabel":"البقرة: 168","question":"ما سرّ الجمع بين الوصفين: ﴿حَلَالًا طَيِّبًا﴾؟","answer":"الحلال ما أباحه الشرع، والطيب ما سلم من الخبث والضرر واستلذته الفطرة السليمة؛ فالجمع يراعي حكم الطعام وصفته.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص646–648، تحت البقرة: 168، في الجمع بين الحلال والطيب.","url":""}]},{"id":"s2-707","number":707,"surah":2,"verses":[168],"verseLabel":"البقرة: 168","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّهُ لَكُمْ عَدُوٌّ مُبِينٌ﴾ فقدم ﴿لكم﴾؟","answer":"التقديم يقرب الخطر ويخصص عداوته بالمخاطبين: ليس حديثًا عن عدو بعيد، بل عدوكم أنتم. و﴿مبين﴾ تحتمل ظاهر العداوة ومُظهرها بأثره؛ فلا عذر لمن يسلك خطوات خصم أعلن قصده منذ البداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص649–651، تحت البقرة: 168، في التقديم والتعريف بالعداوة.","url":""}]},{"id":"s2-708","number":708,"surah":2,"verses":[169],"verseLabel":"البقرة: 169","question":"ما سرّ ترتيب أوامر الشيطان: ﴿بِالسُّوءِ وَالْفَحْشَاءِ وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لَا تَعْلَمُونَ﴾؟","answer":"رتبها في تصاعد: السوء معصية، والفحشاء ما اشتد قبحه، والقول على الله بلا علم يشرع الباطل ويضل الآخرين؛ فهو أخطرها وأعم فسادًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص652–655، تحت البقرة: 169، في ترتيب السوء والفحشاء والقول على الله.","url":""}]},{"id":"s2-709","number":709,"surah":2,"verses":[169],"verseLabel":"البقرة: 169","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا لَا تَعْلَمُونَ﴾ ولم يذكر ما الذي لا يعلمونه؟","answer":"حذف المفعول ليعم كل قول على الله بلا علم: في ذاته وأحكامه وحلاله وحرامه ووعده ووعيده. فلا ينجو المتكلم بأن موضوعه صغير؛ العبرة بجرأة النسبة إلى الله من غير برهان.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص655–657، تحت البقرة: 169، في حذف مفعول العلم.","url":""}]},{"id":"s2-710","number":710,"surah":2,"verses":[170],"verseLabel":"البقرة: 170","question":"ما دلالة عدم ذكر متعلق الهداية في قوله تعالى: ﴿وَلَا يَهْتَدُونَ﴾؟","answer":"حذف متعلق الهداية ليعم؛ أي لا يهتدون إلى حق ولا طريق رشد في هذا المقام، فلا يقيد ضلالهم بوجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص671، تحت البقرة: 170.","url":""}]},{"id":"s2-711","number":711,"surah":2,"verses":[104],"verseLabel":"البقرة: 170، المائدة: 104","question":"ما سرّ اختلاف التعبير بين قولهم في البقرة: ﴿بَلْ نَتَّبِعُ مَا أَلْفَيْنَا عَلَيْهِ آبَاءَنَا﴾، وقولهم في المائدة: ﴿حَسْبُنَا مَا وَجَدْنَا عَلَيْهِ آبَاءَنَا﴾؟","answer":"في البقرة صرحوا بالاتباع لما ألفوا عليه آباءهم، فدل على تقليد العادة. وفي المائدة قالوا ﴿حسبنا﴾ فادعوا كفاية ما وجدوه ورفضوا الزيادة؛ فكان عنادهم هناك أشد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص762–764، تحت المائدة: 104، في المقارنة بالبقرة: 170.","url":""}]},{"id":"s2-712","number":712,"surah":2,"verses":[170],"verseLabel":"البقرة: 170","question":"ما دلالة قولهم: ﴿مَا أَلْفَيْنَا عَلَيْهِ آبَاءَنَا﴾، دون الاستناد إلى علم أو حجة؟","answer":"لفظ ﴿ألفينا﴾ يدل على أنهم صادفوا آباءهم على حال فألفوها واتبعوها؛ فهو اعتراف بأن مستندهم الموروث لا العلم بصحته.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص658–664، تحت البقرة: 170، في دلالة ﴿ألفينا﴾ وتقليد الآباء.","url":""}]},{"id":"s2-713","number":713,"surah":2,"verses":[104],"verseLabel":"البقرة: 170 والمائدة: 104","question":"ما سرّ اختلاف التعبير بين ﴿مَا أَلْفَيْنَا عَلَيْهِ آبَاءَنَا﴾ في البقرة و﴿مَا وَجَدْنَا عَلَيْهِ آبَاءَنَا﴾ في المائدة؟","answer":"﴿ألفينا﴾ تلائم التصريح باتباع ما صادفوا عليه آباءهم، و﴿وجدنا﴾ جاءت مع ادعاء الاكتفاء به: ﴿حسبنا﴾. فاختلاف اللفظ تابع لاختلاف بناء حجتهم في الموضعين.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص664–670، تحت البقرة: 170، في توجيه المتشابه بين ألفينا ووجدنا.","url":""}]},{"id":"s2-714","number":714,"surah":2,"verses":[170],"verseLabel":"البقرة: 170","question":"ما سرّ التعبير في قوله تعالى: ﴿أَوَلَوْ كَانَ آبَاؤُهُمْ لَا يَعْقِلُونَ شَيْئًا وَلَا يَهْتَدُونَ﴾؟","answer":"لا يذم اتباع الآباء لمجرد أنهم آباء، بل إذا فقدوا المصدرين اللذين يصححان الطريق: العقل الذي ينظر، والهداية التي تأتي من الوحي. فالسؤال يختبر التقليد: أيبقى واجبًا حتى لو اجتمع الجهل والضلال؟","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص667–670، تحت البقرة: 170، في الاستفهام الشرطي والجمع بين نفي العقل والهداية.","url":""}]},{"id":"s2-715","number":715,"surah":2,"verses":[170],"verseLabel":"البقرة: 170","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا يَعْقِلُونَ شَيْئًا﴾، ولم يكتفِ بـ«لا يعقلون»؟","answer":"﴿شيئًا﴾ في سياق النفي تستغرق أدنى قدر معتبر في موضع الاتباع؛ أي ليس عندهم من الحجة ما يسوغ جعلهم معيارًا للدين. والمقصود نفي العقل النافع في هذا الباب، لا نفي القدرة الذهنية عنهم مطلقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص668–670، تحت البقرة: 170، في تنكير ﴿شيئًا﴾ بعد النفي.","url":""}]},{"id":"s2-716","number":716,"surah":2,"verses":[104],"verseLabel":"البقرة: 170 والمائدة: 104","question":"ما سرّ اختلاف التعبير بين ﴿لَا يَعْقِلُونَ شَيْئًا﴾ في البقرة و﴿لَا يَعْلَمُونَ شَيْئًا﴾ في المائدة؟","answer":"في البقرة ادعوا مجرد اتباع المألوف، فنفى عن آبائهم التعقل الذي يميز الحجة. وفي المائدة ادعوا أن ما وجدوه يكفيهم، فنفى عنهم العلم نفسه، وهو أبلغ في الرد على دعوى الاكتفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص669–671، تحت البقرة: 170، في توجيه المتشابه بين ﴿يعقلون﴾ و﴿يعلمون﴾.","url":""}]},{"id":"s2-717","number":717,"surah":2,"verses":[171],"verseLabel":"البقرة: 171","question":"ما وجه التمثيل في قوله تعالى: ﴿وَمَثَلُ الَّذِينَ كَفَرُوا كَمَثَلِ الَّذِي يَنْعِقُ بِمَا لَا يَسْمَعُ﴾؟","answer":"التشبيه تمثيل مركب: الداعي إلى الحق كالراعي ينعق، والكافر كالمنعوق به لا يدرك من الكلام إلا الصوت. وحذف بعض أطراف الصورة لدلالة المشهد عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص672–685، تحت البقرة: 171، في تركيب التمثيل وحذف المنعوق به.","url":""}]},{"id":"s2-718","number":718,"surah":2,"verses":[171],"verseLabel":"البقرة: 171","question":"ما سرّ التعبير في قوله تعالى: ﴿بِمَا لَا يَسْمَعُ إِلَّا دُعَاءً وَنِدَاءً﴾، دون أن يقال: «بمن لا يفهم»؟","answer":"لأن الصورة لا تنفي وصول الصوت إلى الأذن، بل تنفي تجاوزه إلى الفهم والاستجابة؛ فهم يسمعون ألفاظ الوحي كما تسمع البهيمة صوت الراعي، ولا يعون مقصوده. وهذا أشد في الذم من مجرد فقد السماع.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص679–686، تحت البقرة: 171، في تمثيل سماع الصوت دون المعنى.","url":""}]},{"id":"s2-719","number":719,"surah":2,"verses":[171],"verseLabel":"البقرة: 171","question":"ما سرّ الجمع بين ﴿دُعَاءً﴾ و﴿نِدَاءً﴾ مع تقارب معناهما؟","answer":"الدعاء يتضمن طلب الإقبال أو الفعل، والنداء رفع الصوت للتنبيه؛ فجمعهما لبيان أنهم لا ينتفعون لا بمضمون الخطاب ولا بالتنبيه إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص681–689، تحت البقرة: 171، في الفرق بين الدعاء والنداء وسر الجمع بينهما.","url":""}]},{"id":"s2-720","number":720,"surah":2,"verses":[171],"verseLabel":"البقرة: 171","question":"ما وجه وصفهم بقوله تعالى: ﴿صُمٌّ بُكْمٌ عُمْيٌ﴾ مع سلامة حواسهم الظاهرة؟","answer":"هذه أوصاف مجازية لتعطيل وظائف الحواس في تلقي الحق؛ فهم يسمعون الأصوات ولا يقبلون الهدى، ولا ينطقون به، ولا يعتبرون بما يرون، فكأن حواسهم مفقودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص683–688، تحت البقرة: 171، في المجاز في الصمم والبكم والعمى.","url":""}]},{"id":"s2-721","number":721,"surah":2,"verses":[171],"verseLabel":"البقرة: 171","question":"ما سرّ ترتيب الصفات: ﴿صُمٌّ بُكْمٌ عُمْيٌ﴾؟","answer":"بدأ بالصمم لأن السمع طريق تلقي الدعوة المذكورة في المثل، ثم البكم لأنه يمنع الجواب والإقرار، ثم العمى لأنه يمنع الاعتبار بالمشاهدات؛ فرتبت منافذ التلقي والاستجابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص684–688، تحت البقرة: 171، في ترتيب الحواس في التذييل.","url":""}]},{"id":"s2-722","number":722,"surah":2,"verses":[171],"verseLabel":"البقرة: 171","question":"ما مناسبة ختم المثل بقوله تعالى: ﴿فَهُمْ لَا يَعْقِلُونَ﴾؟","answer":"الفاء ترتب عدم التعقل النافع على تعطيل السمع والنطق والبصر عن الحق. والمضارع يدل على استمرار تركهم استعمال العقل، لا على انعدام أصل القوة العقلية.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص688–690، تحت البقرة: 171، في نفي العقل ودلالة الفاء.","url":""}]},{"id":"s2-723","number":723,"surah":2,"verses":[168],"verseLabel":"البقرة: 172 والبقرة: 168","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا كُلُوا﴾، وقال قبلها: ﴿يَا أَيُّهَا النَّاسُ كُلُوا﴾؟","answer":"كان خطاب الآية 168 للناس جميعًا لإبطال التحريمات المبتدعة، أما هنا فخص المؤمنين لأن المقام مقام شكر المنعم وإخلاص العبادة له بعد الانتفاع بالطيبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص690–697، تحت البقرة: 172، في الفرق بين الخطابين.","url":""}]},{"id":"s2-724","number":724,"surah":2,"verses":[172],"verseLabel":"البقرة: 172","question":"ما سرّ تكرار الأمر بالأكل في الآية 172 بعد وروده في الآية 168؟","answer":"الأمر الأول إباحة عامة للناس ورد على تحريم المشركين، والثاني خطاب للمؤمنين يربط أكل الطيبات بالشكر والعبادة؛ فاختلف المخاطب والغرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص692–697، تحت البقرة: 172، في تكرار الأمر وتخصيص المؤمنين.","url":""}]},{"id":"s2-725","number":725,"surah":2,"verses":[172],"verseLabel":"البقرة: 172","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ طَيِّبَاتِ مَا رَزَقْنَاكُمْ﴾، دون أن يقال: «كلوا رزقنا»؟","answer":"﴿من﴾ توجه إلى الطيب من الرزق، ولفظ ﴿رزقناكم﴾ يرد الطعام إلى عطية الله لا إلى مجرد كسب الإنسان. فيجتمع في العبارة اختيار النافع الطاهر واستحضار المنعم الذي يسّر أسبابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص691–695، تحت البقرة: 172، في دلالة الطيبات وإسناد الرزق.","url":""}]},{"id":"s2-726","number":726,"surah":2,"verses":[172],"verseLabel":"البقرة: 172","question":"ما مناسبة إتباع الأمر بالأكل بقوله تعالى: ﴿وَاشْكُرُوا لِلَّهِ﴾؟","answer":"عقب الأكل بالشكر حتى لا تقف النعمة عند لذة البدن، بل تقود إلى الاعتراف بالمنعم واستعمال رزقه في طاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص697–699، تحت البقرة: 172، في إرداف الأمر بالأكل بالشكر.","url":""}]},{"id":"s2-727","number":727,"surah":2,"verses":[172],"verseLabel":"البقرة: 172","question":"ما سرّ التعبير في قوله تعالى: ﴿وَاشْكُرُوا لِلَّهِ﴾، دون أن يقال: «واشكروني»؟","answer":"تعدية الشكر باللام تبرز الإحسان الذي صدر من الله وتكلّف العباد بما يطيقون من الاعتراف بأفعاله وآلائه، بدل الإحاطة بحقيقة ذاته ونعمه التي لا تحصى. وفيها لطف وتخفيف مع تعظيم الاستحقاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص698–699، تحت البقرة: 172، في تعدية الشكر باللام.","url":""}]},{"id":"s2-728","number":728,"surah":2,"verses":[172],"verseLabel":"البقرة: 172","question":"ما سرّ تعليق الشكر بقوله تعالى: ﴿إِنْ كُنْتُمْ إِيَّاهُ تَعْبُدُونَ﴾ مع وجوبه؟","answer":"الشرط للحث وإظهار التلازم، لا للشك: إن كنتم تخصونه بالعبادة حقًا فخصوه بالشكر؛ فالشكر شاهد صدق العبودية.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص699–700، تحت البقرة: 172، في دلالة الشرط.","url":""}]},{"id":"s2-729","number":729,"surah":2,"verses":[172],"verseLabel":"البقرة: 172","question":"ما دلالة تقديم ﴿إِيَّاهُ﴾ على ﴿تَعْبُدُونَ﴾؟","answer":"تقديم المفعول يفيد القصر؛ أي إن كنتم تعبدونه وحده دون سواه، وهو المناسب لمقام التوحيد والشكر للمنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص699–700، تحت البقرة: 172، في تقديم المفعول.","url":""}]},{"id":"s2-730","number":730,"surah":2,"verses":[173],"verseLabel":"البقرة: 173","question":"ما سرّ التعبير في قوله تعالى: ﴿إنما حرم عليكم﴾ بأداة الحصر؟","answer":"جاء بعد إباحة الطيبات ليحصر المحرمات المذكورة ويمنع تحريم الناس ما أحل الله، فالأصل سعة الحلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص706، تحت البقرة: 173.","url":""}]},{"id":"s2-731","number":731,"surah":2,"verses":[173],"verseLabel":"البقرة: 173","question":"ما سرّ التعبير في قوله تعالى: ﴿لحم الخنزير﴾، دون أن يقال: الخنزير؟","answer":"لأن المقام في المأكولات فخص اللحم، وهو المقصود الأعظم من الحيوان، مع دلالة النصوص على تحريم سائر أجزائه المأكولة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص706–708، تحت البقرة: 173.","url":""}]},{"id":"s2-732","number":732,"surah":2,"verses":[173],"verseLabel":"البقرة: 173","question":"ما سرّ زيادة ﴿فَلَا إِثْمَ عَلَيْهِ﴾ بعد الاضطرار في البقرة، وعدم ذكرها في آية المائدة؟","answer":"صرحت البقرة برفع الحرج لتقرير أصل رخصة الضرورة، وفي المائدة دل ختام ﴿فإن الله غفور رحيم﴾ على سقوط الإثم ضمنًا مع سياق تفصيل أوسع.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص536، تحت المائدة: 3، في المقارنة بالبقرة: 173.","url":""}]},{"id":"s2-733","number":733,"surah":2,"verses":[3],"verseLabel":"البقرة: 173، المائدة: 3","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿إِنَّمَا حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ﴾ بأداة الحصر، وقوله تعالى في المائدة: ﴿حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ﴾ بلا ﴿إنما﴾؟","answer":"سبقت البقرة إباحة عامة للطيبات، فجاءت ﴿إنما﴾ لحصر المستثنيات المحرمة ومنع تحريم ما أحل الله. أما المائدة فمقام استكمال الأحكام وتفصيل المحرمات، فجاء التقرير من غير إعادة الحصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص535، تحت المائدة: 3، في المقارنة بالبقرة: 173.","url":""}]},{"id":"s2-734","number":734,"surah":2,"verses":[3],"verseLabel":"البقرة: 173، المائدة: 3","question":"ما سرّ التصريح بفاعل التحريم في البقرة: ﴿حَرَّمَ عَلَيْكُمُ﴾، وبناء الفعل للمجهول في المائدة: ﴿حُرِّمَتْ عَلَيْكُمُ﴾؟","answer":"صرحت البقرة بالفاعل لتقرر أن التحريم لله وحده في مواجهة من يشرّع من عنده. أما خطاب المؤمنين في المائدة فمعلوم فيه المحرِّم، فبني الفعل للمجهول وتوجه الاهتمام إلى المحرمات.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص535، تحت المائدة: 3، في المقارنة بالبقرة: 173.","url":""}]},{"id":"s2-735","number":735,"surah":2,"verses":[3],"verseLabel":"البقرة: 173، المائدة: 3","question":"ما سرّ التعبير في قوله تعالى في البقرة: ﴿وَمَا أُهِلَّ بِهِ لِغَيْرِ اللَّهِ﴾، وفي المائدة: ﴿وَمَا أُهِلَّ لِغَيْرِ اللَّهِ بِهِ﴾ بتغيير ترتيب الجارّين؟","answer":"سياق البقرة بدأ بالرزق والطعام، فقدم ﴿به﴾ العائد على المذبوح لأنه موضع الحديث. أما المائدة فسياقها يبرز جهة التحليل والتحريم وإبطال ما يُصرف لغير الله، فقدم ﴿لغير الله﴾ ليجعل بطلان الجهة المشركة في واجهة العبارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص535–536، تحت المائدة: 3، في المقارنة بالبقرة: 173.","url":""}]},{"id":"s2-736","number":736,"surah":2,"verses":[3],"verseLabel":"البقرة: 173، المائدة: 3","question":"ما سرّ اقتصار آية البقرة على أربعة محرمات، وزيادة صور أخرى في آية المائدة؟","answer":"ذكرت البقرة أصول المحرمات، ثم جاءت المائدة ـ وهي من أواخر ما نزل ـ في مقام استكمال التشريع وتفصيل الصور الداخلة في تلك الأصول.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص535–536، تحت المائدة: 3، في المقارنة بالبقرة: 173.","url":""}]},{"id":"s2-737","number":737,"surah":2,"verses":[115],"verseLabel":"البقرة: 173، الأنعام: 145، النحل: 115","question":"ما سرّ اختلاف الخاتمة بين ﴿فَإِنَّ اللَّهَ غَفُورٌ رَحِيمٌ﴾ في البقرة والنحل، و﴿فَإِنَّ رَبَّكَ غَفُورٌ رَحِيمٌ﴾ في الأنعام؟","answer":"ناسب اسم الجلالة في البقرة والنحل سياق النعمة والعبادة والتشريع: فالمنعم المعبود هو الغفور الرحيم. وفي الأنعام تكرر وصف الرب مع آثار التربية والإنشاء، فناسب قوله ﴿ربك﴾ رخصة الضرورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص714–716، تحت البقرة: 173، في المقارنة بالأنعام: 145 والنحل: 115.","url":""}]},{"id":"s2-738","number":738,"surah":2,"verses":[173],"verseLabel":"البقرة: 173","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّمَا حَرَّمَ عَلَيْكُمُ﴾ بعد الأمر بالأكل من الطيبات؟","answer":"جاء الحصر ليرفع الحرج ويوضح أن دائرة التحريم محدودة أمام سعة الحلال، ثم يبين الاستثناء عند الضرورة. فالسياق لا يضيق على الناس، بل يقطع التحريمات التي اخترعوها ويحدد المحرم حقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص702–706، تحت البقرة: 173، في مناسبة الآية وأسلوب الحصر.","url":""}]},{"id":"s2-739","number":739,"surah":2,"verses":[173],"verseLabel":"البقرة: 173","question":"ما سرّ التعبير في قوله تعالى: ﴿حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ﴾، والتحريم في الحقيقة متعلق بأكلها لا بذاتها؟","answer":"حذف الأكل لأن المقام قبله في الطعام، فدل السياق عليه بلا لبس؛ وإسناد التحريم إلى العين أبلغ في تنفير المخاطب منها ومن وجوه الانتفاع الداخلة في الحكم. إنه إيجاز يجعل المحرم حاضرًا بقوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص705–707، تحت البقرة: 173، في حذف متعلق التحريم.","url":""}]},{"id":"s2-740","number":740,"surah":2,"verses":[173],"verseLabel":"البقرة: 173","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا أُهِلَّ بِهِ لِغَيْرِ اللَّهِ﴾، دون أن يقال: «وما ذبح للأصنام»؟","answer":"التعبير يعم كل ذبيحة رفع عندها اسم غير الله أو قصد بها التقرب لسواه، سواء كان صنمًا أو شخصًا أو قوة متوهمة. فالعلة ليست شكل المعبود، بل صرف شعار الذبح والعبادة عن الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص708–710، تحت البقرة: 173، في معنى الإهلال والعموم في غير الله.","url":""}]},{"id":"s2-741","number":741,"surah":2,"verses":[173],"verseLabel":"البقرة: 173","question":"ما سرّ التعبير في قوله تعالى في المضطر: ﴿غَيْرَ بَاغٍ وَلَا عَادٍ﴾، فغاير بين ﴿غير﴾ و﴿لا﴾؟","answer":"جاءت ﴿غير﴾ حالًا جامعةً لقيد الاضطرار، ثم عطف عليها ﴿ولا عاد﴾ لنفي الوصف الثاني وتوكيد استقلاله؛ فلا يكون طالبًا للمحرم من غير ضرورة، ولا متجاوزًا قدر ما يدفع الهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص710–713، تحت البقرة: 173، في مجيء ﴿غير﴾ والجمع بين الباغي والعادي.","url":""}]},{"id":"s2-742","number":742,"surah":2,"verses":[173],"verseLabel":"البقرة: 173","question":"ما سرّ التعبير في قوله تعالى: ﴿فَلَا إِثْمَ عَلَيْهِ﴾، دون أن يقال: «فهو حلال له»؟","answer":"لأن المقام مقام رفع المؤاخذة عن فعل أصله محرم ولا يباح إلا بقدر الضرورة؛ فنفي الإثم يحفظ هيبة الأصل مع بيان الرخصة. كما يطمئن المضطر إلى أنه لا يعاقب إذا التزم القيدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص712–714، تحت البقرة: 173، في تفريع رفع الإثم على الاضطرار.","url":""}]},{"id":"s2-743","number":743,"surah":2,"verses":[173],"verseLabel":"البقرة: 173","question":"ما مناسبة ختم رخصة المضطر باسمَي ﴿غَفُورٌ رَحِيمٌ﴾؟","answer":"المغفرة تناسب ما قد يقع من تناول المحرم، والرحمة تناسب تشريع الرخصة وحفظ النفس؛ فالله لم يجعل الضرورة باب هلاك أو عنت. وجاء الاسمان ليطمئنا القلب بعد ألفاظ التحريم والإثم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص713–716، تحت البقرة: 173، في مناسبة الخاتمة.","url":""}]},{"id":"s2-744","number":744,"surah":2,"verses":[174],"verseLabel":"البقرة: 174","question":"ما سرّ الوصل بالواو بين كتمان الكتاب وأخذ الثمن، دون الفاء؟","answer":"الواو تجمع الجريمتين مع استقلال كل واحدة؛ فقد يقع الكتمان من غير أخذ ثمن، فلا يصح جعل الأكل نتيجة لازمة لكل كتمان بالفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص721، تحت البقرة: 174.","url":""}]},{"id":"s2-745","number":745,"surah":2,"verses":[77],"verseLabel":"البقرة: 174، آل عمران: 77","question":"ما سرّ زيادة قوله تعالى: ﴿مَا يَأْكُلُونَ فِي بُطُونِهِمْ إِلَّا النَّارَ﴾ في البقرة، وابتداء الوعيد في آل عمران بقوله: ﴿أُولَئِكَ لَا خَلَاقَ لَهُمْ فِي الْآخِرَةِ﴾؟","answer":"فصلت البقرة جرم الكتمان وأخذ الثمن، فناسبه تفصيل الوعيد وتصوير المأكول نارًا. أما آل عمران فبدأت بنفي نصيبهم في الآخرة، مع اشتراك الموضعين في بقية أصول الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص728–730، تحت البقرة: 174، في المقارنة بآل عمران: 77.","url":""}]},{"id":"s2-746","number":746,"surah":2,"verses":[77],"verseLabel":"البقرة: 174، آل عمران: 77","question":"ما سرّ زيادة قوله تعالى: ﴿وَلَا يَنْظُرُ إِلَيْهِمْ﴾ في آل عمران، وعدم ذكره في آية البقرة النظيرة؟","answer":"جريمة آل عمران تضمنت بيع عهد الله والأيمان، فزيد في عقوبتهم حرمان نظر الرضا والرعاية. وناسب ذكر النظر سياق العهد الذي يقتضي عادة نظر التعاهد والتكريم، بينما ناسب نفي الكلام في البقرة كتمانهم كلام الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص315–317، تحت آل عمران: 77، في المقارنة بالبقرة: 174.","url":""}]},{"id":"s2-747","number":747,"surah":2,"verses":[174],"verseLabel":"البقرة: 174","question":"ما سرّ التعبير في قوله تعالى: ﴿يَكْتُمُونَ مَا أَنْزَلَ اللَّهُ مِنَ الْكِتَابِ﴾، ولم يحدد ما كتموه؟","answer":"أبهم المكتوم ليعم كل ما أخفوه من الحق، ومنه صفة النبي والبشارة به والأحكام التي خالفت أهواءهم. فالتعميم يمنع حصر الجريمة في معلومة واحدة ويجعل الوعيد لكل كتمان متعمد للوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص717–720، تحت البقرة: 174، في إبهام المكتوم.","url":""}]},{"id":"s2-748","number":748,"surah":2,"verses":[174],"verseLabel":"البقرة: 174","question":"ما دلالة وصف الثمن بأنه ﴿قَلِيلًا﴾ ولو كان في نظر أصحابه كثيرًا؟","answer":"كل عوض دنيوي قليل إذا قيس بالحق الباقي وثواب الآخرة، مهما كثر في أعين أصحابه؛ فهو ثمن زائل لما لا يقدر بثمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص718–721، تحت البقرة: 174، في وصف الثمن بالقلة.","url":""}]},{"id":"s2-749","number":749,"surah":2,"verses":[174],"verseLabel":"البقرة: 174","question":"ما سرّ التعبير في قوله تعالى: ﴿أُولَئِكَ﴾، دون أن يقال: «هم لا يأكلون»؟","answer":"اسم الإشارة يستحضر صورتهم البشعة بالأوصاف السابقة، ويبين أن كتمانهم وبيعهم الحق هما سبب الحكم الآتي. وفي الإشارة إلى البعيد إبعاد لهم في منزلة الذم والاحتقار.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص721–722، تحت البقرة: 174، في الإخبار باسم الإشارة.","url":""}]},{"id":"s2-750","number":750,"surah":2,"verses":[174],"verseLabel":"البقرة: 174","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا يَأْكُلُونَ فِي بُطُونِهِمْ إِلَّا النَّارَ﴾، مع أنهم يأكلون مالًا؟","answer":"سمّى المال الحرام نارًا باعتبار ما يؤول إليه ويسببه؛ فكأن العاقبة دخلت بطونهم منذ لحظة الكسب. والصورة تمحو لذة الثمن العاجلة وتري القارئ حقيقته الأخروية المحرقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص721–724، تحت البقرة: 174، في المجاز بعلاقة السببية.","url":""}]},{"id":"s2-751","number":751,"surah":2,"verses":[174],"verseLabel":"البقرة: 174","question":"ما فائدة قوله: ﴿فِي بُطُونِهِمْ﴾، والأكل لا يكون عادة إلا فيها؟","answer":"ذكر البطون يجسم قبح الفعل ويصور النار مستقرة في أجوافهم، لا مجرد شيء يمر بأفواههم. كما يزيد التهكم بمن جعلوا غايتهم ملء البطون فصار ما ملؤوها به سبب عذابهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص722–724، تحت البقرة: 174، في ذكر البطون.","url":""}]},{"id":"s2-752","number":752,"surah":2,"verses":[174],"verseLabel":"البقرة: 174","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا يُكَلِّمُهُمُ اللَّهُ يَوْمَ الْقِيَامَةِ﴾، مع أن القرآن يذكر خطاب الله للكافرين؟","answer":"المنفي كلام الرضا والتكريم، لا كل خطاب؛ فقد يخاطبون بالتوبيخ والحساب. وعوقب من كتم كلام الله بحرمان كلام الرحمة والتشريف.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص724–727، تحت البقرة: 174، في نفي كلام الله عنهم.","url":""}]},{"id":"s2-753","number":753,"surah":2,"verses":[174],"verseLabel":"البقرة: 174","question":"ما سرّ تقديم ﴿لَا يُكَلِّمُهُمُ اللَّهُ﴾ على ﴿وَلَا يُزَكِّيهِمْ﴾؟","answer":"التكليم بالتكريم مبدأ القرب، والتزكية تطهير وثناء يترتب عليه؛ فبدأ بحرمانهم الصلة، ثم بحرمانهم التطهير.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص725–729، تحت البقرة: 174، في ترتيب الوعيد.","url":""}]},{"id":"s2-754","number":754,"surah":2,"verses":[174],"verseLabel":"البقرة: 174","question":"ما مناسبة قوله تعالى: ﴿وَلَهُمْ عَذَابٌ أَلِيمٌ﴾ بعد تصوير ما يأكلونه بالنار؟","answer":"لأن النار المذكورة أولًا تصور حقيقة ما اكتسبوه، ثم جاءت الجملة لتصرح بأن لهم فوق الخزي والحرمان عذابًا ثابتًا مؤلمًا. وتقديم ﴿لهم﴾ يشعر باختصاص هذا الجزاء بهم واستقراره.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص727–730، تحت البقرة: 174، في تعدد الأخبار وخاتمة الوعيد.","url":""}]},{"id":"s2-755","number":755,"surah":2,"verses":[175],"verseLabel":"البقرة: 175","question":"ما دلالة تكرار اسم الإشارة في قوله تعالى: ﴿أُولَئِكَ الَّذِينَ اشْتَرَوُا الضَّلَالَةَ بِالْهُدَى﴾ بعد قوله: ﴿أُولَئِكَ مَا يَأْكُلُونَ...﴾؟","answer":"لأن كل حكم من الحكمين عظيم يستحق أن يستقل بإشارة تلفت إليه؛ الأولى تصور العقوبة، والثانية تكشف الصفقة التي أوقعتهم فيها. والتكرار يعيد استحضارهم بوصفهم جديرين بأحكام متتابعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص731–734، تحت البقرة: 175، في تكرار الإشارة.","url":""}]},{"id":"s2-756","number":756,"surah":2,"verses":[175],"verseLabel":"البقرة: 175","question":"ما سرّ المقابلة بين ﴿الضَّلَالَةَ بِالْهُدَى﴾ و﴿الْعَذَابَ بِالْمَغْفِرَةِ﴾؟","answer":"المقابلة تعرض الخسارتين معًا: اختاروا في الدنيا الضلال بدل الهدى، فآل اختيارهم في الآخرة إلى العذاب بدل المغفرة. وهكذا يرى القارئ أن الجزاء ليس منفصلًا عن الصفقة، بل هو تمامها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص733–735، تحت البقرة: 175، في المقابلة بين البدائل.","url":""}]},{"id":"s2-757","number":757,"surah":2,"verses":[175],"verseLabel":"البقرة: 175","question":"ما سرّ تصوير كتمان الحق بالشراء في قوله تعالى: ﴿اشْتَرَوُا الضَّلَالَةَ بِالْهُدَى﴾؟","answer":"لأنهم تركوا ما كان في أيديهم من علم وهداية وأخذوا مكانه الضلال والثمن، فشبه الاختيار المتعمد بمبادلة تجارية. والباء تدخل على المتروك المبذول، فكأن الهدى رأس مال أضاعوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص734–736، تحت البقرة: 175، في استعارة الشراء ودلالة الباء.","url":""}]},{"id":"s2-758","number":758,"surah":2,"verses":[175],"verseLabel":"البقرة: 175","question":"ما معنى التعجب في قوله: ﴿فَمَا أَصْبَرَهُمْ عَلَى النَّارِ﴾؟","answer":"الأسلوب للتعجب والتقريع، لا لمدح صبرهم؛ أي ما أجرأهم على الأعمال المؤدية إلى النار، وما أشد غفلتهم عما ينتظرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص735–737، تحت البقرة: 175، في أسلوب ﴿فما أصبرهم﴾.","url":""}]},{"id":"s2-759","number":759,"surah":2,"verses":[176],"verseLabel":"البقرة: 176","question":"إلى ماذا يشير قوله: ﴿ذَلِكَ بِأَنَّ اللَّهَ نَزَّلَ الْكِتَابَ بِالْحَقِّ﴾؟","answer":"يشير إلى الوعيد والجزاء السابق كله؛ استحقوه لأن الله أنزل كتابًا ملابسًا للحق، فقابلوا البيان بالكتمان والاختلاف. فاسم الإشارة يجمع صور العقاب ثم يكشف علتها الجامعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص738–740، تحت البقرة: 176، في مرجع اسم الإشارة والتعليل بالباء.","url":""}]},{"id":"s2-760","number":760,"surah":2,"verses":[176],"verseLabel":"البقرة: 176","question":"ما سرّ التعبير في قوله تعالى: ﴿نَزَّلَ الْكِتَابَ بِالْحَقِّ﴾، ولم يكتفِ بـ«أنزل الكتاب»؟","answer":"﴿بالحق﴾ تثبت أن الوحي نزل محاطًا بالصدق والعدل ولغاية إقامة الحق؛ ولذلك لا يبقى لمختلف أو كاتم عذر في نسبة الخلل إلى الكتاب. الجريمة جاءت من موقفهم لا من غموض المصدر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص739–742، تحت البقرة: 176، في الباء وملابسة التنزيل للحق.","url":""}]},{"id":"s2-761","number":761,"surah":2,"verses":[176],"verseLabel":"البقرة: 176","question":"ما سرّ التعبير في قوله تعالى: ﴿اخْتَلَفُوا فِي الْكِتَابِ﴾، دون أن يقال: «اختلفوا على الكتاب»؟","answer":"﴿في﴾ تصور اختلافهم متغلغلًا في شأن الكتاب ومعانيه وموقفهم منه: آمنوا ببعض وكتموا بعضًا وحرفوا بعضًا. فهو ليس خلافًا خارجيًا عابرًا، بل شقاق نشأ داخل تعاملهم مع الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص741–744، تحت البقرة: 176، في تعدية الاختلاف بـ﴿في﴾.","url":""}]},{"id":"s2-762","number":762,"surah":2,"verses":[176],"verseLabel":"البقرة: 176","question":"ما دلالة وصف الشقاق بأنه ﴿بَعِيدٍ﴾؟","answer":"صوّر الشقاق كأنه مكان بعيد انغمسوا فيه؛ أي بلغ خلافهم غاية أبعدتهم عن الحق وعن سبيل الاجتماع عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص742–744، تحت البقرة: 176، في الاستعارة والتوكيد في ﴿لفي شقاق بعيد﴾.","url":""}]},{"id":"s2-763","number":763,"surah":2,"verses":[136],"verseLabel":"البقرة: 177، النساء: 136","question":"ما سرّ تقديم اليوم الآخر في أركان الإيمان بآية البر، وتأخيره في النساء: 136؟","answer":"تتحدث البقرة عن المؤمن الصادق الذي يعمل للقاء الله؛ فأقرب ما يحرّك سعيه بعد الإيمان بالله هو رجاء الآخرة وخوفها، لذلك قُدّمت. أما النساء فتحذر من الكافر بهذه الأصول، والآخرة أبعد الحقائق عن اعتناء الكافر وتصديقه، فأُخرت في ذكر ما ينكره. فترتيب البقرة يصور دوافع المؤمن، وترتيب النساء يصور تدرج المنكر في البعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص756–757، تحت البقرة: 177، في المقارنة بالنساء: 136.","url":""}]},{"id":"s2-764","number":764,"surah":2,"verses":[177],"verseLabel":"البقرة: 177","question":"ما سرّ افتتاح آية البر بنفي أن يكون البر تولية الوجوه قبل المشرق والمغرب؟","answer":"الآية تصحح اختزال البر في جهة الصلاة بعد جدل القبلة؛ فنفت أن تكون صورة التوجه وحدها حقيقة البر، ثم بينت أن البر عقيدة وعمل ووفاء وصبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص745–753، تحت البقرة: 177، في مناسبة الآية والقصر في نفي البر.","url":""}]},{"id":"s2-765","number":765,"surah":2,"verses":[177],"verseLabel":"البقرة: 177","question":"ما سرّ التعبير في قوله تعالى: ﴿أَنْ تُوَلُّوا وُجُوهَكُمْ﴾، دون أن يقال: «أن تتجهوا»؟","answer":"لأن الوجه أشرف ما يظهر من الإنسان وبه تتحقق هيئة الاستقبال، فذكره يجسم صورة المتجادلين في الجهة. كما يوحي بأن تحريك الوجه وحده لا يكفي ما لم يتوجه القلب والعمل إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص751–754، تحت البقرة: 177، في ذكر الوجوه.","url":""}]},{"id":"s2-766","number":766,"surah":2,"verses":[177],"verseLabel":"البقرة: 177","question":"ما سرّ تخصيص المشرق والمغرب بالذكر دون سائر الجهات؟","answer":"لأنهما الجهتان اللتان دار حولهما نزاع القبلة: بيت المقدس في جهة، والكعبة في الأخرى؛ فذكرهما يستوعب طرفي الجدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص752–754، تحت البقرة: 177، في الاقتصار على الجهتين.","url":""}]},{"id":"s2-767","number":767,"surah":2,"verses":[177],"verseLabel":"البقرة: 177","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَكِنَّ الْبِرَّ مَنْ آمَنَ﴾، فجعل البر شخصًا لا عملًا؟","answer":"فيه حذف مضاف، أي: ولكن ذا البر من آمن، أو أطلق المصدر على صاحبه مبالغة حتى كأن المؤمن هو البر نفسه؛ وفي ذلك ربط وثيق بين البر وصاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص754–756، تحت البقرة: 177، في الإخبار باسم الذات عن المعنى.","url":""}]},{"id":"s2-768","number":768,"surah":2,"verses":[177],"verseLabel":"البقرة: 177","question":"ما سرّ البدء في خصال البر بالإيمان بالله واليوم الآخر؟","answer":"لأن الإيمان بالله أصل الأعمال ومصدر الإخلاص، والإيمان بالآخرة دافع المحاسبة والجزاء؛ فإذا استقاما نشأت بقية الخصال على أساسها. فقدم الباطن الذي يمنح السلوك معناه قبل تفصيل البذل والوفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص756–758، تحت البقرة: 177، في ترتيب أركان الإيمان.","url":""}]},{"id":"s2-769","number":769,"surah":2,"verses":[177],"verseLabel":"البقرة: 177","question":"ما سرّ إفراد ﴿الْكِتَابِ﴾ وجمع ﴿الْمَلَائِكَةِ﴾ و﴿النَّبِيِّينَ﴾؟","answer":"أفرد الكتاب باعتبار جنس الوحي ووحدته في الأصل والغاية، أما الملائكة والنبيون فذوات متعددة يجب الإيمان بها. فالإفراد يبرز وحدة الرسالة، والجمع يراعي تعدد حملتها ومبلغيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص757–759، تحت البقرة: 177، في إفراد الكتاب وتعريف النبيين.","url":""}]},{"id":"s2-770","number":770,"surah":2,"verses":[177],"verseLabel":"البقرة: 177","question":"إلى مَن يعود الضمير في قوله: ﴿وَآتَى الْمَالَ عَلَى حُبِّهِ﴾؟","answer":"يحتمل الضمير أن يعود إلى المال؛ أي بذله مع محبته له، ويحتمل أن يعود إلى الله؛ أي آتى المال على حب الله. والمعنيان يلتقيان في إخلاص البذل مع مجاهدة النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص759–761، تحت البقرة: 177، في احتمالات الضمير ودلالة ﴿على حبه﴾.","url":""}]},{"id":"s2-771","number":771,"surah":2,"verses":[177],"verseLabel":"البقرة: 177","question":"ما سرّ تقديم ﴿ذَوِي الْقُرْبَى﴾ في مصارف المال؟","answer":"لأن حقهم يجمع الصلة والحاجة، ولأن النفوس قد تتجاوز القريب حياءً أو خصومةً مع معرفتها بحاله. فبدأ بالأقرب مسؤولية، ثم وسع دوائر الرحمة إلى اليتامى والمساكين وابن السبيل والسائلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص760–762، تحت البقرة: 177، في ترتيب جهات الإيتاء.","url":""}]},{"id":"s2-772","number":772,"surah":2,"verses":[177],"verseLabel":"البقرة: 177","question":"ما سرّ التعبير في قوله تعالى: ﴿ابْنَ السَّبِيلِ﴾، فأضاف المسافر إلى الطريق؟","answer":"صوّره كأنه ابن للطريق لشدة ملازمته له وانقطاعه عن أهله وماله؛ فالإضافة تستحضر غربته وحاجته ولو كان غنيًا في بلده. إنها صورة تختصر حال المسافر المنقطع.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص761–762، تحت البقرة: 177، في إضافة الابن إلى السبيل.","url":""}]},{"id":"s2-773","number":773,"surah":2,"verses":[177],"verseLabel":"البقرة: 177","question":"ما سرّ التعبير في قوله تعالى: ﴿وَفِي الرِّقَابِ﴾، دون أن يقال: «والرقاب» مثل بقية الأصناف؟","answer":"دلت ﴿في﴾ على إدخال المال في فك الرقاب وتحريرها، فالمراد الإسهام في عملية التحرير، لا مجرد تسليم المال إلى شخص كما في بقية الأصناف.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص762–764، تحت البقرة: 177، في استعمال ﴿في﴾ مع الرقاب.","url":""}]},{"id":"s2-774","number":774,"surah":2,"verses":[177],"verseLabel":"البقرة: 177","question":"ما سرّ التعبير في قوله تعالى: ﴿أَقَامَ الصَّلَاةَ وَآتَى الزَّكَاةَ﴾ بعد قوله: ﴿وَآتَى الْمَالَ عَلَى حُبِّهِ﴾؟","answer":"إيتاء المال الأول تطوع واسع في وجوه البر، أما الزكاة فحق مفروض مضبوط؛ فذكرهما ليجمع البر بين البذل الاختياري وأداء الواجب المالي.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص763–765، تحت البقرة: 177، في الجمع بين إيتاء المال والزكاة.","url":""}]},{"id":"s2-775","number":775,"surah":2,"verses":[177],"verseLabel":"البقرة: 177","question":"ما دلالة إفراد ﴿عَهْدِهِمْ﴾ مع تعدد العهود؟","answer":"أفرد العهد باعتبار الجنس أو باعتباره أمرًا جامعًا لكل ما التزمه الإنسان مع الله والناس؛ فتدخل تحته العهود المتعددة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص765–766، تحت البقرة: 177، في إفراد العهد.","url":""}]},{"id":"s2-776","number":776,"surah":2,"verses":[177],"verseLabel":"البقرة: 177","question":"ما سرّ رفع ﴿وَالْمُوفُونَ﴾ ثم نصب ﴿وَالصَّابِرِينَ﴾ وسط الصفات؟","answer":"رفع ﴿الموفون﴾ عطفًا على معنى الجملة، ونصب ﴿الصابرين﴾ على الاختصاص بالمدح؛ فقطع النسق لتنبيه السامع إلى عظم منزلة الصبر في الشدائد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص764–768، تحت البقرة: 177، في رفع الموفين ونصب الصابرين.","url":""}]},{"id":"s2-777","number":777,"surah":2,"verses":[177],"verseLabel":"البقرة: 177","question":"ما سرّ ترتيب الصبر في ﴿الْبَأْسَاءِ وَالضَّرَّاءِ وَحِينَ الْبَأْسِ﴾؟","answer":"البأساء شدة الفقر، والضراء ما يصيب البدن، وحين البأس وقت القتال؛ فرتب الصبر في المال والبدن ثم في أشد المواقف وأخطرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص767–769، تحت البقرة: 177، في ترتيب أنواع الشدة.","url":""}]},{"id":"s2-778","number":778,"surah":2,"verses":[177],"verseLabel":"البقرة: 177","question":"ما دلالة تكرار ﴿أُولَئِكَ﴾ في قوله تعالى: ﴿أُولَئِكَ الَّذِينَ صَدَقُوا وَأُولَئِكَ هُمُ الْمُتَّقُونَ﴾؟","answer":"كرر اسم الإشارة ليستقل كل حكم: صدقهم نتيجة اجتماع خصال البر، ثم ثبتت لهم منزلة التقوى. وضمير الفصل والتعريف يقويان اختصاصهم بكمال التقوى في المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص769–772، تحت البقرة: 177، في الاستئناف والحصر وتكرار الإشارة.","url":""}]},{"id":"s2-779","number":779,"surah":2,"verses":[178],"verseLabel":"البقرة: 178","question":"ما سرّ التعبير في قوله تعالى: ﴿كتب عليكم القصاص﴾ مع أن القصاص حق لأولياء القتيل؟","answer":"كتب على الجماعة إقامة نظامه ومنع الثأر المتجاوز، وعلى أولياء الدم التزام حدوده؛ فالحكم يحمي المجتمع ولا يخص صاحب الحق وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص777–790، تحت البقرة: 178.","url":""}]},{"id":"s2-780","number":780,"surah":2,"verses":[178],"verseLabel":"البقرة: 178","question":"ما سرّ التعبير في قوله تعالى: ﴿القتلى﴾ بالجمع، ثم فصّل: الحر بالحر والعبد بالعبد والأنثى بالأنثى؟","answer":"أجمل جنس الوقائع أولًا ثم أبطل صور الجاهلية التي تقتل غير الجاني أو تضاعف الثأر بحسب الطبقة، فرد القصاص إلى المماثلة والعدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص780، تحت البقرة: 178.","url":""}]},{"id":"s2-781","number":781,"surah":2,"verses":[178],"verseLabel":"البقرة: 178","question":"ما مناسبة افتتاح حكم القصاص بقوله تعالى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا﴾؟","answer":"استثير وصف الإيمان ليهيئ النفوس لقبول حكم يمس الدماء والرغبة في الانتقام؛ فمقتضى الإيمان التسليم لعدل الله وضبط القصاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص773–776، تحت البقرة: 178، في مناداة المؤمنين.","url":""}]},{"id":"s2-782","number":782,"surah":2,"verses":[178],"verseLabel":"البقرة: 178","question":"ما سرّ التعبير في قوله تعالى: ﴿كُتِبَ عَلَيْكُمُ الْقِصَاصُ﴾، دون أن يقال: «أُمرتم بالقصاص»؟","answer":"﴿كتب﴾ تدل على الفرض والإثبات، وكأن الحكم سجل فلا يعبث به غضب ولا جاهلية. وبناء الفعل للمجهول يوجه النظر إلى ثقل الفريضة واستقرارها، مع العلم بأن الكاتب هو الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص776–777، تحت البقرة: 178، في دلالة ﴿كتب عليكم﴾.","url":""}]},{"id":"s2-783","number":783,"surah":2,"verses":[178],"verseLabel":"البقرة: 178","question":"ما سرّ التعبير في قوله تعالى: ﴿الْقِصَاصُ فِي الْقَتْلَى﴾، دون أن يقال: «أن تقتلوا القاتل»؟","answer":"اللفظ يجعل الأساس المماثلة العادلة في جنايات القتل كلها، لا مجرد فعل انتقام؛ والجار والمجرور يحدد مجال الحكم. كما أن جمع القتلى يوجه التشريع للأمة في كل واقعة لا لحادثة مفردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص777–779، تحت البقرة: 178، في الإيجاز والحذف في ﴿في القتلى﴾.","url":""}]},{"id":"s2-784","number":784,"surah":2,"verses":[178],"verseLabel":"البقرة: 178","question":"ما سرّ التفصيل في قوله تعالى: ﴿الْحُرُّ بِالْحُرِّ وَالْعَبْدُ بِالْعَبْدِ وَالْأُنْثَى بِالْأُنْثَى﴾؟","answer":"جاء التفصيل لإبطال تجاوزات الجاهلية التي كانت تقتل الحر بالعبد والرجل بالمرأة طلبًا للمفاخرة، فأثبت المماثلة ومنع العدوان في القصاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص777–780، تحت البقرة: 178، في معنى المماثلة ودفع عادة الجاهلية.","url":""}]},{"id":"s2-785","number":785,"surah":2,"verses":[178],"verseLabel":"البقرة: 178","question":"ما سرّ إفراد الأنثى بالذكر مع دخولها في عموم القتلى؟","answer":"ذكرت الأنثى ردًا على من كان لا يقتص للمرأة أو يطلب بها رجلًا، وللتصريح بأن دمها مصون وأن المماثلة تشملها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص779–780، تحت البقرة: 178، في إفراد الأنثى.","url":""}]},{"id":"s2-786","number":786,"surah":2,"verses":[178],"verseLabel":"البقرة: 178","question":"ما سرّ التعبير في قوله تعالى: ﴿فَمَنْ عُفِيَ لَهُ﴾ بالفاء؟","answer":"الفاء تفرع باب العفو والدية على أصل القصاص فورًا، فتدل على أن التشريع لم يغلق طريق الصلح. وبعد تقرير الحق الكامل ينتقل إلى ما يختاره ولي الدم من تخفيف بلا انقطاع في السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص780–781، تحت البقرة: 178، في دلالة الفاء.","url":""}]},{"id":"s2-787","number":787,"surah":2,"verses":[178],"verseLabel":"البقرة: 178","question":"ما سرّ وصف القاتل بالأخوة في قوله تعالى: ﴿مِنْ أَخِيهِ﴾ بعد جريمة القتل؟","answer":"أبقى وصف الأخوة الإيمانية للقاتل تنبيهًا إلى أن الجريمة لا تمحو أصل الأخوة، وترقيقًا لقلب ولي الدم ليفتح باب العفو والدية.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص780–782، تحت البقرة: 178، في استعمال الأخوة.","url":""}]},{"id":"s2-788","number":788,"surah":2,"verses":[178],"verseLabel":"البقرة: 178","question":"ما سرّ التعبير في قوله تعالى: ﴿شَيْءٌ﴾ في قوله: ﴿فَمَنْ عُفِيَ لَهُ مِنْ أَخِيهِ شَيْءٌ﴾؟","answer":"نكر ﴿شيء﴾ ليشمل أي قدر من العفو، ولو عن بعض الحق أو من بعض الأولياء؛ فإذا حصل شيء منه انتقل الحكم إلى اتباع المعروف وأداء الدية.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص781–782، تحت البقرة: 178، في تنكير ﴿شيء﴾.","url":""}]},{"id":"s2-789","number":789,"surah":2,"verses":[178],"verseLabel":"البقرة: 178","question":"ما سرّ التعبير في قوله تعالى: ﴿فَاتِّبَاعٌ بِالْمَعْرُوفِ وَأَدَاءٌ إِلَيْهِ بِإِحْسَانٍ﴾، ولم يذكر الفاعلين؟","answer":"حذف الفاعلان للعلم بهما ولتوجيه العناية إلى الواجبين نفسيهما: على ولي الدم اتباع المطالبة بالمعروف، وعلى القاتل أداء الدية بإحسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص782–783، تحت البقرة: 178، في الحذف والعدول إلى المصدر.","url":""}]},{"id":"s2-790","number":790,"surah":2,"verses":[178],"verseLabel":"البقرة: 178","question":"ما سرّ الجمع بين ﴿بِالْمَعْرُوفِ﴾ و﴿بِإِحْسَانٍ﴾؟","answer":"المعروف يضبط مطالبة ولي الدم فلا يشدد أو يعنف، والإحسان يضبط أداء القاتل فلا يماطل أو ينقص؛ فلكل طرف أدب يناسب موقعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص782–784، تحت البقرة: 178، في توزيع واجبي الاتباع والأداء.","url":""}]},{"id":"s2-791","number":791,"surah":2,"verses":[178],"verseLabel":"البقرة: 178","question":"ما سرّ التعبير في قوله تعالى: ﴿ذَلِكَ تَخْفِيفٌ مِنْ رَبِّكُمْ وَرَحْمَةٌ﴾ بعد تشريع القصاص؟","answer":"الإشارة إلى فتح خيار العفو والدية بعد أن كان موجب الجناية القصاص؛ فهو تخفيف عن القاتل وولي الدم، ورحمة بالمجتمع والأسرتين. وإضافة الرب إلى المخاطبين تشعر بأن الحكم تربية ورعاية لا عقوبة مجردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص783–785، تحت البقرة: 178، في اسم الإشارة والجمع بين التخفيف والرحمة.","url":""}]},{"id":"s2-792","number":792,"surah":2,"verses":[178],"verseLabel":"البقرة: 178","question":"ما مناسبة الوعيد بقوله تعالى: ﴿فَمَنِ اعْتَدَى بَعْدَ ذَلِكَ فَلَهُ عَذَابٌ أَلِيمٌ﴾ بعد التخفيف والرحمة؟","answer":"لما فتح باب العفو والدية، شدد الوعيد على من يعود إلى الاعتداء بعد قبول هذا التخفيف؛ حتى لا تتحول الرحمة إلى ذريعة لثأر جديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص784–786، تحت البقرة: 178، في تقديم العدل على الرحمة ووعيد المعتدي.","url":""}]},{"id":"s2-793","number":793,"surah":2,"verses":[179],"verseLabel":"البقرة: 179","question":"ما وجه وصف القصاص بالحياة في قوله تعالى: ﴿وَلَكُمْ فِي الْقِصَاصِ حَيَاةٌ﴾ مع أنه قتل؟","answer":"في القصاص حياة لأنه يردع من يهم بالقتل، ويحفظ حياة الجاني من تعدي أولياء الدم إلى غيره، ويمنع امتداد الثأر؛ فيفوت بقتل واحد قتل كثير.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص791–794، تحت البقرة: 179.","url":""}]},{"id":"s2-794","number":794,"surah":2,"verses":[179],"verseLabel":"البقرة: 179","question":"ما سرّ تعريف ﴿القصاص﴾ وتنكير ﴿حياة﴾؟","answer":"عُرّف القصاص لأنه الحكم المعهود المحدد، ونُكرت ﴿حياة﴾ للتعظيم والتكثير؛ أي لكم فيه نوع عظيم واسع من الحياة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص791، تحت البقرة: 179.","url":""}]},{"id":"s2-795","number":795,"surah":2,"verses":[179],"verseLabel":"البقرة: 179","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَكُمْ فِي الْقِصَاصِ حَيَاةٌ﴾ فقدم ﴿لكم﴾؟","answer":"ليؤكد أن ثمرة الحكم عائدة إلى المجتمع كله، حتى من لم تقع منه جناية؛ فليس القصاص انتقامًا لأسرة وحدها، بل ضمان حياة وأمن للمخاطبين جميعًا. والتقديم يواجه النفرة من العقوبة بإبراز منفعتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص787–789، تحت البقرة: 179، في تقديم الجار والمجرور.","url":""}]},{"id":"s2-796","number":796,"surah":2,"verses":[179],"verseLabel":"البقرة: 179","question":"ما سرّ التعبير في قوله تعالى: ﴿فِي الْقِصَاصِ حَيَاةٌ﴾ باستعمال ﴿في﴾؟","answer":"جعل الحياة كأنها مودعة داخل القصاص مع أن ظاهره قتل؛ وهذه المفارقة البيانية تدعو إلى استخراج الحكمة الكامنة: الردع يزيل سبب الموت، وإزالة سبب الموت إبقاء للحياة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص788–790، تحت البقرة: 179، في المجاز والظرفية.","url":""}]},{"id":"s2-797","number":797,"surah":2,"verses":[179],"verseLabel":"البقرة: 179","question":"ما مناسبة النداء بقوله: ﴿يَا أُولِي الْأَلْبَابِ﴾ والختم بقوله: ﴿لَعَلَّكُمْ تَتَّقُونَ﴾؟","answer":"خص أولي الألباب لأنهم الذين يدركون الحياة الكامنة وراء ظاهر القصاص. وختم بالتقوى لأن استشعار القصاص يردع عن القتل ويحمل على اتقاء العدوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص790–793، تحت البقرة: 179، في نداء أولي الألباب وتعليل الحكم.","url":""}]},{"id":"s2-798","number":798,"surah":2,"verses":[178],"verseLabel":"البقرة: 180 والبقرة: 178","question":"ما سرّ تكرار ﴿كُتِبَ عَلَيْكُمْ﴾ في الوصية بعد وروده في القصاص؟","answer":"كرر ﴿كتب عليكم﴾ لأن الآية انتقلت إلى حكم مستقل مؤكد هو الوصية، كما أكد به حكم القصاص؛ فالتكرار يساوي بينهما في لزوم الامتثال بحسب تشريعهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص794–796، تحت البقرة: 180، في دلالة تكرار ﴿كتب عليكم﴾.","url":""}]},{"id":"s2-799","number":799,"surah":2,"verses":[180],"verseLabel":"البقرة: 180","question":"ما سرّ التعبير في قوله تعالى: ﴿إِذَا حَضَرَ أَحَدَكُمُ الْمَوْتُ﴾ بـ﴿إذا﴾، دون أن يقال: «إن حضر»؟","answer":"لأن الموت متحقق الوقوع لا مشكوك فيه، و﴿إذا﴾ تستعمل للمتوقع المتيقن؛ والمراد حضور أسبابه وعلاماته لا حضور الموت التام الذي ينقطع معه العمل. فالصيغة تجمع اليقين والتنبيه إلى وقت المبادرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص795–797، تحت البقرة: 180، في ظرفية ﴿إذا﴾ وشرطيتها.","url":""}]},{"id":"s2-800","number":800,"surah":2,"verses":[180],"verseLabel":"البقرة: 180","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنْ تَرَكَ خَيْرًا﴾، دون أن يقال: «إن ترك مالًا»؟","answer":"سمى المال خيرًا ليشير إلى أن ما تصح الوصية به مال حلال طيب ذو قدر، لا كسب خبيثًا يقره صاحبه بعد موته. واللفظ يذكر بأن المال وسيلة خير حين يحسن الإنسان توجيهه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص797–798، تحت البقرة: 180، في تسمية المال خيرًا.","url":""}]},{"id":"s2-801","number":801,"surah":2,"verses":[180],"verseLabel":"البقرة: 180","question":"ما سرّ عطف ﴿الْأَقْرَبِينَ﴾ على ﴿الْوَالِدَيْنِ﴾ مع دخولهما في الأقربين؟","answer":"عطف الأقربين للتعميم بعد التخصيص؛ فالوالدان أحق الناس بالوصية، ثم يليهما سائر الأقربين، فاجتمع التنويه بالأصل واستيعاب بقية القرابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص798–799، تحت البقرة: 180، في عطف الخاص على العام.","url":""}]},{"id":"s2-802","number":802,"surah":2,"verses":[180],"verseLabel":"البقرة: 180","question":"ما دلالة تقييد الوصية بقوله تعالى: ﴿بِالْمَعْرُوفِ﴾؟","answer":"المعروف هو ما تقره الشريعة من العدل من غير إضرار بالورثة ولا محاباة ولا تجاوز للقدر؛ فالقيد يمنع أن تسمى الوصية الجائرة برًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص798–799، تحت البقرة: 180، في قصدية لفظ المعروف.","url":""}]},{"id":"s2-803","number":803,"surah":2,"verses":[180],"verseLabel":"البقرة: 180","question":"ما سرّ التعبير في قوله تعالى: ﴿حَقًّا﴾ بعد أن قال: ﴿كُتِبَ عَلَيْكُمْ﴾؟","answer":"﴿حقًا﴾ مصدر مؤكد لمضمون الكتابة، يزيد تقرير الوجوب ويقطع توهم أن الوصية مجرد استحباب مهمل في مقامها. فاجتمع لفظ الفرض ومصدر التوكيد لتشديد حفظ الحقوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص799–800، تحت البقرة: 180، في التوكيد بالمصدر.","url":""}]},{"id":"s2-804","number":804,"surah":2,"verses":[180],"verseLabel":"البقرة: 180","question":"ما سرّ التعبير في قوله تعالى: ﴿حَقًّا عَلَى الْمُتَّقِينَ﴾، مع أن الحكم لا يختص بالمتقين؟","answer":"خصهم بالذكر تشريفًا وإغراءً بالاقتداء؛ لأنهم أسرع إلى تنفيذ أمر الله حين تضيق النفس بالمال أو يحضر الموت. فليس القيد لإخراج غيرهم، بل للإيحاء بأن الوفاء بهذا الحق علامة تقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص799–800، تحت البقرة: 180، في تخصيص المتقين.","url":""}]},{"id":"s2-805","number":805,"surah":2,"verses":[181],"verseLabel":"البقرة: 181","question":"ما سرّ التعبير في قوله تعالى عن الوصية: ﴿فَمَنْ بَدَّلَهُ﴾ بضمير مذكر، دون أن يقال: «بدّلها»؟","answer":"أعاد الضمير إلى الإيصاء أو القول المسموع، وكلاهما مذكر، لا إلى لفظ الوصية وحده؛ فالممنوع تبديل مضمون ما أوصى به الميت وبلّغه. وفي العدول تنبيه إلى أن الأمانة هي الكلام المثبت لا مجرد اسم الوصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص10–14، تحت البقرة: 181، في تذكير الضمير.","url":""}]},{"id":"s2-806","number":806,"surah":2,"verses":[181],"verseLabel":"البقرة: 181","question":"ما دلالة تقييد التبديل بقوله تعالى: ﴿بَعْدَ مَا سَمِعَهُ﴾؟","answer":"ليثبت أن الإثم على من غيّر الوصية بعد علمها والتحقق منها، فلا يؤاخذ بما لم يبلغه أو بما اشتبه عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص10–12، تحت البقرة: 181، في تقييد التبديل بالسماع.","url":""}]},{"id":"s2-807","number":807,"surah":2,"verses":[181],"verseLabel":"البقرة: 181","question":"ما سرّ البدء بالمفرد في ﴿فَمَنْ بَدَّلَهُ﴾ ثم مراعاة المعنى بالجمع في ﴿عَلَى الَّذِينَ يُبَدِّلُونَهُ﴾؟","answer":"روعي لفظ ﴿من﴾ أولًا فأفرد الضمير في ﴿بدله﴾، ثم روعي معناها العام فجمع في ﴿يبدلونه﴾؛ فالحكم يبدأ بكل فرد ويعم كل المبدلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص11–13، تحت البقرة: 181، في العدول من المفرد إلى الجمع.","url":""}]},{"id":"s2-808","number":808,"surah":2,"verses":[181],"verseLabel":"البقرة: 181","question":"ما سرّ التعبير في قوله تعالى: ﴿عَلَى الَّذِينَ يُبَدِّلُونَهُ﴾، دون أن يقال: «فعليهم إثمه»؟","answer":"أعاد الموصول ليعلق الحكم بالصفة نفسها: التبديل هو سبب الإثم. وبدل أن يخفيهم الضمير، سماهم مرة أخرى بفعلهم ليشهّر بالجناية ويقرر أن من اتصف بها دخل في الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص12–13، تحت البقرة: 181، في وضع الموصول موضع الضمير.","url":""}]},{"id":"s2-809","number":809,"surah":2,"verses":[181],"verseLabel":"البقرة: 181","question":"ما مناسبة ختم التحذير من تبديل الوصية بقوله تعالى: ﴿إِنَّ اللَّهَ سَمِيعٌ عَلِيمٌ﴾؟","answer":"الله سميع لوصية الموصي وما يقوله المبدلون، عليم بالنيات والتغيير الخفي؛ فناسب الاسمان وعيد من قد يظن أن التبديل لا يطلع عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص12–14، تحت البقرة: 181، في مناسبة التذييل.","url":""}]},{"id":"s2-810","number":810,"surah":2,"verses":[182],"verseLabel":"البقرة: 182","question":"ما سرّ التعبير في قوله تعالى في إصلاح الوصية ﴿فلا إثم عليه﴾، دون أن يقال: فله أجر؟","answer":"لأن المصلح قد يغير ألفاظ وصية فيخشى أن يدخل في وعيد التبديل، فالمقصود أولًا رفع هذا الحرج، والأجر مفهوم من الإصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص22، تحت البقرة: 182.","url":""}]},{"id":"s2-811","number":811,"surah":2,"verses":[182],"verseLabel":"البقرة: 182","question":"ما سرّ التعبير في قوله تعالى: ﴿فَمَنْ خَافَ مِنْ مُوصٍ جَنَفًا أَوْ إِثْمًا﴾، مع أن الخوف يكون من أمر مستقبل؟","answer":"الخوف هنا بمعنى التوقع القوي أو العلم بأمارات الميل؛ فيجوز لمن ظهرت له بوادر جنف الموصي أو إثمه أن يصلح قبل التنفيذ أو بعده، فلا يختص الخوف بمجهول مستقبل.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص15–19، تحت البقرة: 182، في دلالة الخوف.","url":""}]},{"id":"s2-812","number":812,"surah":2,"verses":[182],"verseLabel":"البقرة: 182","question":"ما سرّ الجمع بين ﴿جَنَفًا﴾ و﴿إِثْمًا﴾؟","answer":"الجنف ميل عن العدل قد يقع خطأ أو جهلًا، والإثم ميل متعمد مع العلم؛ فجمعهما ليشمل الخلل غير المقصود والمقصود في الوصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص17–21، تحت البقرة: 182، في الفرق بين الجنف والإثم.","url":""}]},{"id":"s2-813","number":813,"surah":2,"verses":[182],"verseLabel":"البقرة: 182","question":"ما سرّ التعبير في قوله تعالى: ﴿فَأَصْلَحَ بَيْنَهُمْ﴾، ولم يذكر بين مَن ومَن؟","answer":"دل سياق الوصية على الأطراف: الموصي والموصى لهم والورثة وأهل الحقوق، وحذفهم ليعم كل من نشأ النزاع بينهم. فالعبرة بإعادة العدل إلى شبكة العلاقات كلها، لا بصورة نزاع واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص19–22، تحت البقرة: 182، في حذف أطراف الإصلاح.","url":""}]},{"id":"s2-814","number":814,"surah":2,"verses":[182],"verseLabel":"البقرة: 182","question":"ما وجه نفي الإثم عن المصلح في قوله تعالى: ﴿فَلَا إِثْمَ عَلَيْهِ﴾ مع أنه يصلح الوصية؟","answer":"لأن تغيير الوصية بعد سماعها مظنة الإثم، فنفى الحرج عمن يتدخل لتصحيح جنف أو إثم؛ حتى لا يدخل الإصلاح المشروع في وعيد التبديل المحرم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص20–23، تحت البقرة: 182، في رفع الإثم عن المصلح.","url":""}]},{"id":"s2-815","number":815,"surah":2,"verses":[182],"verseLabel":"البقرة: 182","question":"ما مناسبة ختم إصلاح الوصية بقوله تعالى: ﴿إِنَّ اللَّهَ غَفُورٌ رَحِيمٌ﴾؟","answer":"المغفرة تناسب ما وقع من جنف أو إثم وما قد يقع من المصلح من اجتهاد، والرحمة تناسب فتح باب الصلح بدل ترك الخصومة. فالخاتمة تطمئن إلى أن مقصد الحكم إزالة الظلم وحفظ الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص22–24، تحت البقرة: 182، في مناسبة الغفور الرحيم.","url":""}]},{"id":"s2-816","number":816,"surah":2,"verses":[183],"verseLabel":"البقرة: 183","question":"ما سرّ التعبير في قوله تعالى: ﴿كتب عليكم الصيام﴾ كما قال في القصاص والقتال؟","answer":"﴿كتب﴾ تدل على فرض ثابت مؤكد، وتناسب التكاليف التي تحتاج إلى عزم وضبط للنفس، مثل القصاص والقتال والصيام.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص31–43، تحت البقرة: 183.","url":""}]},{"id":"s2-817","number":817,"surah":2,"verses":[183],"verseLabel":"البقرة: 183","question":"ما مناسبة نداء المؤمنين قبل فرض الصيام بقوله تعالى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا﴾؟","answer":"استدعى فيهم وصف الإيمان ليهون عليهم التكليف ويبعثهم إلى الامتثال؛ فالذي آمن بالآمر يقبل ما يربيه ولو شق على النفس. والنداء يشعر بأن الصيام مقتضى إيمانهم لا عبئًا منفصلًا عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص25–28، تحت البقرة: 183، في النداء بوصف الإيمان.","url":""}]},{"id":"s2-818","number":818,"surah":2,"verses":[183],"verseLabel":"البقرة: 183","question":"ما سرّ التعبير في قوله تعالى: ﴿كُتِبَ عَلَيْكُمُ الصِّيَامُ﴾، دون أن يقال: «صوموا»؟","answer":"﴿كتب﴾ تفيد الفرض الثابت المسجل، و﴿عليكم﴾ تستحضر تبعة التكليف قبل تفصيله؛ فالصيام ليس نصيحة عارضة. وبناء الفعل للمجهول يركز على عظمة المكتوب مع وضوح أن فارضه الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص27–31، تحت البقرة: 183، في بناء ﴿كتب﴾ وتقديم الجار والمجرور.","url":""}]},{"id":"s2-819","number":819,"surah":2,"verses":[183],"verseLabel":"البقرة: 183","question":"ما سرّ التعبير في قوله تعالى: ﴿كَمَا كُتِبَ عَلَى الَّذِينَ مِنْ قَبْلِكُمْ﴾؟","answer":"ليؤنس المكلفين بأنهم ليسوا أول من حمل هذه العبادة، وليدل على قدم الصيام وشرفه وملاءمته لتربية البشر في الشرائع. فاشتراك الأمم فيه يخفف استثقاله ويعظم منزلته.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص29–34، تحت البقرة: 183، في حكمة التشبيه بالسابقين.","url":""}]},{"id":"s2-820","number":820,"surah":2,"verses":[183],"verseLabel":"البقرة: 183","question":"هل تعني ﴿كَمَا كُتِبَ﴾ أن صيامنا مماثل تمامًا لصيام الأمم السابقة؟","answer":"التشبيه في أصل فرض الصيام، لا في تطابق الأيام والكيفية وسائر الأحكام؛ أي كتب عليكم الصيام كما كتب على من قبلكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص31–35، تحت البقرة: 183، في وجه التشبيه المجمل.","url":""}]},{"id":"s2-821","number":821,"surah":2,"verses":[183],"verseLabel":"البقرة: 183","question":"ما سرّ اختيار لفظ ﴿الصِّيَامُ﴾ هنا، واستعمال «الصوم» في موضع آخر؟","answer":"الصيام والصوم يشتركان في أصل الإمساك، وغلب ﴿الصيام﴾ على العبادة الشرعية عن المفطرات، أما الصوم فأصل الإمساك وقد يستعمل في الإمساك عن الكلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص34–36، تحت البقرة: 183، في الفرق بين الصيام والصوم.","url":""}]},{"id":"s2-822","number":822,"surah":2,"verses":[183],"verseLabel":"البقرة: 183","question":"ما مناسبة ختم فرض الصيام بقوله تعالى: ﴿لَعَلَّكُمْ تَتَّقُونَ﴾؟","answer":"لأن الصيام يدرب النفس على ترك المباح امتثالًا، فتقوى على ترك الحرام، ويوقظ مراقبة الله؛ وحذف متعلق التقوى ليعم ما يتقى.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص33–36، تحت البقرة: 183، في تعليل الصيام بالتقوى وحذف المتعلق.","url":""}]},{"id":"s2-823","number":823,"surah":2,"verses":[184],"verseLabel":"البقرة: 184","question":"ما سرّ التعبير في قوله تعالى: ﴿فعدة من أيام أخر﴾ بالجمع ﴿أخر﴾ لا بالإفراد؟","answer":"لأنها صفة لأيام مجموعة، وتفيد أيامًا بديلة متعددة تقابل ما فات، مع سعة اختيارها خارج رمضان.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص45، تحت البقرة: 184.","url":""}]},{"id":"s2-824","number":824,"surah":2,"verses":[184],"verseLabel":"البقرة: 184","question":"ما دلالة إفراد ﴿مسكين﴾ في قوله تعالى: ﴿طَعَامُ مِسْكِينٍ﴾؟","answer":"لأن الفدية عن كل يوم تتعلق بإطعام مسكين واحد، فالإفراد يبين مقدار الواجب مع إمكان جمع الأيام والمساكين.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص47، تحت البقرة: 184.","url":""}]},{"id":"s2-825","number":825,"surah":2,"verses":[184],"verseLabel":"البقرة: 184","question":"ما سرّ التعبير في قوله تعالى عن رمضان: ﴿أَيَّامًا مَعْدُودَاتٍ﴾ مع أنه شهر كامل؟","answer":"وصفها بالمعدودات تهوينًا وتيسيرًا؛ فما كان محدودًا قابلًا للعد والانقضاء يهون احتماله، ولا يستغرق العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص37–41، تحت البقرة: 184، في وصف الأيام بالمعدودات.","url":""}]},{"id":"s2-826","number":826,"surah":2,"verses":[184],"verseLabel":"البقرة: 184","question":"ما سرّ التعبير في قوله تعالى: ﴿أَوْ عَلَى سَفَرٍ﴾، دون أن يقال: «أو مسافرًا»؟","answer":"صوّره متمكنًا من السفر وملابسًا له، كأنه مستعلٍ على مركوبه أو على طريقه؛ فليس مجرد نية سفر عابرة. والعبارة تثبت الحالة التي ترتبط بها الرخصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص42–45، تحت البقرة: 184، في تعدية السفر بـ﴿على﴾.","url":""}]},{"id":"s2-827","number":827,"surah":2,"verses":[184],"verseLabel":"البقرة: 184","question":"ما سرّ التعبير في قوله تعالى: ﴿فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ﴾، دون أن يقال: «فليقضها بعد رمضان»؟","answer":"أوجز فحذف فعل الصيام، وجعل الواجب نفس العدد ليؤكد استيفاء ما فات دون اشتراط أيام بعينها. وتنكير ﴿أيام﴾ يوسع وقت القضاء ما دام من أيام أخرى صالحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص43–47، تحت البقرة: 184، في الإيجاز وتنكير الأيام.","url":""}]},{"id":"s2-828","number":828,"surah":2,"verses":[184],"verseLabel":"البقرة: 184","question":"ما سرّ التعبير في قوله تعالى: ﴿وَعَلَى الَّذِينَ يُطِيقُونَهُ فِدْيَةٌ﴾، مع أن المطيق قادر على الصوم؟","answer":"قيل: الآية في مرحلة كان القادر فيها مخيرًا بين الصيام والفدية ثم نسخ التخيير، وقيل: المراد من لا يطيقه إلا بمشقة بالغة كالكبير والمريض المزمن؛ فالطاقة هنا بلوغ غاية الوسع.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص46–51، تحت البقرة: 184، في معنى ﴿يطيقونه﴾.","url":""}]},{"id":"s2-829","number":829,"surah":2,"verses":[184],"verseLabel":"البقرة: 184","question":"ما مناسبة جعل الفدية ﴿طَعَامُ مِسْكِينٍ﴾؟","answer":"قابل ترك عبادة بدنية بإحسان يصل إلى بدن محتاج؛ فكما حفظ المفطر نفسه من المشقة أطعم نفسًا تدفع عنها مشقة الجوع. وإفراد المسكين يربط كل يوم أفطره بإطعام مسكين.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص49–52، تحت البقرة: 184، في إضافة الطعام وإفراد المسكين.","url":""}]},{"id":"s2-830","number":830,"surah":2,"verses":[184],"verseLabel":"البقرة: 184","question":"ما سرّ التعبير في قوله تعالى: ﴿فَمَنْ تَطَوَّعَ خَيْرًا فَهُوَ خَيْرٌ لَهُ﴾، ولم يحدد نوع الخير؟","answer":"أطلقه ليشمل الزيادة في مقدار الفدية أو عدد المساكين وسائر الإحسان المرتبط بها؛ فلا يحصر التطوع في صورة واحدة. وحذف التفصيل يحفز النفس أن تبحث عن مزيد الخير بحسب قدرتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص50–53، تحت البقرة: 184، في إطلاق التطوع والخير.","url":""}]},{"id":"s2-831","number":831,"surah":2,"verses":[184],"verseLabel":"البقرة: 184","question":"ما سرّ التعبير في قوله تعالى: ﴿وَأَنْ تَصُومُوا خَيْرٌ لَكُمْ﴾ بعد ذكر الفدية؟","answer":"ليبين أن الرخصة أو التخيير لا يجعل البديلين سواء في الفضل؛ فالصيام أبلغ في تحقيق التقوى وتربية الإرادة لمن قدر عليه. وانتقل إلى الخطاب المباشر لتنشيط المكلفين واختيار الأكمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص51–54، تحت البقرة: 184، في الالتفات وترجيح الصوم.","url":""}]},{"id":"s2-832","number":832,"surah":2,"verses":[184],"verseLabel":"البقرة: 184","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿إِنْ كُنْتُمْ تَعْلَمُونَ﴾؟","answer":"لأن خيرية الصوم لها حكم وآثار قد تخفى على من ينظر إلى مشقته العاجلة؛ أي لو علمتم منفعته حق العلم لاخترتموه. والشرط يهز النفس لتتجاوز إحساس الجوع إلى ما وراءه من تربية وثواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص52–54، تحت البقرة: 184، في دلالة الشرط.","url":""}]},{"id":"s2-833","number":833,"surah":2,"verses":[185],"verseLabel":"البقرة: 185","question":"ما سرّ تقديم فضيلة رمضان بإنزال القرآن فيه قبل بيان حكم صيامه؟","answer":"قدم شرف الشهر وسبب اختياره، ليكون صيامه شكرًا على نعمة القرآن والهداية، لا مجرد إمساك عن الطعام والشراب.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص52–70، تحت البقرة: 185.","url":""}]},{"id":"s2-834","number":834,"surah":2,"verses":[185],"verseLabel":"البقرة: 185","question":"ما سرّ الجمع بين ﴿هُدًى لِلنَّاسِ﴾ و﴿بَيِّنَاتٍ مِنَ الْهُدَى وَالْفُرْقَانِ﴾؟","answer":"وصف القرآن أولًا بأنه هداية عامة للناس، ثم بين أنه مشتمل على دلائل واضحة من الهدى ومعايير تفرق بين الحق والباطل؛ فالثاني تفصيل للأول.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص63، تحت البقرة: 185.","url":""}]},{"id":"s2-835","number":835,"surah":2,"verses":[185],"verseLabel":"البقرة: 185","question":"ما سرّ تكرار حكم المريض والمسافر بعد ذكره في الآية السابقة؟","answer":"أعيد الحكم بعد تعيين رمضان حتى لا يظن أن رخصة المرض والسفر كانت في الحكم الأول ثم نسخت؛ فثبت بقاؤها في فرض رمضان النهائي.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص52–70، تحت البقرة: 185.","url":""}]},{"id":"s2-836","number":836,"surah":2,"verses":[185],"verseLabel":"البقرة: 185","question":"ما سرّ العدول من ﴿أَيَّامًا مَعْدُودَاتٍ﴾ إلى التصريح بقوله: ﴿شَهْرُ رَمَضَانَ﴾؟","answer":"أجمل الأيام أولًا لتخفيف وقع التكليف، ثم عينها منعًا لالتباس زمن العبادة ولإيجاب استيعاب الشهر. والتصريح باسم رمضان يزيده تشريفًا بذكر الحدث الذي ميزه: نزول القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص55–59، تحت البقرة: 185، في العدول إلى اسم الشهر.","url":""}]},{"id":"s2-837","number":837,"surah":2,"verses":[185],"verseLabel":"البقرة: 185","question":"ما وجه قوله تعالى: ﴿أُنْزِلَ فِيهِ الْقُرْآنُ﴾ مع نزول القرآن منجمًا في سنوات؟","answer":"المراد ابتداء نزول القرآن في رمضان، وقيل إنزاله جملة إلى السماء الدنيا ثم نزوله منجمًا؛ فنسب الإنزال إلى الشهر لوقوع ابتداء الحدث العظيم فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص57–62، تحت البقرة: 185، في معنى إنزال القرآن في الشهر.","url":""}]},{"id":"s2-838","number":838,"surah":2,"verses":[185],"verseLabel":"البقرة: 185","question":"ما سرّ التعبير في قوله تعالى: ﴿فَمَنْ شَهِدَ مِنْكُمُ الشَّهْرَ فَلْيَصُمْهُ﴾، وهل يُشاهَد الشهر؟","answer":"الشهود بمعنى الحضور والإقامة عند دخول الشهر، أو مشاهدة هلاله؛ والضمير يعود إلى الشهر بمعنى أيامه. فالحكم يتعلق بمن أدرك رمضان حاضرًا قادرًا، لا بمجرد رؤية جسم الشهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص63–66، تحت البقرة: 185، في معنى شهود الشهر وضمير ﴿فليصمه﴾.","url":""}]},{"id":"s2-839","number":839,"surah":2,"verses":[185],"verseLabel":"البقرة: 185","question":"ما سرّ الجمع بين إثبات اليسر ونفي العسر في قوله تعالى: ﴿يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ وَلَا يُرِيدُ بِكُمُ الْعُسْرَ﴾؟","answer":"إثبات إرادة اليسر لا يقطع وحده توهم إرادة بعض العسر، فنفى العسر صراحة لتأكيد مقصد التيسير الذي ظهر في رخصتي المرض والسفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص67–70، تحت البقرة: 185، في الجمع بين الإثبات والنفي.","url":""}]},{"id":"s2-840","number":840,"surah":2,"verses":[185],"verseLabel":"البقرة: 185","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلِتُكْمِلُوا الْعِدَّةَ﴾ بعد رخصة الإفطار؟","answer":"حتى يفهم أن التيسير لا يعني إسقاط العبادة، بل نقل الأيام الفائتة إلى وقت يقدر عليه المكلف؛ فتجتمع الرحمة مع تمام الواجب. والعطف على معنى الرخصة يكشف مقصدها لا ظاهر لفظها فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص68–70، تحت البقرة: 185، في العطف على المعنى وإكمال العدة.","url":""}]},{"id":"s2-841","number":841,"surah":2,"verses":[185],"verseLabel":"البقرة: 185","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلِتُكَبِّرُوا اللَّهَ عَلَى مَا هَدَاكُمْ﴾ بعد الصيام؟","answer":"لأن إتمام العبادة وهداية العبد إلى طريقها يستدعيان تعظيم الهادي، فجعل التكبير خاتمة الخروج من رمضان وإكمال العدة. و﴿على ما هداكم﴾ ترد الفضل إلى الله لا إلى قوة الصائم وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص69–71، تحت البقرة: 185، في تعليل التكبير بالهداية.","url":""}]},{"id":"s2-842","number":842,"surah":2,"verses":[185],"verseLabel":"البقرة: 185","question":"ما مناسبة ختم آية رمضان بقوله تعالى: ﴿وَلَعَلَّكُمْ تَشْكُرُونَ﴾؟","answer":"بدأ الصيام بالتقوى وختم تفصيله بالشكر؛ فبعد أن ذاق المكلف التيسير والهداية وإكمال العبادة يعرف قدر النعمة ويثني على المنعم. والرجاء يحوله من أداء مؤقت إلى أثر دائم في القلب والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص70–71، تحت البقرة: 185، في مناسبة خاتمة الشكر.","url":""}]},{"id":"s2-843","number":843,"surah":2,"verses":[186],"verseLabel":"البقرة: 186","question":"ما مناسبة مجيء آية الدعاء في أثناء آيات الصيام؟","answer":"الصيام مظنة صفاء النفس والإخلاص والدعاء، فجاء ذكر قرب الله وإجابته بين أحكامه ليبين أن غاية العبادة صلة العبد بربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص70–87، تحت البقرة: 186.","url":""}]},{"id":"s2-844","number":844,"surah":2,"verses":[186],"verseLabel":"البقرة: 186","question":"ما سرّ التعبير في قوله تعالى: ﴿فليستجيبوا لي﴾، دون أن يقال: فليجيبوني؟","answer":"الاستجابة تحمل معنى الطاعة والانقياد بعد الدعوة، فليست مجرد جواب لفظي بل مقابلة قرب الله بامتثال أمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص82، تحت البقرة: 186.","url":""}]},{"id":"s2-845","number":845,"surah":2,"verses":[186],"verseLabel":"البقرة: 186","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِذَا سَأَلَكَ عِبَادِي عَنِّي﴾ وأضافهم إلى نفسه؟","answer":"الإضافة تشريف وتقريب قبل أن يأتي الجواب؛ فهم عباده وإن سألوا أو قصروا، والسؤال عن الله لا عن حكم بعيد. ولفظ ﴿عبادي﴾ يهيئ القلب لسماع خبر القرب والرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص73–77، تحت البقرة: 186، في إضافة العباد إلى ضمير الجلالة.","url":""}]},{"id":"s2-846","number":846,"surah":2,"verses":[186],"verseLabel":"البقرة: 186","question":"ما سرّ مجيء جواب سؤال العباد مباشرة: ﴿فَإِنِّي قَرِيبٌ﴾ من غير واسطة ﴿قل﴾؟","answer":"حذفت ﴿قل﴾ إيذانًا بشدة القرب وسرعة الإجابة؛ فجاء الجواب من الله إلى عباده مباشرة من غير ذكر واسطة في العبارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص75–79، تحت البقرة: 186، في حذف ﴿قل﴾ والالتفات إلى التكلم.","url":""}]},{"id":"s2-847","number":847,"surah":2,"verses":[186],"verseLabel":"البقرة: 186","question":"ما معنى قرب الله في قوله تعالى: ﴿فَإِنِّي قَرِيبٌ﴾ مع علوه سبحانه؟","answer":"قرب الله قرب علم وسمع وإجابة ورحمة وإحاطة، لا قرب مسافة أو حلول؛ فهو سبحانه عالٍ على خلقه ولا يحول بينه وبين دعاء عبده شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص76–80، تحت البقرة: 186، في دلالة القرب.","url":""}]},{"id":"s2-848","number":848,"surah":2,"verses":[186],"verseLabel":"البقرة: 186","question":"ما سرّ التعبير في قوله تعالى: ﴿أُجِيبُ دَعْوَةَ الدَّاعِ إِذَا دَعَانِ﴾ وكرر مادة الدعاء؟","answer":"ليجعل الإجابة مرتبطة بالفعل الحقيقي للداعي نفسه لا بمجرد تمنٍّ غافل؛ كلما تحقق منه الدعاء تحقق وعد السماع والإجابة على وجه الحكمة. والتكرار يقرب الحركة بين النداء والجواب حتى تكاد تبدو فورية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص78–81، تحت البقرة: 186، في تكرار مادة الدعاء والشرط.","url":""}]},{"id":"s2-849","number":849,"surah":2,"verses":[186],"verseLabel":"البقرة: 186","question":"ما سرّ التعبير في قوله تعالى: ﴿دَعْوَةَ الدَّاعِ﴾، دون أن يقال: «دعاء العبد»؟","answer":"ركز على الدعوة الواحدة الصادقة وعلى صاحبها حال دعائه؛ فلا يشترط كثرة الكلام ولا منزلة خاصة. واسم الفاعل يستحضر العبد متلبسًا بالدعاء في اللحظة التي يسمعه الله فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص78–81، تحت البقرة: 186، في المصدر واسم الفاعل.","url":""}]},{"id":"s2-850","number":850,"surah":2,"verses":[186],"verseLabel":"البقرة: 186","question":"ما سرّ التعبير في قوله تعالى: ﴿فَلْيَسْتَجِيبُوا لِي وَلْيُؤْمِنُوا بِي﴾، مع أن الإيمان سابق للاستجابة؟","answer":"المطلوب أن يقابلوا إجابة الله لهم بإجابة أوامره، ثم يجددوا إيمانهم وثقتهم بوعده؛ وخص الإيمان بعد عموم الاستجابة لعظم منزلته. فالدعاء علاقة ذات طرفين: سؤال من العبد وطاعة وثقة منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص79–82، تحت البقرة: 186، في ترتيب الاستجابة والإيمان وعطف الخاص.","url":""}]},{"id":"s2-851","number":851,"surah":2,"verses":[186],"verseLabel":"البقرة: 186","question":"ما مناسبة ختم آية الدعاء بقوله تعالى: ﴿لَعَلَّهُمْ يَرْشُدُونَ﴾؟","answer":"حتى لا يظن أن ثمرة الدعاء مقصورة على نيل المطلوب العاجل؛ الغاية الأبعد إصابة الحق وحسن التصرف والهداية إلى ما ينفع. فالاستجابة والإيمان بالله يعيدان توجيه حياة العبد كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص81–83، تحت البقرة: 186، في أهمية الرشد ومناسبة الخاتمة.","url":""}]},{"id":"s2-852","number":852,"surah":2,"verses":[187],"verseLabel":"البقرة: 187","question":"ما سرّ تشبيه الزوجين باللباس في قوله تعالى: ﴿هُنَّ لِبَاسٌ لَكُمْ وَأَنْتُمْ لِبَاسٌ لَهُنَّ﴾؟","answer":"اللباس يلاصق ويستر ويحمي ويمنح السكن والدفء؛ فالتشبيه يجمع شدة القرب والستر والسكن والمنفعة المتبادلة بين الزوجين.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص87–98، تحت البقرة: 187.","url":""}]},{"id":"s2-853","number":853,"surah":2,"verses":[187],"verseLabel":"البقرة: 187","question":"ما سرّ إفراد ﴿لباس﴾ مع ضمير الجمع؟","answer":"لأنه اسم جنس أو مصدر يصدق على كل زوج وزوجة، والإفراد يبرز وحدة الوظيفة المتبادلة لا عدد الأشخاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص91، تحت البقرة: 187.","url":""}]},{"id":"s2-854","number":854,"surah":2,"verses":[187],"verseLabel":"البقرة: 187","question":"ما سرّ التعبير في قوله تعالى: ﴿تختانون أنفسكم﴾ لا: تخونون؟","answer":"صيغة الافتعال تصور تكرر الفعل ومبالغة النفس في خيانتها، وسماه خيانة للذات لأن ضرر مخالفة الحكم يعود عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص93، تحت البقرة: 187.","url":""}]},{"id":"s2-855","number":855,"surah":2,"verses":[187],"verseLabel":"البقرة: 187","question":"ما سرّ اختلاف التعبير عن المعاشرة بلفظ ﴿الرَّفَثُ﴾ ثم ﴿بَاشِرُوهُنَّ﴾؟","answer":"الرفث كناية عامة عن شأن المعاشرة في مقام رفع الحرج، والمباشرة تصور اتصال البشرة حين جاء الإذن بالفعل؛ فتنوع اللفظ مع المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص87–98، تحت البقرة: 187.","url":""}]},{"id":"s2-856","number":856,"surah":2,"verses":[187,229],"verseLabel":"البقرة: 187 و229","question":"ما سرّ اختلاف التعبير بين قوله تعالى في أحكام الصيام: ﴿تِلْكَ حُدُودُ اللَّهِ فَلَا تَقْرَبُوهَا﴾، وقوله تعالى في أحكام الطلاق: ﴿تِلْكَ حُدُودُ اللَّهِ فَلَا تَعْتَدُوهَا﴾؟","answer":"في الصيام نهى عن قربان المحظورات ومقدماتها، فقال ﴿فلا تقربوها﴾ مبالغة في الاحتياط. وفي الطلاق حدود ومقادير مرسومة فناسب النهي عن تجاوزها: ﴿فلا تعتدوها﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص99–101، تحت البقرة: 187، في المقارنة بالبقرة: 229 ونظائرها.","url":""}]},{"id":"s2-857","number":857,"surah":2,"verses":[187],"verseLabel":"البقرة: 187","question":"ما سرّ التعبير في قوله تعالى: ﴿أُحِلَّ لَكُمْ لَيْلَةَ الصِّيَامِ الرَّفَثُ﴾ بالبناء للمجهول؟","answer":"وجه النظر إلى نعمة الإباحة نفسها بعد المنع، مع العلم أن المحل هو الله، ثم صرح باسمه لاحقًا في الحدود والتشريع. والصيغة تبرز انتقال الحكم وتخفيفه على الصائمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص84–87، تحت البقرة: 187، في بناء ﴿أحل﴾ والالتفات.","url":""}]},{"id":"s2-858","number":858,"surah":2,"verses":[187],"verseLabel":"البقرة: 187","question":"ما سرّ التعبير في قوله تعالى: ﴿الرَّفَثُ إِلَى نِسَائِكُمْ﴾ بـ﴿إلى﴾، دون أن يقال: «مع نسائكم»؟","answer":"ضمّن الرفث معنى الإفضاء والانتهاء إلى الزوجة، وجاء التعبير كناية مهذبة تبعد التصوير المكشوف لحال الجماع. فحرف الغاية يؤدي المعنى ويحفظ حياء العبارة القرآنية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص87–90، تحت البقرة: 187، في تعدية الرفث بـ﴿إلى﴾.","url":""}]},{"id":"s2-859","number":859,"surah":2,"verses":[187],"verseLabel":"البقرة: 187","question":"ما سرّ تقديم قوله تعالى: ﴿هُنَّ لِبَاسٌ لَكُمْ﴾ على ﴿وَأَنْتُمْ لِبَاسٌ لَهُنَّ﴾؟","answer":"لأن سياق الإباحة بدأ بالرفث إلى النساء، فكان الحديث عنهن أقرب، وللتنبيه إلى أن حاجتهن إلى السكن والستر معتبرة كما حاجة الرجال. ثم جاءت المقابلة لتثبت التساوي في وظيفة اللباس.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص91–94، تحت البقرة: 187، في تقديم النساء والمقابلة.","url":""}]},{"id":"s2-860","number":860,"surah":2,"verses":[187],"verseLabel":"البقرة: 187","question":"ما سرّ التعبير في قوله تعالى: ﴿فَتَابَ عَلَيْكُمْ وَعَفَا عَنْكُمْ﴾ قبل إباحة المباشرة؟","answer":"قدّم محو أثر المخالفة ليطمئنهم، ثم شرع التخفيف الذي يرفع سببها؛ فالتوبة قبول الرجوع، والعفو إزالة المؤاخذة. وهكذا لم يأت الحكم الجديد مجرد إباحة، بل رحمة تعالج الماضي والمستقبل.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص96–99، تحت البقرة: 187، في ترتيب التوبة والعفو والتخفيف.","url":""}]},{"id":"s2-861","number":861,"surah":2,"verses":[187],"verseLabel":"البقرة: 187","question":"ما سرّ التعبير في قوله تعالى: ﴿فَالْآنَ بَاشِرُوهُنَّ﴾؟","answer":"﴿الآن﴾ ترسم حدًا واضحًا بين الحكم السابق والتوسعة الجديدة، والفاء تفرع الإذن على التوبة والعفو. واختيرت المباشرة كناية عن التقاء البشرتين، أصرح من الرفث في الحكم وأبقى من التصريح الخشن.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص97–100، تحت البقرة: 187، في دلالة ﴿فالآن﴾ والمباشرة.","url":""}]},{"id":"s2-862","number":862,"surah":2,"verses":[187],"verseLabel":"البقرة: 187","question":"ما مناسبة قوله تعالى: ﴿وَابْتَغُوا مَا كَتَبَ اللَّهُ لَكُمْ﴾ بعد إباحة المباشرة؟","answer":"المراد ابتغاء ما قدره الله وأباحه من طلب الولد، وقيل طلب ما كتب من الرخصة والثواب؛ فوجه الإباحة إلى مقصد مشروع لا إلى مجرد قضاء الشهوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص98–101، تحت البقرة: 187، في إطلاق ﴿ما كتب الله لكم﴾.","url":""}]},{"id":"s2-863","number":863,"surah":2,"verses":[187],"verseLabel":"البقرة: 187","question":"ما سرّ التعبير في قوله تعالى: ﴿حَتَّى يَتَبَيَّنَ لَكُمُ الْخَيْطُ الْأَبْيَضُ مِنَ الْخَيْطِ الْأَسْوَدِ﴾؟","answer":"شبّه ضوء الصبح الممتد بخيط أبيض يشق سواد الليل الذي يبدو كخيط أسود، فجعل انتقال الزمن مشهدًا بصريًا يمكن ضبطه. المقصود ظهور الفجر الصادق لا خيطان حسيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص99–101، تحت البقرة: 187، في التشبيه البليغ.","url":""}]},{"id":"s2-864","number":864,"surah":2,"verses":[187],"verseLabel":"البقرة: 187","question":"ما فائدة قوله تعالى: ﴿مِنَ الْفَجْرِ﴾ بعد ذكر الخيط الأبيض والأسود؟","answer":"جاء ﴿من الفجر﴾ بيانًا بعد الاستعارة؛ حتى لا يحمل الخيطان على الحقيقة، فالمراد بياض الصبح وسواد الليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص100–101، تحت البقرة: 187، في البيان بعد التشبيه.","url":""}]},{"id":"s2-865","number":865,"surah":2,"verses":[187],"verseLabel":"البقرة: 187","question":"ما سرّ التعبير في قوله تعالى: ﴿ثُمَّ أَتِمُّوا الصِّيَامَ إِلَى اللَّيْلِ﴾، دون أن يقال: «حتى الليل»؟","answer":"﴿إلى﴾ تحدد غاية الإمساك بوضوح، و﴿ثم﴾ تعطف إتمام الصوم على مرحلة الإباحة الليلية مع بُعد ما بين طرفي الزمن. والتعبير يدل على انتهاء الصوم بدخول الليل وينفي وصال الصيام بعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص100–102، تحت البقرة: 187، في العطف والغاية.","url":""}]},{"id":"s2-866","number":866,"surah":2,"verses":[187],"verseLabel":"البقرة: 187","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا تُبَاشِرُوهُنَّ وَأَنْتُمْ عَاكِفُونَ فِي الْمَسَاجِدِ﴾ بعد إباحتها ليلًا؟","answer":"لأن إباحة الليل عامة، فاستثنى حال الاعتكاف التي ينقطع فيها العبد لعبادة الله، حتى لا يفهم أن الرخصة تشملها. وذكر المساجد يثبت مكان الاعتكاف ويقابل لباس الزوجية بخلوة العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص101–102، تحت البقرة: 187، في تخصيص المباشرة بحال الاعتكاف.","url":""}]},{"id":"s2-867","number":867,"surah":2,"verses":[187],"verseLabel":"البقرة: 187","question":"ما سرّ التعبير في قوله تعالى عن حدود الله: ﴿فَلَا تَقْرَبُوهَا﴾، دون أن يقال: «فلا تتجاوزوها»؟","answer":"نهى عن الاقتراب من مقدمات المحرم، لا عن الوقوع فيه فقط؛ لأن من دار عند الحد أوشك أن يتجاوزه. وفي أحكام الشهوة خصوصًا تكون الوقاية بإبعاد الخطوات المفضية إلى المخالفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص101–102، تحت البقرة: 187، في دلالة النهي عن القرب.","url":""}]},{"id":"s2-868","number":868,"surah":2,"verses":[188],"verseLabel":"البقرة: 188","question":"ما سرّ التعبير في قوله تعالى: ﴿وتدلوا بها إلى الحكام﴾ فصوّر المال كأنه دلو؟","answer":"استعار الإدلاء بالدلو لإلقاء الأموال أو الخصومات إلى الحكام طلبًا للحكم بها؛ فصور من يدفع الرشوة أو يقدم الحجة الباطلة كمن يدلي دلوه ليجتذب مال غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص106–117، تحت البقرة: 188.","url":""}]},{"id":"s2-869","number":869,"surah":2,"verses":[188],"verseLabel":"البقرة: 188","question":"ما سرّ التعبير عن أخذ المال بالباطل بقوله تعالى: ﴿لَا تَأْكُلُوا﴾؟","answer":"الأكل أشهر وجوه الانتفاع بالمال وأشدها اتصالًا بالنفس، فكني به عن الاستيلاء على أموال الناس بالباطل في أي وجه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص103–105، تحت البقرة: 188، في استعارة الأكل للأخذ.","url":""}]},{"id":"s2-870","number":870,"surah":2,"verses":[188],"verseLabel":"البقرة: 188","question":"ما سرّ التعبير في قوله تعالى: ﴿أَمْوَالَكُمْ﴾، مع أن المراد أموال غيركم؟","answer":"لأن أموال الجماعة بمنزلة مال واحد يتكافل الناس على حمايته، ولأن من أكل مال أخيه أباح للآخرين أن يفعلوا مثله بماله. فالضمير يبني حاجزًا أخلاقيًا: اعتداؤك على غيرك اعتداء على مجتمعك ونفسك.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص104–106، تحت البقرة: 188، في مقابلة الجمع بالجمع.","url":""}]},{"id":"s2-871","number":871,"surah":2,"verses":[188],"verseLabel":"البقرة: 188","question":"ما فائدة قوله: ﴿بَيْنَكُمْ﴾؟","answer":"يستحضر المال متداولًا داخل العلاقات والمعاملات، ويبين أن الباطل قد يقع بتواطؤ طرفين لا بسرقة منفردة فقط. فالحكم يحرس المساحة الواقعة بين الناس: العقود والخصومات والأمانات.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص104–106، تحت البقرة: 188، في ظرفية ﴿بينكم﴾.","url":""}]},{"id":"s2-872","number":872,"surah":2,"verses":[188],"verseLabel":"البقرة: 188","question":"ما سرّ التعبير في قوله تعالى: ﴿بِهَا﴾ في ﴿وَتُدْلُوا بِهَا إِلَى الْحُكَّامِ﴾؟","answer":"الباء تجعل الأموال أداة ووسيلة للوصول إلى الحكم الباطل؛ فالجريمة ليست في المال وحده، بل في استخدامه سلّمًا لتزييف العدل. وقد يعود الضمير إلى الخصومة المالية كلها بما يقدم فيها من حجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص107–109، تحت البقرة: 188، في دلالة الباء والضمير.","url":""}]},{"id":"s2-873","number":873,"surah":2,"verses":[188],"verseLabel":"البقرة: 188","question":"ما سرّ التعبير في قوله تعالى: ﴿لِتَأْكُلُوا فَرِيقًا مِنْ أَمْوَالِ النَّاسِ﴾؟","answer":"﴿فريقًا﴾ أي جزءًا وطائفة من الأموال؛ حتى الجزء المحصل بالحيلة داخل في الوعيد، فلا يصغره صاحبه. واللام تكشف الغاية الفاسدة من التقاضي: تحويل القضاء من إظهار الحق إلى وسيلة للأكل.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص109–111، تحت البقرة: 188، في التعليل ولفظ ﴿فريقًا﴾.","url":""}]},{"id":"s2-874","number":874,"surah":2,"verses":[188],"verseLabel":"البقرة: 188","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وَأَنْتُمْ تَعْلَمُونَ﴾؟","answer":"لأن من يستعين بالحاكم ليغطي الباطل قد يملك حكمًا ظاهريًا، لكنه يعلم في باطنه أن المال ليس حقه؛ فعلمه يجعل جرأته وإثمه أشد. وحكم القاضي لا يغير حقيقة يعرفها الخصم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص110–113، تحت البقرة: 188، في الحال المؤكدة وأثر العلم.","url":""}]},{"id":"s2-875","number":875,"surah":2,"verses":[189],"verseLabel":"البقرة: 189","question":"ما سرّ التعبير عن الهلال بالجمع في سؤالهم عن ﴿الْأَهِلَّةِ﴾؟","answer":"لأن الهلال يتجدد كل شهر وتختلف منازله وأحوال ظهوره، فجمع باعتبار تعدد الأهلة في الشهور.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص118، تحت البقرة: 189.","url":""}]},{"id":"s2-876","number":876,"surah":2,"verses":[189],"verseLabel":"البقرة: 189","question":"ما سرّ تخصيص الحج بالذكر بعد قوله تعالى: ﴿مَوَاقِيتُ لِلنَّاسِ﴾؟","answer":"لأنه من أعظم العبادات ارتباطًا بالشهور القمرية، فخص بعد العموم لعنايته ولأن الخطأ في وقته يخل بأدائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص120، تحت البقرة: 189.","url":""}]},{"id":"s2-877","number":877,"surah":2,"verses":[189],"verseLabel":"البقرة: 189","question":"ما سرّ جعل الأهلة مواقيت دون الشمس؟","answer":"تغير الهلال ظاهر يسهل أن يراه عامة الناس في كل مكان ويحدد أول الشهر، فلا يحتاج إلى حساب دقيق أو أداة خاصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص121، تحت البقرة: 189.","url":""}]},{"id":"s2-878","number":878,"surah":2,"verses":[189],"verseLabel":"البقرة: 189","question":"ما سرّ توجيه الجواب إلى وظيفة الأهلة: ﴿هِيَ مَوَاقِيتُ لِلنَّاسِ وَالْحَجِّ﴾ دون بيان كيفية تكوّنها؟","answer":"عدل الجواب إلى ما يحتاجه الناس وينفعهم: ضبط مواقيت عباداتهم ومعاملاتهم وحجهم، ولم يدخل بهم في وصف فلكي لا يتعلق بمقصود التكليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص114–122، تحت البقرة: 189، في الأسلوب الحكيم.","url":""}]},{"id":"s2-879","number":879,"surah":2,"verses":[189],"verseLabel":"البقرة: 189","question":"ما سرّ التعبير في قوله تعالى: ﴿قُلْ هِيَ مَوَاقِيتُ﴾، دون أن يقال: «فقل» كما يجيء كثيرًا بعد السؤال؟","answer":"حذف الفاء لأن الجواب لم يأت على نفس جهة سؤالهم المتوهمة، بل استأنف توجيههم إلى وظيفة الأهلة؛ فالفصل يشعر بأن القضية تحتاج تصحيحًا لا جوابًا سببيًا مباشرًا فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص115–117، تحت البقرة: 189، في العدول عن ﴿فقل﴾ إلى ﴿قل﴾.","url":""}]},{"id":"s2-880","number":880,"surah":2,"verses":[189],"verseLabel":"البقرة: 189","question":"ما سرّ وصف الأهلة بأنها ﴿مَوَاقِيتَ﴾ بصيغة الجمع؟","answer":"لأن الأهلة تضبط أوقاتًا كثيرة للعبادات والمعاملات والعدد والحج؛ فكل وقت مضبوط بها ميقات.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص116–119، تحت البقرة: 189، في الإيجاز والجمع في المواقيت.","url":""}]},{"id":"s2-881","number":881,"surah":2,"verses":[189],"verseLabel":"البقرة: 189","question":"ما علاقة قوله: ﴿وَلَيْسَ الْبِرُّ بِأَنْ تَأْتُوا الْبُيُوتَ مِنْ ظُهُورِهَا﴾ بسؤال الأهلة؟","answer":"الجامع تصحيح السؤال والعمل: كما وجّههم إلى النافع من سؤال الأهلة، أبطل عادة كانوا يعدونها برًا وهي دخول المحرم من ظهر البيت؛ فالبر امتثال الشرع لا التكلف والعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص120–125، تحت البقرة: 189، في مناسبة الجملة ودلالة الظهور.","url":""}]},{"id":"s2-882","number":882,"surah":2,"verses":[189],"verseLabel":"البقرة: 189","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَكِنَّ الْبِرَّ مَنِ اتَّقَى﴾، فجعل البر شخصًا؟","answer":"بالغ حتى جعل المتقي نفس البر، أو المعنى: بر من اتقى؛ فليست القيمة في حركة غريبة يؤديها الجسد، بل في إنسان لازمته التقوى وصارت له سجية. والصياغة تقابل التكلف الظاهر بالخلق الباطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص122–126، تحت البقرة: 189، في الإخبار بالموصول عن البر.","url":""}]},{"id":"s2-883","number":883,"surah":2,"verses":[189],"verseLabel":"البقرة: 189","question":"ما مناسبة الأمر بقوله تعالى: ﴿وَأْتُوا الْبُيُوتَ مِنْ أَبْوَابِهَا﴾ بعد نفي البر؟","answer":"لم يكتف بإبطال العادة، بل وضع السلوك الصحيح مكانها؛ فالدين لا يترك فراغًا بعد إزالة الوهم. والعبارة صارت أصلًا في مباشرة كل أمر من مدخله المشروع الواضح بدل الالتواء والتكلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص123–127، تحت البقرة: 189، في عطف الأمر على الخبر ذي معنى النهي.","url":""}]},{"id":"s2-884","number":884,"surah":2,"verses":[189],"verseLabel":"البقرة: 189","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وَاتَّقُوا اللَّهَ لَعَلَّكُمْ تُفْلِحُونَ﴾؟","answer":"ردّ ميزان البر كله إلى تقوى الله لا إلى عادات اخترعها الناس، وجعل الفلاح ثمرة اتباع حدوده في السؤال والعمل والشعائر. و﴿لعل﴾ تبقي القلب بين الرجاء والعمل، لا الاتكال على المظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص126–130، تحت البقرة: 189، في تعلق الفلاح بالتقوى.","url":""}]},{"id":"s2-885","number":885,"surah":2,"verses":[190],"verseLabel":"البقرة: 190","question":"ما دلالة تقديم ﴿فِي سَبِيلِ اللَّهِ﴾ في قوله تعالى: ﴿وَقَاتِلُوا فِي سَبِيلِ اللَّهِ الَّذِينَ يُقَاتِلُونَكُمْ﴾؟","answer":"قدم ﴿في سبيل الله﴾ لتقييد القتال من أوله بالإخلاص والغاية المشروعة، فلا يكون لعصبية أو غنيمة أو عدوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص135، تحت البقرة: 190.","url":""}]},{"id":"s2-886","number":886,"surah":2,"verses":[190],"verseLabel":"البقرة: 190","question":"ما مناسبة الانتقال من الأهلة والحج إلى الأمر بقوله تعالى: ﴿وَقَاتِلُوا فِي سَبِيلِ اللَّهِ﴾؟","answer":"الحج كان مظنة تعرض المسلمين لصد المشركين وقتالهم، فانتقل من مواقيته وأحكامه إلى تشريع القتال الذي يحمي العبادة والطريق إلى البيت.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص131–133، تحت البقرة: 190، في مناسبة العطف.","url":""}]},{"id":"s2-887","number":887,"surah":2,"verses":[190],"verseLabel":"البقرة: 190","question":"ما سرّ التعبير في قوله تعالى: ﴿الَّذِينَ يُقَاتِلُونَكُمْ﴾، دون أن يقال: «قاتلوا الكافرين»؟","answer":"قيد الأمر بمن باشر القتال أو تهيأ له ليجعل سبب المواجهة العدوان لا مجرد المخالفة في الدين، وليخرج من لا يقاتل كالنساء والصبيان والشيوخ. والموصول يعلق الحكم بالفعل الموجب له.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص132–135، تحت البقرة: 190، في دلالة الموصول والمفاعلة.","url":""}]},{"id":"s2-888","number":888,"surah":2,"verses":[190],"verseLabel":"البقرة: 190","question":"ما دلالة صيغة المفاعلة في قوله تعالى: ﴿يُقَاتِلُونَكُمْ﴾؟","answer":"المفاعلة تدل على وقوع القتال بين جانبين؛ فقيد الأمر بمن يباشر قتال المسلمين، ولم يجعله عدوانًا على من لا يقاتل.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص133–135، تحت البقرة: 190، في دلالة المفاعلة.","url":""}]},{"id":"s2-889","number":889,"surah":2,"verses":[190],"verseLabel":"البقرة: 190","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا تَعْتَدُوا﴾، ولم يذكر ما الذي لا يعتدون فيه؟","answer":"حذف المتعلق ليعم كل عدوان: البدء بغير المقاتل، وتجاوز الضرورة، والتمثيل والغدر وإفساد ما لا صلة له بالقتال. فالإطلاق يحاصر التجاوز في الأشخاص والوسائل والغايات معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص134–136، تحت البقرة: 190، في حذف متعلق الاعتداء.","url":""}]},{"id":"s2-890","number":890,"surah":2,"verses":[190],"verseLabel":"البقرة: 190","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّ اللَّهَ لَا يُحِبُّ الْمُعْتَدِينَ﴾، دون أن يقال: «يعاقب المعتدين»؟","answer":"نفي المحبة يقرر أن الاعتداء مبغوض في ذاته ولو ظن صاحبه أنه ينصر قضية حق؛ فلا يكفي شرف الغاية لتبرير الوسيلة. والتذييل المؤكد يضع المقاتل تحت رقابة أخلاقية في أشد لحظات القوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص135–136، تحت البقرة: 190، في نفي المحبة وتأكيد التذييل.","url":""}]},{"id":"s2-891","number":891,"surah":2,"verses":[191],"verseLabel":"البقرة: 191","question":"ما سرّ التعبير في قوله تعالى: ﴿والفتنة أشد من القتل﴾؟ وأي فتنة أشد من القتل؟","answer":"المراد اضطهاد المؤمن عن دينه والشرك والصد والإخراج، وهي تهدم الروح والجماعة وتستمر آثارها؛ لذلك كانت أشد من واقعة قتل محدودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص141–153، تحت البقرة: 191.","url":""}]},{"id":"s2-892","number":892,"surah":2,"verses":[5],"verseLabel":"البقرة: 191، النساء: 89 و91، التوبة: 5","question":"ما سرّ التعبير في قوله تعالى في البقرة: ﴿وَاقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ﴾، دون أن يقال: «حيث وجدتموهم» كما جاء في مواضع أخرى؟","answer":"﴿ثقفتموهم﴾ تدل على الظفر بهم والتمكن منهم بعد الطلب، فهي أخص من مجرد الوجود، وتناسب سياق المحاربين الذين يترصد بعضهم بعضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص355–357، تحت الأنفال في مبحث: ثقفتموهم ووجدتموهم وصادفتموهم، مع المقارنة بالبقرة: 191 والنساء والتوبة.","url":""}]},{"id":"s2-893","number":893,"surah":2,"verses":[191],"verseLabel":"البقرة: 191","question":"ما سرّ التعبير في قوله تعالى: ﴿وَاقْتُلُوهُمْ﴾ بعد أن قال في الآية السابقة: ﴿وَقَاتِلُوا﴾؟","answer":"القتال مفاعلة بين فريقين في المواجهة، أما القتل فإيقاع الفعل بالمحارب بعد الظفر به؛ فانتقل اللفظ بحسب اختلاف الحال.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص137–140، تحت البقرة: 191، في عطف القتل على القتال.","url":""}]},{"id":"s2-894","number":894,"surah":2,"verses":[191],"verseLabel":"البقرة: 191","question":"ما سرّ التعبير في قوله تعالى: ﴿وَأَخْرِجُوهُمْ مِنْ حَيْثُ أَخْرَجُوكُمْ﴾؟","answer":"جاء الجزاء من جنس فعلهم: أخرجوكم من وطنكم وصدّوكم، فردوا إلى الموضع نفسه بإنهاء سلطانهم المعتدي. وتكرار ﴿أخرج﴾ و﴿حيث﴾ يحقق المقابلة الدقيقة ويمنع تجاوز الجريمة إلى انتقام غير منضبط.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص141–144، تحت البقرة: 191، في المقابلة وعطف الإخراج.","url":""}]},{"id":"s2-895","number":895,"surah":2,"verses":[191],"verseLabel":"البقرة: 191","question":"ما سرّ تقديم قوله تعالى: ﴿وَأَخْرِجُوهُمْ مِنْ حَيْثُ أَخْرَجُوكُمْ﴾ على قوله: ﴿وَالْفِتْنَةُ أَشَدُّ مِنَ الْقَتْلِ﴾؟","answer":"ذكر إخراجهم مقابلةً بالمثل قبل بيان علته؛ ثم قرر أن فتنتهم للمؤمنين عن دينهم وإخراجهم من الحرم أشد من القتل الذي استنكروه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص143–146، تحت البقرة: 191، في تعليل الحكم بجملة الفتنة.","url":""}]},{"id":"s2-896","number":896,"surah":2,"verses":[191],"verseLabel":"البقرة: 191","question":"ما سرّ النهي عن القتال عند المسجد الحرام بعد الأمر العام بالقتال؟","answer":"لحرمة المسجد الحرام؛ فالأصل منع القتال عنده، ولا يباح إلا إذا ابتدؤوا المسلمين بالقتال فيه، فيكون الرد جزاءً لاعتدائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص146–149، تحت البقرة: 191، في تخصيص المسجد الحرام.","url":""}]},{"id":"s2-897","number":897,"surah":2,"verses":[191],"verseLabel":"البقرة: 191","question":"ما سرّ التعبير في قوله تعالى: ﴿حَتَّى يُقَاتِلُوكُمْ فِيهِ﴾ ثم ﴿فَإِنْ قَاتَلُوكُمْ فَاقْتُلُوهُمْ﴾؟","answer":"جعل ابتداء القتال في الحرم منهم شرطًا، فإن باشروا القتال زالت حرمتهم العملية وجاز قتل المعتدين؛ ففرّق بين بدء العدوان ودفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص147–150، تحت البقرة: 191، في الغاية والشرط والإيجاز.","url":""}]},{"id":"s2-898","number":898,"surah":2,"verses":[191],"verseLabel":"البقرة: 191","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿كَذَلِكَ جَزَاءُ الْكَافِرِينَ﴾؟","answer":"اسم الإشارة يلخص الجزاء السابق ويقرره قاعدة فيمن جمع الكفر والصد عن المسجد والقتال فيه؛ فالجزاء من جنس فعلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص149–150، تحت البقرة: 191، في بلاغة الفاصلة.","url":""}]},{"id":"s2-899","number":899,"surah":2,"verses":[192],"verseLabel":"البقرة: 192","question":"ما سرّ التعبير في قوله تعالى: ﴿فإن انتهوا﴾ بـ﴿إن﴾ لا ﴿إذا﴾؟","answer":"استعمل ﴿إن﴾ لأن انتهاءهم مع عنادهم غير محقق الوقوع، بخلاف ما يكثر أو يتوقع تحققه فيستعمل له ﴿إذا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص153، تحت البقرة: 192.","url":""}]},{"id":"s2-900","number":900,"surah":2,"verses":[192],"verseLabel":"البقرة: 192","question":"ما سرّ التعبير في قوله تعالى: ﴿فَإِنِ انْتَهَوْا﴾، ولم يذكر عمّا ينتهون؟","answer":"حذف المتعلق ليعم: فإن انتهوا عن الكفر والفتنة والقتال والصد بحسب ما يقتضيه السياق؛ فلا يقصر الانتهاء على فعل واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص151–153، تحت البقرة: 192، في إيجاز الحذف.","url":""}]},{"id":"s2-901","number":901,"surah":2,"verses":[192],"verseLabel":"البقرة: 192","question":"ما سرّ العدول عن جواب مباشر مثل «فاتركوهم» إلى قوله تعالى: ﴿فَإِنَّ اللَّهَ غَفُورٌ رَحِيمٌ﴾؟","answer":"وضع علة الكف عنهم موضع الجواب: إذا انتهوا قابلهم الله بالمغفرة والرحمة، والمؤمنون أولى أن يكفوا عمن قبل الله رجوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص152–154، تحت البقرة: 192، في حذف جواب الشرط والاكتفاء بالتعليل.","url":""}]},{"id":"s2-902","number":902,"surah":2,"verses":[192],"verseLabel":"البقرة: 192","question":"ما مناسبة اسمَي ﴿غَفُورٌ رَحِيمٌ﴾ بعد الحديث عن القتال؟","answer":"المغفرة تمحو ما سبق من كفر واعتداء عند الانتهاء، والرحمة تفتح لهم باب الإيمان والأمان بعد القتال؛ فالخاتمة ترغيب في الرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص153–154، تحت البقرة: 192، في مناسبة الخاتمة.","url":""}]},{"id":"s2-903","number":903,"surah":2,"verses":[193],"verseLabel":"البقرة: 193","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى لا تكون فتنة ويكون الدين لله﴾؟","answer":"الفتنة هنا الشرك وصد الناس عن الدين واضطهادهم بسببه؛ والغاية إزالة الإكراه والصد حتى تكون العبادة والطاعة لله لا لسلطان الفتنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص157–167، تحت البقرة: 193.","url":""}]},{"id":"s2-904","number":904,"surah":2,"verses":[39],"verseLabel":"البقرة: 193، الأنفال: 39","question":"ما سرّ اختلاف التعبير بين قوله تعالى في الأنفال: ﴿وَيَكُونَ الدِّينُ كُلُّهُ لِلَّهِ﴾ بزيادة ﴿كله﴾، وقوله تعالى في البقرة: ﴿وَيَكُونَ الدِّينُ لِلَّهِ﴾ دونها؟","answer":"زاد ﴿كله﴾ في الأنفال لأن سياقها أوسع في استئصال الفتنة وظهور الدين على الشرك كله، أما البقرة فالمقام في قتال من يقاتل عند الحرم حتى تزول فتنتهم؛ فناسب الإيجاز.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص153–154، تحت الأنفال: 39، في المقارنة بالبقرة: 193.","url":""}]},{"id":"s2-905","number":905,"surah":2,"verses":[193],"verseLabel":"البقرة: 193","question":"ما سرّ تكرار الأمر بقوله تعالى: ﴿وَقَاتِلُوهُمْ﴾ بعد أحكام القتال السابقة؟","answer":"كرر الأمر بعد بيان الغاية ليؤكد استمرار القتال المشروع حتى تزول الفتنة ويأمن الناس على الدين، لا لمجرد واقعة عابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص155–158، تحت البقرة: 193، في استئناف الأمر وبيان الغاية.","url":""}]},{"id":"s2-906","number":906,"surah":2,"verses":[193],"verseLabel":"البقرة: 193","question":"ما سرّ التعبير في قوله تعالى: ﴿حَتَّى لَا تَكُونَ فِتْنَةٌ﴾، دون أن يقال: «حتى تهلكوهم»؟","answer":"لأن الغاية إزالة الإكراه والاضطهاد لا إبادة الخصم؛ فإذا زالت الفتنة سقط سبب القتال. وتنكير ﴿فتنة﴾ في سياق النفي يعم أي نظام يصد الناس عن دينهم بالقوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص157–160، تحت البقرة: 193، في دلالة الغاية والنكرة في النفي.","url":""}]},{"id":"s2-907","number":907,"surah":2,"verses":[193],"verseLabel":"البقرة: 193","question":"ما سرّ عطف المثبت: ﴿وَيَكُونَ الدِّينُ لِلَّهِ﴾ على المنفي: ﴿لَا تَكُونَ فِتْنَةٌ﴾؟","answer":"جمع بين إزالة الباطل وإثبات الحق: تزول الفتنة التي تصد عن الدين، ويخلص سلطان العبادة والطاعة لله؛ فلا يكفي نفي الفساد من غير إقامة المقصود.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص159–162، تحت البقرة: 193، في عطف المثبت على المنفي.","url":""}]},{"id":"s2-908","number":908,"surah":2,"verses":[193],"verseLabel":"البقرة: 193","question":"ما سرّ التعبير في قوله تعالى: ﴿وَيَكُونَ الدِّينُ لِلَّهِ﴾، دون أن يقال: «ويؤمنوا كلهم»؟","answer":"علق الغاية بسيادة عبادة الله وزوال الفتنة، لا بإكراه كل فرد على الإيمان؛ فالإيمان القلبي لا يصنعه السيف. اللام تفيد إخلاص الدين لله وعدم خضوعه لسلطة تصرف الناس عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص160–163، تحت البقرة: 193، في دلالة اللام ومعنى الدين لله.","url":""}]},{"id":"s2-909","number":909,"surah":2,"verses":[193],"verseLabel":"البقرة: 193","question":"ما سرّ التعبير في قوله تعالى: ﴿فَلَا عُدْوَانَ إِلَّا عَلَى الظَّالِمِينَ﴾، وسمّى العقوبة عدوانًا؟","answer":"سمّى جزاء الظالمين عدوانًا من باب المشاكلة ومقابلة اللفظ باللفظ؛ فهو في الحقيقة عقوبة عادلة لا ظلم فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص162–164، تحت البقرة: 193، في القصر والمشاكلة.","url":""}]},{"id":"s2-910","number":910,"surah":2,"verses":[194],"verseLabel":"البقرة: 194","question":"ما دلالة تقييد الرد بقوله تعالى: ﴿بِمِثْلِ مَا اعْتَدَى عَلَيْكُمْ﴾؟","answer":"قيد الرد بالمثل لمنع تجاوز الحق تحت حرارة الانتقام؛ فالمأذون فيه دفع العدوان بقدره لا ابتداء ظلم جديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص173، تحت البقرة: 194.","url":""}]},{"id":"s2-911","number":911,"surah":2,"verses":[194],"verseLabel":"البقرة: 194","question":"ما سرّ التعبير في قوله تعالى: ﴿الشَّهْرُ الْحَرَامُ بِالشَّهْرِ الْحَرَامِ﴾ وكرر اللفظ نفسه؟","answer":"ليقرر المماثلة الدقيقة: انتهاكهم حرمة الشهر يقابل في الشهر الحرام بقدر الضرورة، فلا يحول احترامه دون ردهم إذا بدؤوا. والتكرار يجعل كفتي القصاص متطابقتين لفظًا ومعنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص165–168، تحت البقرة: 194، في المقابلة وتكرار الشهر الحرام.","url":""}]},{"id":"s2-912","number":912,"surah":2,"verses":[194],"verseLabel":"البقرة: 194","question":"ما سرّ إفراد ﴿الشَّهْرُ الْحَرَامُ﴾ ثم جمع ﴿وَالْحُرُمَاتُ قِصَاصٌ﴾؟","answer":"ذكر الشهر الحرام أولًا لأنه سبب الواقعة المعينة، ثم عمم الحكم في جميع الحرمات: لكل حرمة قصاص إذا انتهكها المعتدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص167–170، تحت البقرة: 194، في إيثار الجمع والتعميم.","url":""}]},{"id":"s2-913","number":913,"surah":2,"verses":[194],"verseLabel":"البقرة: 194","question":"ما سرّ التعبير في قوله تعالى: ﴿وَالْحُرُمَاتُ قِصَاصٌ﴾، دون أن يقال: «تعظَّم الحرمات»؟","answer":"لأن المقام فيمن انتهك الحرمة متذرعًا بها، فبيّن أن صيانتها لا تعني ترك المعتدي، بل يقابل انتهاكه بمثله دون زيادة. لفظ القصاص يجمع الحماية والعدل في قاعدة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص168–171، تحت البقرة: 194، في الإخبار بالمصدر.","url":""}]},{"id":"s2-914","number":914,"surah":2,"verses":[194],"verseLabel":"البقرة: 194","question":"ما سرّ التعبير في قوله تعالى: ﴿فَمَنِ اعْتَدَى عَلَيْكُمْ فَاعْتَدُوا عَلَيْهِ﴾، مع أن رد الاعتداء ليس اعتداءً مذمومًا؟","answer":"سمي الرد اعتداء من باب المشاكلة؛ لأنه في صورة فعل المعتدي ومقابل له، لكنه مقيد بالمثل، فليس عدوانًا مذمومًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص170–173، تحت البقرة: 194، في المشاكلة.","url":""}]},{"id":"s2-915","number":915,"surah":2,"verses":[194],"verseLabel":"البقرة: 194","question":"ما مناسبة الأمر بالتقوى بعد الإذن برد الاعتداء؟","answer":"لأن الإذن بالرد مظنة مجاوزة الحد بدافع الغضب، فجاء الأمر بالتقوى حارسًا للمماثلة والعدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص173–175، تحت البقرة: 194، في مناسبة الأمر بالتقوى.","url":""}]},{"id":"s2-916","number":916,"surah":2,"verses":[194],"verseLabel":"البقرة: 194","question":"ما سرّ التعبير في قوله تعالى: ﴿وَاعْلَمُوا أَنَّ اللَّهَ مَعَ الْمُتَّقِينَ﴾؟","answer":"وعدهم بالنصر والتأييد ما داموا داخل حدود التقوى، لا لمجرد أنهم في جانب المؤمنين؛ فالمعية مشروطة بالسلوك العادل. وهذا يطمئن المظلوم ويحذره في وقت واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص174–176، تحت البقرة: 194، في الأمر بالعلم والمعية.","url":""}]},{"id":"s2-917","number":917,"surah":2,"verses":[194],"verseLabel":"البقرة: 194","question":"ما مناسبة ختم الآية بـ﴿الْمُتَّقِينَ﴾ دون «المنتصرين» أو «المقاتلين»؟","answer":"لأن قيمة القتال والقصاص في انضباطهما بأمر الله، وأقرب الناس إلى معيته من يكف نفسه عند الحد. فالخاتمة تعيد مركز الثقل من القوة الظاهرة إلى الرقابة الأخلاقية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص175–176، تحت البقرة: 194، في مناسبة الفاصلة.","url":""}]},{"id":"s2-918","number":918,"surah":2,"verses":[195],"verseLabel":"البقرة: 195","question":"ما سرّ الجمع بين الأمر بالإنفاق والنهي عن إلقاء النفس في التهلكة؟","answer":"الإنفاق عدة الجهاد وسبب قوة الأمة؛ وتركه يفضي إلى ضعفها وهلاكها. لذلك اتصل الأمر به بالنهي عن التهلكة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص174–193، تحت البقرة: 195.","url":""}]},{"id":"s2-919","number":919,"surah":2,"verses":[195],"verseLabel":"البقرة: 195","question":"ما مناسبة الأمر بالإنفاق بعد آيات القتال؟","answer":"لأن القتال لا يقوم بلا إعداد وإنفاق، فجاء تمويله بعد بيان أحكامه وغاياته.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص177–180، تحت البقرة: 195، في مناسبة الأمر بالإنفاق.","url":""}]},{"id":"s2-920","number":920,"surah":2,"verses":[195],"verseLabel":"البقرة: 195","question":"ما دلالة تقييد الإنفاق بقوله تعالى: ﴿فِي سَبِيلِ اللَّهِ﴾؟","answer":"حتى يكون البذل خالصًا لنصرة الحق ومصالحه، لا للسمعة والعصبية والسيطرة. و﴿في﴾ تصور المال واقعًا داخل طريق الله ومتجهًا إلى غايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص179–181، تحت البقرة: 195، في دلالة ﴿في سبيل الله﴾.","url":""}]},{"id":"s2-921","number":921,"surah":2,"verses":[195],"verseLabel":"البقرة: 195","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا تُلْقُوا بِأَيْدِيكُمْ إِلَى التَّهْلُكَةِ﴾، مع أن الإنسان يلقي نفسه لا يده فقط؟","answer":"ذكرت الأيدي لأنها آلة الإلقاء والمباشرة غالبًا، وأضيف الفعل إليها تصويرًا للإنسان وهو يصنع أسباب هلاكه بنفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص180–183، تحت البقرة: 195، في الصورة ودلالة الأيدي.","url":""}]},{"id":"s2-922","number":922,"surah":2,"verses":[195],"verseLabel":"البقرة: 195","question":"ما المراد بالتهلكة في قوله تعالى: ﴿وَلَا تُلْقُوا بِأَيْدِيكُمْ إِلَى التَّهْلُكَةِ﴾؟","answer":"اللفظ عام في كل سبب يؤدي إلى الهلاك، ويدخل فيه ترك الإنفاق والجهاد حتى يسلط العدو، كما يدخل فيه الإقدام غير المنضبط على الضرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص181–184، تحت البقرة: 195، في إطلاق التهلكة وعلاقتها بالسياق.","url":""}]},{"id":"s2-923","number":923,"surah":2,"verses":[195],"verseLabel":"البقرة: 195","question":"ما مناسبة الأمر بالإحسان بعد النهي عن التهلكة؟","answer":"الإحسان مرتبة زائدة على مجرد ترك الهلاك؛ فبعد النهي عن التقصير أمر بإتقان الإنفاق والعمل وأدائهما على الوجه الحسن.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص183–185، تحت البقرة: 195، في موقع الأمر بالإحسان.","url":""}]},{"id":"s2-924","number":924,"surah":2,"verses":[195],"verseLabel":"البقرة: 195","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿إِنَّ اللَّهَ يُحِبُّ الْمُحْسِنِينَ﴾؟","answer":"بعد أن نفى محبته للمعتدين في الآية 190 أثبت هنا محبته للمحسنين، فبين طرفي الطريق: لا تجاوز ولا تقصير، بل إحسان. والتعبير بالمحبة يجعل الدافع أعلى من مجرد النجاة من العقاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص184–185، تحت البقرة: 195، في تعليل الأمر بالمحبة.","url":""}]},{"id":"s2-925","number":925,"surah":2,"verses":[196],"verseLabel":"البقرة: 196","question":"ما سرّ التعبير في قوله تعالى: ﴿فإن أحصرتم﴾ بـ﴿إن﴾، ثم قال ﴿فإذا أمنتم﴾ بـ﴿إذا﴾؟","answer":"جاء الإحصار بـ﴿إن﴾ لأنه عارض غير محقق، وجاء الأمن بـ﴿إذا﴾ لأنه الأصل الغالب المتوقع بعد زوال العارض.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص193–198، تحت البقرة: 196.","url":""}]},{"id":"s2-926","number":926,"surah":2,"verses":[196],"verseLabel":"البقرة: 196","question":"ما سرّ التعبير في قوله تعالى: ﴿وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ﴾، دون أن يقال: «حجوا واعتمروا»؟","answer":"ركز على إكمال العبادة بعد الدخول فيها وألا تقطع أو تفسد، لأن السياق سيفصل موانع الإتمام وجبرها. و﴿لله﴾ تصحح النية: إتمام المناسك تعبّد خالص لا عادة أو مفاخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص186–191، تحت البقرة: 196، في اختيار الإتمام والتقييد لله.","url":""}]},{"id":"s2-927","number":927,"surah":2,"verses":[196],"verseLabel":"البقرة: 196","question":"ما سرّ الجمع بين الحج والعمرة في أمر واحد؟","answer":"لاشتراكهما في الإحرام وكثير من الأعمال واحتمال الإحصار، مع اختلاف مرتبتهما؛ فجمعهما في وجوب الوفاء بما بدأه العبد. والعطف يرفع توهم أن العمرة أخف شأنًا حتى يجوز إفسادها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص188–192، تحت البقرة: 196، في عطف العمرة على الحج.","url":""}]},{"id":"s2-928","number":928,"surah":2,"verses":[196],"verseLabel":"البقرة: 196","question":"ما سرّ التعبير في قوله تعالى: ﴿فَإِنْ أُحْصِرْتُمْ﴾ بالبناء للمجهول؟","answer":"ليعم كل مانع يحبس المحرم عن إتمام نسكه: عدو أو مرض أو عارض قاهر، دون حصر الحكم في فاعل معين. موضع العناية هو وقوع الحبس وآثاره لا اسم من سببه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص191–195، تحت البقرة: 196، في بناء الإحصار والإيجاز.","url":""}]},{"id":"s2-929","number":929,"surah":2,"verses":[196],"verseLabel":"البقرة: 196","question":"ما سرّ التعبير في قوله تعالى: ﴿فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ﴾، ولم يحدد نوعًا واحدًا؟","answer":"راعى تفاوت القدرة، فأوجب ما تيسر من بهيمة الأنعام ضمن الحد الشرعي، لا ما يعجز عنه المحصر. والموصول يجعل اليسر جزءًا من صياغة التكليف نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص193–196، تحت البقرة: 196، في ﴿ما استيسر﴾ وتعريف الهدي.","url":""}]},{"id":"s2-930","number":930,"surah":2,"verses":[196],"verseLabel":"البقرة: 196","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا تَحْلِقُوا رُءُوسَكُمْ حَتَّى يَبْلُغَ الْهَدْيُ مَحِلَّهُ﴾؟","answer":"جعل بلوغ الهدي موضع حلّه علامة انتهاء حكم الإحرام في حال الإحصار؛ فلا يتحلل المحرم بهواه قبل أن يؤدي جبر النسك. وذكر الرؤوس لأن الحلق أبرز شعائر التحلل.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص195–198، تحت البقرة: 196، في الغاية وذكر الرؤوس.","url":""}]},{"id":"s2-931","number":931,"surah":2,"verses":[196],"verseLabel":"البقرة: 196","question":"ما سرّ التعبير في قوله تعالى: ﴿أَوْ بِهِ أَذًى مِنْ رَأْسِهِ﴾، دون أن يقال: «أو يؤذيه رأسه»؟","answer":"قدّم الجار والمجرور لتصوير الأذى ملازمًا للمحرم، ثم حدد مصدره بالرأس كالقمل أو الجرح الذي يضطره للحلق. والعبارة تفصل بين مجرد الرغبة والحاجة الطبية المعتبرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص197–199، تحت البقرة: 196، في بناء وصف الأذى.","url":""}]},{"id":"s2-932","number":932,"surah":2,"verses":[196],"verseLabel":"البقرة: 196","question":"ما سرّ تنويع الفدية بين ﴿صِيَامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍ﴾؟","answer":"نوّع الفدية تيسيرًا بحسب أحوال المكلفين: عبادة بدنية بالصيام، ومالية بالصدقة، ونسك بالذبح؛ فيختار ما يقدر عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص198–201، تحت البقرة: 196، في تقسيم الفدية.","url":""}]},{"id":"s2-933","number":933,"surah":2,"verses":[196],"verseLabel":"البقرة: 196","question":"ما سرّ التعبير بقوله تعالى: ﴿فَإِذَا أَمِنْتُمْ﴾ بعد الإحصار، مع حذف متعلق الأمن؟","answer":"حذف متعلق الأمن ليعم الأمن من العدو والمرض وسائر أسباب الإحصار؛ فإذا زال المانع عاد الحاج إلى حكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص200–202، تحت البقرة: 196، في الحذف واستعمال ﴿إذا﴾.","url":""}]},{"id":"s2-934","number":934,"surah":2,"verses":[196],"verseLabel":"البقرة: 196","question":"ما سرّ تسمية الجمع بين العمرة والحج تمتعًا؟","answer":"لأنه ينتفع بإسقاط أحد السفرين، ويتمتع بما كان ممنوعًا عليه بالإحرام بين العمرة والحج.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص201–204، تحت البقرة: 196، في معنى التمتع وتعديته.","url":""}]},{"id":"s2-935","number":935,"surah":2,"verses":[196],"verseLabel":"البقرة: 196","question":"ما سرّ التعبير في قوله تعالى: ﴿فَمَنْ لَمْ يَجِدْ﴾ دون أن يذكر ما لم يجده؟","answer":"دل الهدي السابق عليه، فحذف اختصارًا؛ ويشمل عدم وجود الهدي أو ثمنه والقدرة عليه. فانتقل من البدل المالي إلى الصوم من غير تكرار يثقل الآية الطويلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص202–204، تحت البقرة: 196، في حذف مفعول الوجدان.","url":""}]},{"id":"s2-936","number":936,"surah":2,"verses":[196],"verseLabel":"البقرة: 196","question":"ما سرّ تقسيم الصيام إلى ثلاثة أيام في الحج وسبعة عند الرجوع؟","answer":"ليقع بعض الجبر داخل زمن النسك فيبقى متصلًا به، ويؤخر الأكثر إلى زمن السعة بعد الرجوع. والتقسيم يخفف المشقة في السفر مع استكمال بدل الهدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص203–206، تحت البقرة: 196، في توزيع الأيام والالتفات إلى الخطاب.","url":""}]},{"id":"s2-937","number":937,"surah":2,"verses":[196],"verseLabel":"البقرة: 196","question":"ما فائدة قوله: ﴿تِلْكَ عَشَرَةٌ كَامِلَةٌ﴾ بعد ذكر ثلاثة وسبعة؟","answer":"جمع الأعداد وصرح بكمال العشرة دفعًا لتوهم أن الواو للتخيير، وتأكيدًا لاستيفائها، وتنبيهًا إلى كمال الأجر والحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص204–207، تحت البقرة: 196، في التذييل بالعدد الكامل.","url":""}]},{"id":"s2-938","number":938,"surah":2,"verses":[196],"verseLabel":"البقرة: 196","question":"ما سرّ تخصيص حكم التمتع بمن لم يكن أهله حاضري المسجد الحرام؟","answer":"لأن البعيد يجمع النسكين في سفر واحد ويتمتع بالتحلل بينهما، بخلاف من كان أهله قريبين من الحرم فلا تتحقق في حقه المشقة والصورة نفسها. والتعبير بالأهل يراعي موطن الاستقرار لا وجود الشخص العابر فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص205–207، تحت البقرة: 196، في قيد حاضري المسجد الحرام.","url":""}]},{"id":"s2-939","number":939,"surah":2,"verses":[196],"verseLabel":"البقرة: 196","question":"ما مناسبة ختم تفصيلات الحج بقوله تعالى: ﴿وَاتَّقُوا اللَّهَ وَاعْلَمُوا أَنَّ اللَّهَ شَدِيدُ الْعِقَابِ﴾؟","answer":"كثرة تفاصيل النسك مظنة المخالفة أو التحايل، فجمعها بالتقوى ومراقبة شدة العقاب؛ حتى لا تتحول الشعيرة إلى صورة بلا امتثال.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص206–207، تحت البقرة: 196، في مناسبة الأمر بالتقوى والوعيد.","url":""}]},{"id":"s2-940","number":940,"surah":2,"verses":[197],"verseLabel":"البقرة: 197","question":"ما سرّ التعبير في قوله تعالى: ﴿الحج أشهر معلومات﴾، دون أن يقال: حج البيت في أشهر معلومات؟","answer":"حذف المضاف والظرف ليجعل الصلة شديدة، كأن الحج نفسه هو هذه الأشهر؛ فيبرز أن الإحرام والمناسك مقيدة بزمن معلوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص211، تحت البقرة: 197.","url":""}]},{"id":"s2-941","number":941,"surah":2,"verses":[197],"verseLabel":"البقرة: 197","question":"ما سرّ ترتيب الرفث والفسوق والجدال؟","answer":"الرفث ما يتصل بالشهوة، والفسوق خروج عن الطاعة، والجدال خصومة مع الآخرين؛ فانتقل من فساد يتعلق بالنفس إلى المعصية ثم إلى ما يفسد الصحبة والمجتمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص211–222، تحت البقرة: 197.","url":""}]},{"id":"s2-942","number":942,"surah":2,"verses":[197],"verseLabel":"البقرة: 197","question":"ما سرّ التعبير في قوله تعالى: ﴿الْحَجُّ أَشْهُرٌ مَعْلُومَاتٌ﴾، مع أن أعمال الحج الكبرى في أيام؟","answer":"أطلق الحج على زمنه مبالغة، أو التقدير: وقت الحج أشهر معلومات؛ والمراد بيان الزمن الذي يصح فيه الإحرام، وإن وقعت الأعمال الكبرى في أيام معلومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص208–212، تحت البقرة: 197، في الإخبار بالأشهر.","url":""}]},{"id":"s2-943","number":943,"surah":2,"verses":[197],"verseLabel":"البقرة: 197","question":"ما دلالة وصف أشهر الحج بأنها ﴿مَعْلُومَاتٌ﴾؟","answer":"لأنها مستقرة معروفة عند العرب من شريعة إبراهيم، فلا تحتاج إلى تعداد في هذا المقام؛ وفي الوصف حجة على من يعبث بتوقيتها. ما كان معلومًا يُبنى عليه الحكم مباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص210–213، تحت البقرة: 197، في وصف الأشهر بالمعلومات.","url":""}]},{"id":"s2-944","number":944,"surah":2,"verses":[197],"verseLabel":"البقرة: 197","question":"ما معنى فرض الإنسان الحج في قوله تعالى: ﴿فَمَنْ فَرَضَ فِيهِنَّ الْحَجَّ﴾؟","answer":"فرض الحج أي أوجبه على نفسه بالدخول في الإحرام والنية؛ فإذا أحرم لزمته أحكام النسك ومحظوراته.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص212–215، تحت البقرة: 197، في إسناد الفرض إلى المحرم.","url":""}]},{"id":"s2-945","number":945,"surah":2,"verses":[197],"verseLabel":"البقرة: 197","question":"ما سرّ التعبير في قوله تعالى: ﴿فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِي الْحَجِّ﴾؟","answer":"جاء النفي بـ﴿لا﴾ مكررًا لنفي كل واحد من الرفث والفسوق والجدال استقلالًا، وتشديد تنزيه الحج عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص214–219، تحت البقرة: 197، في الجمع بين المنهيات وترتيبها.","url":""}]},{"id":"s2-946","number":946,"surah":2,"verses":[197],"verseLabel":"البقرة: 197","question":"ما سرّ التعبير في قوله تعالى: ﴿فِي الْحَجِّ﴾ بعد المنهيات، وهي ممنوعة في غيره أيضًا؟","answer":"لأن قبحها يشتد في العبادة والزمان والمكان الشريف، ولأن الحج موطن ازدحام ومشقة تتعرض فيه النفوس للجدال. القيد ليس لإباحتها خارجه، بل لتغليظ اجتنابها داخله.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص217–220، تحت البقرة: 197، في قيد الظرف.","url":""}]},{"id":"s2-947","number":947,"surah":2,"verses":[197],"verseLabel":"البقرة: 197","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا تَفْعَلُوا مِنْ خَيْرٍ يَعْلَمْهُ اللَّهُ﴾ بعد النهي؟","answer":"لم يترك الحاج في فراغ سلبي بعد الكف عن الرفث والفسوق والجدال، بل فتح له كل أبواب الخير. وعلم الله هنا وعد بالحفظ والجزاء، وحذف التفصيل ليعم صغير العمل وكبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص219–222، تحت البقرة: 197، في الانتقال من النهي إلى الخير.","url":""}]},{"id":"s2-948","number":948,"surah":2,"verses":[197],"verseLabel":"البقرة: 197","question":"ما سرّ التعبير في قوله تعالى: ﴿وَتَزَوَّدُوا فَإِنَّ خَيْرَ الزَّادِ التَّقْوَى﴾؟","answer":"أمرهم بالزاد الحسي الذي يحفظهم في السفر، ثم نبه إلى الزاد الباقي وهو التقوى؛ فكما لا يستغني المسافر عن طعامه لا يستغني السائر إلى الله عن التقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص220–225، تحت البقرة: 197، في التمثيل بالزاد.","url":""}]},{"id":"s2-949","number":949,"surah":2,"verses":[197],"verseLabel":"البقرة: 197","question":"ما مناسبة تخصيص النداء بقوله تعالى: ﴿وَاتَّقُونِ يَا أُولِي الْأَلْبَابِ﴾؟","answer":"لأن أصحاب العقول الخالصة يدركون أن المظاهر والمناسك لا تنفع بلا تقوى، وأن المسافر الحقيقي يحتاج إلى زاد الآخرة. وحذف ياء المتكلم في ﴿اتقون﴾ يوافق خفة الفاصلة مع بقاء قرب الخطاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص223–226، تحت البقرة: 197، في نداء أولي الألباب.","url":""}]},{"id":"s2-950","number":950,"surah":2,"verses":[198],"verseLabel":"البقرة: 198","question":"ما سرّ الكناية عن التجارة بقوله تعالى: ﴿تَبْتَغُوا فَضْلًا مِنْ رَبِّكُمْ﴾؟","answer":"سمى الربح والتجارة فضلًا من الله؛ ليقرر أن الرزق عطية منه لا ثمرة الحيلة وحدها، وليهذب قصد التجارة في موسم العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص230–232، تحت البقرة: 198.","url":""}]},{"id":"s2-951","number":951,"surah":2,"verses":[198],"verseLabel":"البقرة: 198","question":"ما سرّ نفي الجناح عن ابتغاء فضل الله في الحج، والتعبير بذلك بدل الأمر بالتجارة؟","answer":"نفي الجناح يرفع حرجًا كان عندهم من التجارة في الحج، والتعبير بابتغاء فضل الله يبيح الكسب مع ربطه بالمنعم، من غير أن يجعل التجارة مقصد الحج.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص227–231، تحت البقرة: 198، في نفي الجناح والكناية عن التجارة.","url":""}]},{"id":"s2-952","number":952,"surah":2,"verses":[198],"verseLabel":"البقرة: 198","question":"ما دلالة إضافة الفضل إلى الرب في قوله تعالى: ﴿فَضْلًا مِنْ رَبِّكُمْ﴾؟","answer":"إضافة الفضل إلى الرب تستحضر الرعاية والتربية والرزق، وتمنع أن ينسب الحاج كسبه إلى أسباب التجارة وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص230–233، تحت البقرة: 198، في دلالة الإضافة.","url":""}]},{"id":"s2-953","number":953,"surah":2,"verses":[198],"verseLabel":"البقرة: 198","question":"ما سرّ التعبير في قوله تعالى: ﴿فَإِذَا أَفَضْتُمْ مِنْ عَرَفَاتٍ﴾، دون أن يقال: «خرجتم»؟","answer":"الإفاضة اندفاع الجماعة الكثيرة كفيض الماء؛ فصورت حركة الحجيج من عرفات مجتمعين في سيل بشري.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص232–235، تحت البقرة: 198، في استعارة الإفاضة.","url":""}]},{"id":"s2-954","number":954,"surah":2,"verses":[198],"verseLabel":"البقرة: 198","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ عَرَفَاتٍ﴾ بصيغة الجمع؟","answer":"﴿عرفات﴾ علم للمكان جاء بصيغة الجمع، ويجوز أن يلحظ تعدد بقاعه ومواقفه، مع بقاء المراد الموضع المعروف.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص233–236، تحت البقرة: 198، في صيغة عرفات.","url":""}]},{"id":"s2-955","number":955,"surah":2,"verses":[198],"verseLabel":"البقرة: 198","question":"ما مناسبة الأمر بالذكر عند المشعر الحرام؟","answer":"بعد حركة الإفاضة يثبت القلب بالذكر في موضع يشعر بحرمة الله وعلامات دينه؛ فلا تتحول المناسك إلى انتقال جسدي فقط. وتحديد المكان يربط الزمن والمشهد بالتوحيد والشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص235–237، تحت البقرة: 198، في مناسبة الذكر بالمشعر.","url":""}]},{"id":"s2-956","number":956,"surah":2,"verses":[198],"verseLabel":"البقرة: 198","question":"ما سرّ تكرار الأمر بالذكر في قوله: ﴿وَاذْكُرُوهُ كَمَا هَدَاكُمْ﴾ بعد ﴿فَاذْكُرُوا اللَّهَ﴾؟","answer":"الأمر الأول أصل الذكر عند المشعر، والثاني يحدد صفته وسببه: اذكروه ذكرًا يليق بهدايته لكم بعد الضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص236–238، تحت البقرة: 198، في تكرار الذكر.","url":""}]},{"id":"s2-957","number":957,"surah":2,"verses":[198],"verseLabel":"البقرة: 198","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِنْ كُنْتُمْ مِنْ قَبْلِهِ لَمِنَ الضَّالِّينَ﴾؟","answer":"ذكّرهم بحالهم قبل القرآن أو قبل الهدى حتى يعرفوا مقدار النعمة التي تستوجب الذكر؛ فالهداية تظهر قيمتها بمقابلة الضلال السابق. وتوالي ﴿إن﴾ واللام و﴿من﴾ يقوي تقرير حال لا ينبغي نسيانها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص237–238، تحت البقرة: 198، في التوكيد ومقابلة الهداية بالضلال.","url":""}]},{"id":"s2-958","number":958,"surah":2,"verses":[199],"verseLabel":"البقرة: 199","question":"ما سرّ الأمر بالإفاضة من حيث أفاض الناس؟","answer":"أمر قريشًا ومن كان يقف بالمزدلفة ترفعًا أن يقفوا بعرفات ويفيضوا مع الناس؛ فالدين يسوي بينهم ويبطل امتياز الجاهلية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص235–246، تحت البقرة: 199.","url":""}]},{"id":"s2-959","number":959,"surah":2,"verses":[199],"verseLabel":"البقرة: 199","question":"ما سرّ التعبير في قوله تعالى: ﴿ثُمَّ أَفِيضُوا مِنْ حَيْثُ أَفَاضَ النَّاسُ﴾ بعد ذكر الإفاضة من عرفات؟","answer":"الأمر بالإفاضة من حيث أفاض الناس تصحيح لموقف من كان لا يقف بعرفات، و﴿ثم﴾ للانتقال في الرتبة أو لترتيب الذكر، لا يلزم منها أن الإفاضة الثانية بعد الأولى زمنًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص239–241، تحت البقرة: 199، في العطف بـ﴿ثم﴾.","url":""}]},{"id":"s2-960","number":960,"surah":2,"verses":[199],"verseLabel":"البقرة: 199","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ حَيْثُ أَفَاضَ النَّاسُ﴾، ولم يسمِّ عرفات؟","answer":"لأن المقصود كسر الاستعلاء والعودة إلى جماعة الحجيج؛ فلفظ ﴿الناس﴾ هو الحجة الأخلاقية: أنتم منهم لا طبقة فوقهم. ودل السياق على المكان دون حاجة إلى تكراره.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص240–242، تحت البقرة: 199، في التعبير بالناس والحذف.","url":""}]},{"id":"s2-961","number":961,"surah":2,"verses":[199],"verseLabel":"البقرة: 199","question":"ما مناسبة إتباع الإفاضة بالأمر بالاستغفار؟","answer":"لأن العبادة مهما عظمت لا تخلو من تقصير، ولأنهم كانوا يصححون عادة جاهلية؛ فأمروا بالاستغفار بعد النسك تواضعًا وجبرًا للنقص.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص241–242، تحت البقرة: 199، في مناسبة الاستغفار.","url":""}]},{"id":"s2-962","number":962,"surah":2,"verses":[199],"verseLabel":"البقرة: 199","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿إِنَّ اللَّهَ غَفُورٌ رَحِيمٌ﴾؟","answer":"وعد بالغفران لما يستغفرون منه، والرحمة بقبولهم وإصلاح مناسكهم بعد الخطأ. وجاءت الصيغتان الدالتان على الثبات لتفتحا باب الرجوع عقب الأمر المباشر بالاستغفار.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص241–242، تحت البقرة: 199، في مناسبة الخاتمة.","url":""}]},{"id":"s2-963","number":963,"surah":2,"verses":[200],"verseLabel":"البقرة: 200","question":"ما سرّ التعبير في قوله تعالى: ﴿فاذكروا الله كذكركم آباءكم أو أشد ذكرًا﴾؟","answer":"كان العرب يذكرون مفاخر آبائهم بعد الحج، فأمروا أن يستبدلوا بذلك ذكر الله، أو يزيدوا عليه في القوة؛ لأنه صاحب النعم والهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص235–246، تحت البقرة: 200.","url":""}]},{"id":"s2-964","number":964,"surah":2,"verses":[200,201],"verseLabel":"البقرة: 200–201","question":"ما سرّ المقابلة بين دعاء طالب الدنيا وحدها ودعاء طالب حسنتي الدنيا والآخرة؟","answer":"الأول حصر همّه في الدنيا فحرم نصيب الآخرة، والثاني جمع خير الدارين وطلب الوقاية من النار؛ فالمقابلة تعلم شمول الدعاء واتزان المقصد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص235–246، تحت البقرة: 200–201.","url":""}]},{"id":"s2-965","number":965,"surah":2,"verses":[200],"verseLabel":"البقرة: 200","question":"ما سرّ التعبير في قوله تعالى: ﴿فَإِذَا قَضَيْتُمْ مَنَاسِكَكُمْ فَاذْكُرُوا اللَّهَ﴾؟","answer":"انتهاء أعمال الحج لا يعني انتهاء الصلة بالله؛ بل ينتقل الحاج من حركة المناسك إلى دوام الذكر. والفاء تجعل الذكر أول ما يعقب الفراغ حتى لا تملأ المفاخرة واللغو المساحة التي تركتها العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص243–246، تحت البقرة: 200، في التعقيب بعد قضاء المناسك.","url":""}]},{"id":"s2-966","number":966,"surah":2,"verses":[200],"verseLabel":"البقرة: 200","question":"ما سرّ التعبير في قوله تعالى: ﴿أَوْ أَشَدَّ ذِكْرًا﴾ بـ﴿أو﴾، أفي الأمر شك؟","answer":"﴿أو﴾ للإباحة أو بمعنى بل الانتقالية؛ أي اذكروا الله كذكركم آباءكم، بل أشد ذكرًا، وليس في الأمر شك.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص247–250، تحت البقرة: 200، في دلالة ﴿أو﴾.","url":""}]}]);
